import{C as e,L as t,V as n,_ as r,b as i,x as a}from"./vue-DJZSiPbu.js";import{r as o}from"./app-a38lz1Y_.js";var s=JSON.parse(`{"path":"/read/extra/E1.html","title":"1 最美好的名配角 | 阅读","lang":"zh-CN","frontmatter":{"title":"1 最美好的名配角","description":"「一旦没钱，自然也没有女人！」 （自称）统治初学者城镇阿克塞尔的小混混冒险者达斯特非常缺钱。 在新手冒险者和真他们逐渐提升名气的同时——达斯特不但自导自演诈欺来贩售赃物，还策划让贵族大小姐包养等等，想尽办法在阿克塞尔这座城镇赚钱！ 在这个情况下，他却从自己尊称为「老大」的大恶魔巴尼尔口中，得到了「你将迎向有趣的未来」这种不吉利的预言！ 由达斯特视角所展...","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"1 最美好的名配角\\",\\"image\\":[\\"\\"],\\"dateModified\\":null,\\"author\\":[]}"],["meta",{"property":"og:url","content":"https://ajtn123.github.io/konosuba/read/extra/E1.html"}],["meta",{"property":"og:site_name","content":"素晴"}],["meta",{"property":"og:title","content":"1 最美好的名配角"}],["meta",{"property":"og:description","content":"「一旦没钱，自然也没有女人！」 （自称）统治初学者城镇阿克塞尔的小混混冒险者达斯特非常缺钱。 在新手冒险者和真他们逐渐提升名气的同时——达斯特不但自导自演诈欺来贩售赃物，还策划让贵族大小姐包养等等，想尽办法在阿克塞尔这座城镇赚钱！ 在这个情况下，他却从自己尊称为「老大」的大恶魔巴尼尔口中，得到了「你将迎向有趣的未来」这种不吉利的预言！ 由达斯特视角所展..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:locale","content":"zh-CN"}]]},"readingTime":{"minutes":307.23,"words":92169},"git":{"createdTime":1784183213000},"autoDesc":true,"filePathRelative":"read/extra/E1.md","headers":[]}`),c={name:`E1.md`};function l(o,s,c,l,u,d){let f=n(`ImageView`);return t(),i(`div`,null,[s[0]||=r(`p`,null,`「一旦没钱，自然也没有女人！」`,-1),s[1]||=r(`p`,null,`（自称）统治初学者城镇阿克塞尔的小混混冒险者达斯特非常缺钱。`,-1),s[2]||=r(`p`,null,`在新手冒险者和真他们逐渐提升名气的同时——达斯特不但自导自演诈欺来贩售赃物，还策划让贵族大小姐包养等等，想尽办法在阿克塞尔这座城镇赚钱！`,-1),s[3]||=r(`p`,null,`在这个情况下，他却从自己尊称为「老大」的大恶魔巴尼尔口中，得到了「你将迎向有趣的未来」这种不吉利的预言！`,-1),s[4]||=r(`p`,null,`由达斯特视角所展开，有点色色的外传就从这里开始！`,-1),e(f,{src:`/images/E1/00.avif`,alt:`封面`,width:`850`,height:`1257`}),e(f,{src:`/images/E1/15.avif`,alt:`扉页`,width:`850`,height:`1257`}),s[5]||=r(`h2`,{id:`彩页`,tabindex:`-1`},[r(`a`,{class:`header-anchor`,href:`#彩页`},[r(`span`,null,`彩页`)])],-1),e(f,{src:`/images/E1/01.avif`,alt:`彩页插图 1`,width:`850`,height:`650`}),e(f,{src:`/images/E1/10.avif`,alt:`彩页插图 2`,width:`850`,height:`1591`}),e(f,{src:`/images/E1/04.avif`,alt:`角色介绍`,width:`850`,height:`1257`}),e(f,{src:`/images/E1/13.avif`,alt:`目录`,width:`850`,height:`1257`}),s[6]||=a(`<h2 id="序章" tabindex="-1"><a class="header-anchor" href="#序章"><span>序章</span></a></h2><p>「听好了，和真。你作为冒险者还不够成熟，就算运气好打败魔王军的干部，也不能因此得意忘形。这你应该懂吧？」</p><p>坐在冒险者公会酒吧的角落，我正在向新人冒险者——这个名为和真的男人讲述一介冒险者的心得。</p><p>这家伙明明还是新人，却跟伙伴一同打倒魔王军干部的无头骑士，是备受期待的新人。</p><p>虽然先前跟他起过冲突……不过那只是年少轻狂所犯下的错误，现在我们已经能相处得如此融洽了。</p><p>「我会这样讲可不是因为讨厌你喔，这是身为挚友的忠告。绝对不是看到你坐拥后宫才觉得嫉妒，你应该可以理解这点吧？」</p><p>我绝非器量如此狭小的男人，必须好好强调这点才行。</p><p>「我懂你要说什么，达斯特。但我们不是挚友，只不过是认识而已。」</p><p>「喂喂，别那么见外嘛，我跟你可是曾在昏暗的个人房共度过一晚耶。」</p><p>「不要用那种会让人误会的讲法！那是牢房吧！」</p><p>「但这么说也没错啊。」</p><p>我们明明就在牢房里热烈地交流过。</p><p>印象中，和真当时是因为炸燬了垃圾领主的宅邸，而遭到逮捕是吧？</p><p>「我也有亲眼看见喔！你们那时的确一起待在个人房里！」</p><p>「你不要挑最麻烦的时机出现啦，这个没用女神！」</p><p>那位从旁插嘴的女性，是有着清澈水蓝色头发的美女。</p><p>她的外表真的很美。但也只有外表就是了。</p><p>「你说谁是没用女神啊！我可是阿克西斯教徒们所信奉的女神阿库娅喔！」</p><p>「那是你的脑内设定。」</p><p>「真是可怜。」</p><p>这家伙是由于有着相同的名字就深信自己是女神，一个可怜的祭司。</p><p>这个「我可是女神」算是她独特的哏吧，不过每次都让人笑不出来。</p><p>真要说起来，光是身为世间评价成只会添乱的阿克西斯教徒就已经很有问题了，一般来说不会特地自称是该教团的女神吧。</p><p>我曾遇过阿克西斯教徒，但尽是些不听别人说话的家伙。说真的，我不想跟他们有太多牵扯。</p><p>伙伴们也说过想找祭司加入队伍，但只要一听到对方是阿克西斯教徒就会打退堂鼓。那群人就是如此危险。</p><p>「呐，为什么大家都不愿意相信我就是女神呢？」</p><p>「我说啊，这位祭司小姐。所谓神明是那种在天上守护人们的存在吧？应该也有很多事情等着祂们去处理，根本不会有那个闲情逸致降临到这个世界当冒险者吧？身为神明如果做出这种事情，那根本就是怠忽职守。」</p><p>「咳咳、咳咳！」</p><p>「克莉丝，你怎么了？为什么会突然咳了起来？难道说……这是硬把水挤进气管里的新玩法吗！」</p><p>「她又不是你，达克妮丝。」</p><p>坐在附近位子上的短发平胸女盗贼突然呛到，而和真的伙伴——十字骑士达克妮丝，则似乎正在关心（？）她。</p><p>在一旁边吃炸鸡边吐嘈的，则是脑袋有问题的爆裂女孩。虽然她看似受不了达克妮丝的言行，不过自己也一样病得不轻。</p><p>我记得她的名字是惠惠吧……红魔族为什么尽是取些奇怪的名字啊？</p><p>「女神也是会遇上各种状况啊！例如硬是被某个家里蹲带来这种地方！」</p><p>「阿库娅，不可能有这种事啦。身为女神大人却受到与物品同等的待遇，甚至因此坠落到这个世界上……这怎么可能会发生呢？」</p><p>露出温柔微笑将手放在阿库娅肩膀上的和真，以及被达克妮丝从背后架住，哭着正要动手揍向和真的阿库娅。</p><p>身为祭司，在听到女神被拿来开玩笑时，果然还是会生气呢。</p><p>被伙伴们安抚的祭司，以及继续激怒对方的和真。</p><p>看他们这样吵吵闹闹真的很有意思啊。真是的，这群人正是最适合新手冒险者城镇阿克塞尔的新人了。</p><p>趁着这群人在一旁吵得不可开交，从早上就什么都没吃的我找来店员随意点了些餐点。</p><p>当然，是由和真出钱。</p><h2 id="第一章-那段故事的另一侧" tabindex="-1"><a class="header-anchor" href="#第一章-那段故事的另一侧"><span>第一章 那段故事的另一侧</span></a></h2><h3 id="_1" tabindex="-1"><a class="header-anchor" href="#_1"><span>1</span></a></h3><p>这酒真是难喝。</p><p>虽然我跟平常一样在冒险者公会与伙伴们把酒言欢，但我的心情从刚刚就差到不行。</p><p>「咦？沙拉里面没有番茄耶，我明明那么喜欢番茄……怎么了？你为什么要皱着眉头啊？原本就长得不太好看了，摆出这个表情只会让你看起来像个小混混喔。」</p><p>我们队上唯一的女性琳恩停下翻搅沙拉的手，露出傻眼的表情看向我。</p><p>她身上披着蓝色斗篷，一头红发在后脑勺扎成马尾，脸上还残存着些许稚气。每当我看着琳恩时总会觉得……不，现在先不管这个。</p><p>「你说谁是小混混啊！啧，我只是觉得自从那些家伙来了之后，这座城镇待起来的感觉就变差了。」</p><p>「你说的『那些家伙』是指那群新人冒险者吗？」</p><p>即使人在酒吧依旧身穿铠甲的泰勒竖起拇指，朝后方比了两下。</p><p>在他指尖前方是个颇为软弱的黑发男性，带着三个好女人……真是令人火大的家伙。</p><p>队伍中跟我最合拍的弓手奇斯似乎也很在意，只见他嘴里叼着活跳跳的小黄瓜回头望去。</p><p>「他们应该就是在与魔王军干部贝尔迪亚战斗时最活跃的那群人吧。」</p><p>「似乎是这样。因为我太晚到现场了，所以不清楚详细情况。」</p><p>因为正好有别的事情，让我无法从头参与那场战斗，但还是听说了他们活跃的事迹。</p><p>「那一位不但挺身承受魔王军干部的攻击，面容也没有因疼痛而变得扭曲，甚至还对大家展露了笑容，完全就是十字骑士的榜样。」</p><p>同样身为十字骑士的泰勒大概有着相当的感触吧，只见他的眼神中充满了尊敬。</p><p>「那个红魔族的女孩也是，那道魔法的威力实在太强大了！我充分见识到她作为魔法师的水平跟我完全是不同等级。」</p><p>「那位水蓝色头发的大祭司所使出的水攻也是压倒性强大呢。」</p><p>奇斯正用色眯眯的视线盯着那个大祭司的屁股瞧。</p><p>那位水蓝色头发，双手握着扇子不知道在做什么的女人，虽然身为人人忌讳的阿克西斯教大祭司这点是有些美中不足，但只要能够忍受这个部分，她就是个顶级的美女。</p><p>而在这三个人的围绕下寻找工作的则是一名不起眼的男子。我最看不惯的，就是明明拥有实力坚强的伙伴们，却只会找些搬运行李之类工作的这个愚蠢男人。</p><p>「真要说起来，他竟然完全没有来跟掌管新手冒险者城镇阿克塞尔的我打招呼，这实在让人无法接受！」</p><p>「你说是谁在掌管城镇啊？别说掌管了，你根本是给城镇添麻烦的存在吧。」</p><p>泰勒一脸傻眼地开口吐嘈，但我没要搭理他。</p><p>奇斯跟琳恩似乎也想说些什么，但是我可不会跟他们对上眼。</p><p>「所有队友都是优秀的上级职业，还都是好女人，偏偏拥有这个后宫的却是最弱职业的冒险者！多么令人羡慕的轻松人生啊！」</p><p>为了让那家伙能听见，我刻意加大音量如此说道。</p><p>接着压抑着怒气看向这里的那个家伙——</p><h3 id="_2" tabindex="-1"><a class="header-anchor" href="#_2"><span>2</span></a></h3><p>太棒啦啊啊啊！那个笨蛋竟然答应跟我交换队员耶！</p><p>能刺激那个名为和真的最弱职业冒险者讲出对我有利的气话真是太好了。</p><p>虽说那家伙在交换队员时竟然面露喜色让我有些在意，但那应该只是在逞强吧。</p><p>我想，他肯定是因为怒上心头就忍不住说错话，又因为自尊心作祟而无法开口反悔吧。如果不是这个原因，他才不可能会愿意跟我交换这种一流的伙伴。</p><p>在冒险者公会的酒吧跟和真吵了一架后，他竟然非常干脆就答应跟我交换队伍成员。</p><p>那家伙该不会真的是个蠢蛋吧？即使只是暂时的，他居然愿意放弃这些上等的女人们。</p><p>她们不但都是上级职业，还全都是美女。即使其中一个的身体还在成长中有点可惜，但趁现在先把她弄到手也没有损失。</p><p>虽然跟和真约好只交换一天，但只要我在这三人面前好好表现，就有机会代替和真成为小队队员……不，这样不行，我可不能离开琳恩，不然邀请她们加入我们小队应该也行。</p><p>「呐，虽然刚刚是说要去消灭哥布林，但要不要去打倒更强的敌人啊？例如龙之类的！如果是由我们出手，肯定能轻松解决吧。」</p><p>这家伙在说什么啊？在公会时她也提过一样的事，她脑袋的螺丝该不会真的松掉了吧？从她充满自信地抬头挺胸说出这段话的模样看来，这个人应该是对自身实力有着相当的自信。</p><p>我记得这位个性强势的水蓝色头发大祭司好像叫阿库娅。</p><p>「这真是好主意！我一直想试着承受一次龙的吐息！全身沐浴在那灼热的气息之中，被烤得微焦……真是太棒了！」</p><p>这个十字骑士是认真的吗？就算是上级职业，要是正面挨上龙的吐息别说被烤焦了，根本就直达另一个世界了吧，还说什么要承受下来，这家伙到底是……</p><p>「呃，我刚刚也说过了，你为什么不带武器……甚至连铠甲都没穿啊？」</p><p>「我不是也回答过了吗？就算带了武器也砍不中，而且我的铠甲在跟魔王军干部的激战中坏掉了。」</p><p>「……虽然我实在是不想让步，但就算退个一百步先不提武器……没穿铠甲的前锋相当危险吧。」</p><p>「放心吧，孱弱的攻击根本无法对我造成伤害！而且如果是跟哥布林战斗，没穿铠甲反而还比较省事！」</p><p>省事……省什么事啊？</p><p>这家伙为什么会双眼湿润、脸颊泛红，就连呼吸也变得粗重？应该只是因为战斗前情绪显得高昂对吧……只是这样对吧……？</p><p>毕竟她能够承受魔王军干部的攻击，面对哥布林这点程度的敌人，即使没穿铠甲也不会有问题……就当成是这样吧。</p><p>「要去讨伐龙吗，我赞成。龙那身用来守护自己的坚固鳞片，就靠我的爆裂魔法粉碎给你们看吧！」</p><p>这个甩动斗篷并高举魔杖的小女孩，是红魔族的大法师。</p><p>所谓红魔族，是以庞大的魔力及奇怪的命名品味闻名的一族。我记得她的名字是惠惠……从这个搞笑的名字判断，她肯定是红魔族。</p><p>「不、不是啦，我先前也说过了，如果是你们或许真的能打赢，但我的能力还不足以挑战龙，所以很抱歉，能请你们接受驱除哥布林的任务吗？」</p><p>而且……我实在不想跟龙战斗，可以的话绝对要避免这种事。</p><p>「这样就没办法了～～我原本是想打倒强大的魔物让和真好好见识一下，但也只好特别配合你的实力了，你要好好感谢我喔。」</p><p>「说的也是。虽然我也想改变和真对我们的看法呢。」</p><p>「算了，就先这样好了。之后再找机会成为屠龙者吧。」</p><p>从这股完全不觉得自己会败北的自信看来，她们果然都拥有相当的实力。无论怎么想，这三个人都是最弱职业的冒险者配不上的队员。</p><p>「我说啊，为什么你们会跟那个最弱职业的家伙组队呢？你们身为上级职业，想找队员的话根本可以任君挑选吧。」</p><p>「呃，那是因为……我没办法放着那个家里蹲不管啊！」</p><p>「没、没错，绝对不是因为被其他冒险者拒绝，完全没有队伍愿意让我加入喔！」</p><p>「是、是啊。不是因为组队过一次的人哭喊着『拜托饶了我吧』并拒绝我喔，绝对不是。只是因为听说有位个性极度恶劣的冒险者在虐待两名柔弱女性，才会想说务必让我加入……好就近监视，别让他做出傻事罢了。」</p><p>「哦～～嗯，说的也是，这样我就能理解你们为何要跟人渣组队了。」</p><p>毕竟无论再怎么想，最格格不入的就只有最弱职业的和真了。</p><p>但如果是因为怜悯及监视，那就能够理解。</p><p>「没错，明明是我们比较厉害，根本不该听从那个区区家里蹲自以为是地下的命令啊！他应该要更尊敬、更宠我们才对！」</p><p>「就是说啊，我也觉得他应该要再更重视我们一点才对！」</p><p>「和真就是太小看我们了。要趁这次机会让他知道我们有多重要。」</p><p>在看见她们愤恨不平的模样后，我开始觉得可以挖角到她们。</p><p>今天就让她们见识见识我帅气的一面吧。啊，对了，有件事情得先跟她们确认才行。</p><p>「这么说来，可以让我确认一下你们的技能吗？姑且先稍微了解一下会比较好吧。」</p><p>「我会使用宴会才艺技能以及大祭司的所有技能，最拿手的是花鸟风月。」</p><p>「宴会才艺……是、是吗……能使用大祭司的所有技能还真是厉害！」</p><p>即使学会大祭司所有的技能，也还有剩余点数能拿去学宴会才艺啊……她可能是超越我想像的逸才呢。</p><p>「吾乃惠惠！职业乃大法师，使用的乃是最强攻击魔法，爆裂魔法！」</p><p>「喔、喔喔。我已经听过你的名字了，不过你能使用爆裂魔法啊！这也太厉害了！」</p><p>她应该跟名叫阿库娅的大祭司一样，先取得某种程度的魔法后才学习爆裂魔法吧。这么一来，她肯定拥有相当的实力。</p><p>不可能会有那种完全不学其他魔法，就选择先习得爆裂魔法的笨蛋吧。</p><p>毕竟能一口气清光魔王军干部所召唤出来的部下，那股威力根本不容置疑。这时候应该要捧她一下让她高兴吧。</p><p>「竟然可以跟能使用爆裂魔法的魔法师组队，这实在太棒了！之后我一定要跟伙伴们好好炫耀一番！」</p><p>「看来你是个懂得爆裂魔法有多棒的厉害人物呢。已经离城镇够远了，即使在这里使用也不会挨骂，就让你见识一下吾之魔法吧！」</p><p>「咦？」</p><p>这个人……到底是在说什么啊？如果在这种毫无遮蔽可言的平原上投下爆裂魔法，魔物们将会被爆炸声吸引过来耶。她是在开玩笑的吧？</p><p>正当我面露苦笑时，眼前却出现了往魔杖前端聚集的庞大魔力。</p>`,126),e(f,{src:`/images/E1/11.avif`,alt:`插图`,width:`850`,height:`1206`}),s[7]||=a(`<p>有如火花般的东西四处飞散，这股刺肤的压迫感……她是认真的？</p><p>「喂，等等！快住——」</p><p>「『Explosion』！」</p><p>我的制止被惠惠施放的魔法、暴风以及爆焰，还有爆炸声覆盖过去……唔喔喔喔喔！</p><p>「啊啊啊啊！快、快趴下啊啊啊啊！」</p><p>为了尽量降低往这里袭击而来的暴风所带来的影响，我卧倒在地。然而那名十字骑士却若无其事地站在原地。</p><p>大祭司则是双手抱膝坐在十字骑士身后打着呵欠。</p><p>这未免太奇怪了吧！在场的竟然只有我感到害怕……这群人到底是怎么回事啊？</p><p>我在暴风止歇后战战兢兢地起身，就看到平原上形成一个巨大的洼地。</p><p>「真的假的……我从来没看过这种威力的魔法……」</p><p>「吾之爆裂魔法的威力如何？」</p><p>我看向用骄傲的语气发问的大法师……却发现她趴倒在地面上。</p><p>「喂，你为什么躺在地上？」</p><p>「因为我的魔力用光了……」</p><p>「啥啊啊啊啊啊！咦？你只使出一次魔法就用尽魔力了吗？开什么玩笑啊！」</p><p>一发爆裂魔法就会用尽魔力的魔法师根本毫无价值可言！</p><p>「为什么明明没有敌人你却击出魔法？我完全无法理解耶！」</p><p>「爆裂魔法本来就是在情绪高涨时施展的东西啊，外行人就是这样才令人困扰。」</p><p>「别慌张，这是常有的事。」</p><p>「竟然说我是外行人！队伍的魔法师就这样变成废物了耶，你们也慌张一下吧——！」</p><p>「一一计较已经过去的事情可是会秃头喔。啊，快看快看，远方有某些东西正在往这边跑过来了喔。」</p><p>这群人为什么还能这么悠哉啊！</p><p>啊啊，够了，不要拉我的衣服，你是小孩子吗？反正朝这边跑过来的肯定是听见爆炸声的冒险者或卫兵吧。</p><p>「看起来好像是有着黑色毛皮用四脚行走的野兽……那完全就是充满野性的兽行呢。」</p><p>「黑色野兽？」</p><p>完全只有不祥的预感耶。于是我眯起眼睛凝视前方。</p><p>那是全身覆盖着黑色毛皮的猫科野兽，嘴边还露出两颗巨大的獠牙……咦？喂喂！</p><p>「那不是初学者杀手吗！快、快快、快逃啊！」</p><p>它应该是被爆炸声吸引过来的吧！在带着累赘的情况下战斗会有危险！</p><p>就在我背起气力用尽，完全派不上用场的魔法师准备逃跑时——</p><p>「那就是初学者杀手吗！我一直想跟它较量一次看看耶！你的剑借我一下！」</p><p>「喂，等等！那是我重要的——」</p><p>十字骑士夺走了我的剑之后就朝敌人飞奔而去，那个笨蛋到底在想什么！</p><p>初学者杀手是会将哥布林或狗头人那种弱小怪当成诱饵，然后反过来狩猎人类的，既狡猾危险度又高的魔物。以这个充满上级职业的队伍来说，原本应该是打得赢的对手……但从她们目前的言行来看，我只有不祥的预感。</p><p>「上啊！达克妮丝，这时就是要给它一拳！」</p><p>不要跟着起哄啊！这个该死的祭司！而且比起声援，好歹也放个支持魔法吧！</p><p>「吃我一刀！」</p><p>毫不犹豫冲上前挥剑的十字骑士的攻击完全落空。</p><p>并不是初学者杀手躲开了攻击，而是那家伙自己朝空无一物的地方挥下长剑。虽然她立刻举剑再次挥出攻击……但还是豪迈地挥空。</p><p>「喂，那是怎样……」</p><p>我问了问背上的爆裂女孩后，得到了相当确切的答案——</p><p>「先前不就说过了，达克妮丝在防御上坚若磐石，但她的攻击绝对无法命中敌人。」</p><p>所以她才会说不需要带武器吗！</p><p>攻击打不中敌人的十字骑士……对着没敌人的平原发了一记魔法就变成废物的爆裂女孩。</p><p>……现在就绝望还太早了！那名大祭司应该有着货真价实的能力。我必须借助她的支持魔法之力，在十字骑士被打倒前做些什么才行！</p><p>「这还真是相当刁钻的攻击呢！」</p><p>咦……那个十字骑士明明没有穿铠甲，却可以承受初学者杀手的攻击？</p><p>光是衣服变得破破烂烂，本人却神采奕奕这点就已经够奇怪了，她的表情看起来还相当高兴，更是让我难以理解……应该说我不想理解。</p><p>而且她还把我的剑丢在一旁，徒手跟初学者杀手打了起来。</p><p>「这家伙打算就这样把我压倒在地上，对我发泄它的兽欲吗！被非人的野兽蹂躏我细致的肌肤……唔唔唔唔！」</p><p>能若无其事承受那种攻击，算是哪门子的细致肌肤啊？</p><p>虽然初学者杀手正咬住扭动身子的达克妮丝的肩膀，不过应该是我的错觉吧，总觉得它似乎面露怯色。</p><p>……但就算真是我的错觉好了，那位十字骑士明明被咬住肩膀，却没有露出丝毫痛苦的神情究竟是怎么回事？究竟为什么还能露出那样灿烂的笑容啊！</p><p>到了这一刻我终于懂了，总算明白了。这群人……根本不正常！全都是些脑袋有问题的家伙！和真当时会摆出强迫推销的态度，积极接受我的交涉的原因，我完～～全可以理解了！</p><p>「快流着口水，越发激烈地咬我吧！接着将我的衣服全都撕碎，一点一点将试图抵抗的我逼入绝境，再将一柱擎天的……这真是太棒了！呼啊啊啊啊啊！」</p><p>十字骑士在发出奇怪叫声后翻起白眼昏厥过去。虽然我警戒着初学者杀手会不会就此痛下杀手，但它却是松口向后退开。</p><p>那个初学者杀手竟然……？它是被那股难以言喻的气魄及异常的状况吓到了吗？</p><p>先、先不要管理由了，敌人退却的现在正是我们的好机会！</p><p>「你们几个，要逃走喽！」</p><p>「别开玩笑了，如果能打倒初学者杀手，和真不但会对我们改观，到时候不管要他请两杯，甚至十杯唰唰他都会跪着乖乖照办！吃下女神的这一击吧，神光拳！」</p><p>「你疯了吗！为什么要在这个时间点跑去攻击啊！」</p><p>在大祭司的拳头打中目标前，她就因为踩到初学者杀手先前咬着十字骑士时所流下的唾液向前滑倒。</p><p>由于架势完全垮掉，使得水蓝色头发的脑袋就这样滑到初学者杀手面前，而它也毫不犹豫地咬了下去。</p><p>「啊啊啊啊啊啊！被咬住了，我会被吃掉啊啊～～！」</p><p>大祭司明明被狠狠咬住脑袋却显得相当从容。是因为初学者杀手刚刚在咬坚硬的十字骑士时咬过头，使得它下颚的力道减弱了吗？</p><p>「快点放开我啦！想要美味地享用女神，可是会遭天谴喔！那个，再这样下去真的不太妙，所以说……拜托谁来救救我啊！和真先生！」</p><p>她看起来似乎还能忍受，但也不能就这样丢着不管。</p><p>我将背上的爆裂女孩以脸部朝下的姿势丢在地上，接着捡起她拿在手上的魔杖。</p><p>「这样我不就什么都看不见了吗！至少把我的头朝向那里吧。」</p><p>虽然她对于脚朝向这边的状态颇有微词，但我完全是故意的。</p><p>十字骑士昏厥中，吵吵闹闹的祭司正抓着敌人的下颚挣扎没有看向这里。</p><p>「如果是用魔杖应该就不算数吧。」</p><p>我压低重心轻轻挥几下魔杖做确认。虽然跟长枪不同，但如果是面对初学者杀手应该不会有问题！</p><p>总算赶跑初学者杀手后，我背起动弹不得的魔法师，设法安抚泣不成声的祭司，并让她背起翻白眼昏厥中的十字骑士……费了好一番功夫才总算回到公会。</p><p>到底是谁讲出后宫这种话啊……如果能回到那个时候，我真想尽全力对自己挥下一记加上助跑的拳头！</p><p>好累，身心都残破不堪了……这可是我人生中第一次因为冒险累成这样耶。</p><p>那些家伙还没回来吗？等他们回来之后，我有一件非做不可的事情。</p><p>「——今天有种经历了一场大冒险的感觉呢！」</p><p>我听见琳恩高兴的声音从门扉的另一侧传来。</p><p>相较之下我们却是这副惨状。</p><p>「呜呜……抽噎……」</p><p>动弹不得的两人再加上啜泣声。</p><p>等那家伙把门打开……我就要为了自己的失敬向他道歉，并求他把伙伴还给我！</p><p>为了达成这点无论要我下跪还是怎样都无所谓！</p><h2 id="第二章-为你献上那柄魔剑" tabindex="-1"><a class="header-anchor" href="#第二章-为你献上那柄魔剑"><span>第二章 为你献上那柄魔剑</span></a></h2><h3 id="_1-1" tabindex="-1"><a class="header-anchor" href="#_1-1"><span>1</span></a></h3><p>我的名字是达斯特。</p><p>是在新手冒险者城镇阿克塞尔中……类似掌管整个城镇的存在。</p><p>虽然今天看起来也像是漫无目的地在城镇中闲晃，但我其实是为了维持城镇治安，而在四处巡逻。</p><p>「你好啊，今天过得如何？」</p><p>像这样爽朗地跟居民们对话也是非常重要的事。</p><p>为了让大家从平时就对我抱持亲切感，我都会主动搭话。身为这座城镇的代表，这可以说是理所当然的义务。</p><p>「呃，是达斯特喔。拿来撒的盐巴放在哪里啊？今天可没有卖剩的东西！重点是你先前的欠款呢？」</p><p>杂货店的老板一看到我就露出厌恶的表情开始找碴。</p><p>「喂喂，那只是我免费接收了瑕疵品好吗，不如说我还想跟你收东西坏掉的补偿耶！真要讲起来东西坏掉时的碎片可是让我受了伤，你还要给我治疗费吧？另外心灵受到伤害的精神赔偿也顺便……不要用全力朝我身上撒盐啦！」</p><p>大叔老板毫不留情地一把抓起盐巴往我身上砸。</p><p>这个家伙，不要浪费食物啊！</p><p>「呸呸！可恶，盐巴跑进鼻子里了！」</p><p>「反正你这个穷光蛋也没办法好好吃饭吧？能摄取珍贵的盐分不是很好吗！而且你还敢跟我提赔偿？我明明就提醒过那个已经坏掉了，到底是谁强行把东西拿走的啊？」</p><p>「啊～～我不记得了～～你有能证明自己那样说过的证据吗？啊啊啊？如果你有证据我可以立刻向你道歉喔！但是如果没有证据我就绝对不会道歉！」</p><p>大叔在我的威胁下向后退了一步。</p><p>哼，想向我这个高超冒险者达斯特大爷找碴，你还早了十年啦。</p><p>「喂，如果你想赔不是就把该给的东西拿出来啊！如果没有要给，就把至今为止的欠款一笔勾销啊！无论你选哪一种我都无所谓！咳噗！」</p><p>就在我确定将赢得胜利的瞬间，双眼突然冒出了金星。</p><p>由于头顶突然传来强烈剧痛，害我慌忙回过头，接着就看到琳恩正皱起眉头瞪着我。</p><p>「你干嘛啦！很痛耶！」</p><p>「还敢问我！你是那种不到处给人添麻烦就活不下去的存在吗？不跟人呛声就会死吗？给别人添麻烦是你的兴趣吗？」</p><p>「我只是在对他述说为人之道而已。」</p><p>「啥？这种话轮得到偏离正途迷失正轨的达斯特来说吗？这比阿克西斯教徒说不要给人添麻烦还缺乏说服力耶。如果是跟冒险者起冲突也就算了，你可以不要给市民们添麻烦吗？啊啊——真是的，全身都是酒臭味，你又从大白天就开始喝酒了吧。」</p><p>「哼，要是不喝谁受得了啊。那时候本来应该要来个三才对，那家伙肯定是出老千啦。」</p><p>光是回想起来就让人火大。今天原本预计要在平常光顾的赌场靠我精心准备的老千战术取胜，所以把所有家产都带去了。</p><p>因为实在太不爽，忍不住顺势推了对方一把就被禁止出入，现在还落得这个下场。</p><p>「你有好好洗澡吗？竟然全身上下都是头皮屑，你不要靠近我喔。」</p><p>「这是盐巴啦，盐巴！」</p><p>「哪有把盐巴撒到头上的笨蛋啊？」</p><p>虽然我恶狠狠地瞪向大叔，他却摆出事不关己的态度。</p><p>……这位大叔还真有种啊。</p><p>「小琳，你真是帮了我大忙。如果可以顺便带这个小混混去冒险，然后让他变成魔物的饲料就更好了。现在的他有着刚刚好的盐味，魔物们应该也会很高兴吧。」</p><p>「真是不好意思，虽然我们也想出去冒险，但是魔王军干部似乎搬进了附近的古城，公会因此提出警告，导致我们无法外出冒险。」</p><p>「所以这几天街上的冒险者才会这么多啊，这可真是麻烦。」</p><p>「干部什么的跑来这种新手冒险者城镇做什么啊，可以学会什么叫察言观色吗？就是因为这样，才会在魔王军那种阴沉沉的地方工作啦。算了，等干部真的攻打过来，就由我达斯特大爷出面解决吧！」</p><p>我举起拇指指着自己，同时露出得意的笑容。</p><p>如果是在这座城镇，我有实力能在冒险者当中名列前茅的自信。</p><p>「哈！除了恐吓敲诈没有其他特技的你能干嘛啊？快去找敌人单挑然后被痛打一顿吧。」</p><p>这家伙竟敢嘲笑我，这位大叔根本就不知道我的实力吧。</p><p>「很好，就让你用身体来感受我的实力吧。好好品尝这记薄盐口味的拳头！」</p><p>正当我将指头折得喀喀作响并往大叔走去时……我的头顶再度传来一阵剧痛。</p><p>「不要随便出手揍我，要是把我打成笨蛋你要怎么赔啊！」</p><p>「反正也不会比现在更糟了，真的拜托你收敛点吧。小心又被抓起来关进牢里喔。我可不会再去把你保出来了。拜你所赐，我最近变得只要露脸就可以走进拘留所了耶！」</p><p>「喔喔，那阵子真的是受你照顾了，下次也拜托喽……警察啊，因为住宿费也花光了，加上还会提供餐点，去牢房给他们关照一下感觉也不错。」</p><p>虽然牢房住起来相当煞风景，但是遮风避雨又提供三餐还能午睡。</p><p>干脆找间店进去白吃白喝，顺便找店员麻烦，就能跟平常一样有地方睡觉了。</p><p>「我绝对不会再借你钱了。大叔，要是达斯特做出奇怪的行为，就立刻通知警察。毕竟他们也已经习惯了，应该会二话不说就直接把他带走吧。」</p><p>「竟然连警察都已经习惯了……你啊……」</p><p>大叔的眼神从藐视升级成怜悯了。不，应该是降级吧。</p><p>毕竟警察局的牢房就跟我的别墅一样啊。只要这些家伙也经历过一次，就会知道那里其实意外舒适。</p><p>「达斯特也不要再做傻事，好好找个工作吧。就算不能去冒险，也还有打杂之类的工作能做啊，你的体力应该相当不错吧。」</p><p>「事到如今我可不打算再去做搬货之类的杂工了。但如果有打扮煽情的漂亮大姊姊一直在旁边帮忙加油的话，我也是可以去试试啦。」</p><p>明明是为了做自己喜欢的事情才成为冒险者，谁还要做那种麻烦事啊。</p><p>没错，我已经下定决心要自由自在地生活，只做我想做的事情了。</p><p>「唉……真希望你能跟御剑先生稍微学习一下。」</p><p>「御剑？那是谁啊？」</p><p>听见琳恩突然说出男人的名字，让我直接做出反应。</p><p>而且她的语气中还对那家伙抱持相当的敬意。</p><p>「是最近变得相当有名的人，好像是勇者候补之一，持有一把厉害魔剑的型男剑士，为人有礼而且实力高超，很多人都对他抱持憧憬……话说回来，你已经不记得了吗？你之前不是喝醉跑去找碴，结果反而被人家痛殴一顿吗？就是那个上级职业的剑术大师啊。」</p><p>「那个人有时会来我店里光顾，是个非常有礼的好客人呢……跟某个人完全不一样。」</p><p>啊～～是那个带着两个可爱女孩的后宫男啊。实力乱强一把的该死外挂男。虽然想起来了，不过我的原则是对自己不利的事情就该全都忘记！</p><p>「哼，谁会记得啊！像那种圣人君子般的家伙，其实内心都很黑啦。表面上温文儒雅的家伙都不是什么好东西，再加上型男的性格都很恶劣，早就是世间的定论了。」</p><p>「虽然你讲得好像有看过那种人，但那根本就是没人爱的男人在嫉妒吧，真是丢人。」</p><p>「你说谁没人爱啊！我常光顾的那间酒吧的大姊姊，在我有钱时就会对我百般奉承喔！」</p><p>「你说那种话都不会觉得空虚吗？」</p><p>「才不会！我才不是那种玻璃心。说到底，还是我这种表里如一的人最值得信任了。」</p><p>「如果表里都糟糕透顶就没任何意义了。」</p><p>「无论哪一面都是黑的有个屁用啊。」</p><p>可恶，这两个人在骂我的时候根本就一个鼻孔出气！</p><p>虽然很想反驳但战况实在不妙，今天我就先乖乖撤退吧。</p><p>「哈！随便你们怎么说吧！跟你们不一样，我还有别的事情要处理。」</p><p>像这样抛下一句话之后，我就快步扬长而去。</p><h3 id="_2-1" tabindex="-1"><a class="header-anchor" href="#_2-1"><span>2</span></a></h3><p>「受不了，感觉醉意都快退了。对上琳恩我就是拿她没辙耶。」</p><p>要是其他人我还能用强硬的态度蛮干到底，但只要看着那张脸我无论如何都……</p><p>「啊——不要再胡思乱想了。好啦，哪里能找到好女人呢？那种有着多到花不完的钱，身体又渴望着男人，而且还愿意无边无际纵容我的女人最棒了。」</p><p>正当我大摇大摆地走在路中央，就看到前方出现两个女人。分别是拿着长枪的战士美少女，以及腰际挂着短刀，像是盗贼的美少女。</p><p>只有两个女的啊，这时候不上前搭讪就太失礼了。</p><p>「今天总该轮到我坐旁边了！」</p><p>「这可不是由你来决定的事情。」</p><p>原本以为她们是伙伴，但看起来感情不太好呢。</p><p>算了，这种事情根本无所谓。不过这屁股还真是棒耶，要是有人穿着如此暴露还在我面前晃着屁股，那我的手也会忍不住……</p><p>「呀啊啊啊啊！你做什么！」</p><p>「这个家伙竟然摸了我的屁股！」</p><p>两人慌慌张张回过头，长得果然很正呢……咦？总觉得好像在哪见过这两个人……但既然想不起来应该就不重要吧。</p><p>「反正也不会少一块肉，让我摸又不会怎样。」</p><p>「垃圾！能摸我屁股的人只有响夜而已！」</p><p>「就是说啊！偏离人生正轨的醉汉才没有资格摸我呢！……呃，这家伙不就是先前在公会跑来找麻烦，结果被响夜痛打一顿的醉汉吗！」</p><p>啊～～她们是御剑的跟班啊！那家伙该不会在附近……看来是不在。那就拿她们代替御剑好好还一下当时的回礼吧。</p><p>「喂喂，还敢摆架子喔！我才不记得喝醉时发生的事呢！你们特别提起被我摸的过去是怎样……意思是你们不只想被摸还想被揉吗？真是拿你们没办法，既然都开口要求了，是男人就该好好回应才对。我会把你们的屁股揉到变形为止！好了，快把屁股露出来吧！」</p><p>「不要靠近我！小混混！」</p><p>我一边双手空抓一边逼近那两个女人，她们就一脸害怕地退后。像这样胁迫一脸厌恶的女性让我有些兴奋耶，我似乎能稍微理解坏人们的心情了。</p><p>「那家伙就是达斯特，那个小混混冒险者。」</p><p>「哇啊，真是可怜，那两个女孩被小混混缠上了。」</p><p>那群观众实在有够吵耶，都是这些大嗓门让人群开始往这边聚集了。</p><p>虽然我不是认真想做到那种程度，但事到如今也无法收手，就再稍微纠缠她们一下吧。</p><p>「不、不要靠近我，变态！响夜！响夜——！」</p><p>「救救我，响夜！」</p><p>「嘿嘿嘿，就算你们哭着叫破喉咙也不会有人来啦！就让我好好享受你们美妙的惨叫声吧！嘻嘻嘻嘻！」</p><p>啊，总觉得越来越好玩了。</p><p>我继续朝坐倒在地眼泛泪光的少女们逼近，来到距离她们只差一步的地方。</p><p>「住手，你想对我的伙伴们做什么！」</p><p>「响夜！」</p><p>在最巧妙的时刻闯进来的是一个帅到让人不爽的型男。一头褐色的头发，身穿看起来就贵到爆炸，还闪着蓝色光芒的铠甲，腰际更挂着一把黑鞘之剑。</p><p>这家伙依然是一副有钱人的打扮耶。铠甲已经相当不得了，那把剑感觉更是高档。琳恩似乎有提过关于那把剑的事情，但谁会去记住那么琐碎的东西啊。</p><p>「你是谁？」</p><p>「哈！白马王子登场啦。难道你不知道在询问别人的名字之前，要先报上自己名号这个常识吗？还有，在阿克塞尔报上名号的同时，给予对方金钱可是基本礼仪啊！」</p><p>「要给钱？是类似外国那种小费制度的独特体系吗……毕竟是异世界，所以无法一概断言没这回事呢。」</p><p>哦，他因为我胡扯的事情在认真烦恼耶。这家伙是那种个性认真又不谙世事的蠢蛋吗？</p><p>「响夜，不要被骗了！根本没有那种规则！真要说起来，那种小混混说的话根本没有倾听的价值。」</p><p>「这么说也对。啊——虽然我很想说『恶人不需要知道我的名号』……不过这次就算了。我名叫御剑响夜，你的名字是？」</p><p>这家伙竟然那么有礼貌地重新报上名号。到底该说他很机灵，还是单纯就是个笨蛋？</p><p>与其说他是在小看我，不如说正因为对自己的实力很有自信，才能那么从容应对。</p><p>「你就把耳朵掏干净仔细听好了，我的名字是达斯特，是这座城镇众所皆知的冒险者！」</p><p>「这么说也没错啦，不过是恶名昭彰。」</p><p>「又是那个小混混冒险者在做蠢事啊。谁快去把警察或是他的监护人小琳找来吧！」</p><p>这群观众真的是烦死了。只要我一引发骚动，这里的居民就会立刻聚集过来。</p><p>「嗯？我怎么觉得以前有在哪里见过你？」</p><p>「他就是之前在公会跑来找碴的醉鬼小混混！那张色眯眯的脸我想忘也忘不了。看那一脸色相就肯定是他！因为是那种不受女生欢迎的长相所以我还记得！」</p><p>「看他那张脸肯定是脑中几乎都塞满下流的事情！那对眼睛跟嘴巴看起来就像罪犯！他肯定是偷窥跟色狼的惯犯！而且总觉得很臭！」</p><p>「这跟长相无关吧！还有很臭是怎样，我身上明明就散发着花香！要是再不适可而止，即使是我也会哭喔！」</p><p>这群可恶的女人，竟然这样信口开河。</p><p>「啊啊！我想起来了。所以你又想被我揍得满地找牙了吗？」</p><p>竟然露出那种从容的笑容，这家伙真的让人很火大。</p><p>可恶，都是因为这个型男不请自来，害得事情变得很麻烦。因为跟他交手过所以很清楚，这家伙的实力相当高超，确实有着符合他高等级的强大身体能力。</p><p>在酒醉的情况下对上他实在有些不妙，这种时候还是在发生进一步冲突前先战略性撤退好了。绝对不是因为我打不赢喔！</p><p>「唔！我的肚子突然痛起来了，今天就先放过你吧！我可不是逃跑啊，给我记牢了！」</p><p>我在撂下招牌台词后就转身离开现场。这可不是逃跑，只是因为一旦被琳恩知道，她就不会再借钱给我了，这样会让我很困扰！</p><h3 id="_3" tabindex="-1"><a class="header-anchor" href="#_3"><span>3</span></a></h3><p>在那之后虽然已经过了好几天，但我就是无法接受。</p><p>最近有被其他冒险者以及伙伴们看扁的趋势啊，是时候该让他们见识我究竟有多么伟大了。毕竟从事冒险者这个职业，一旦被看扁那一切都结束了。</p><p>加上还有先前被痛扁的怨恨没解决，我看就先从那个型男开始下手吧。</p><p>这只是为了让世人了解我真正的实力，并不是因为我个人讨厌型男。也不是因为我很羡慕那家伙带着两个那种等级的美女喔。</p><p>这终究只是前辈冒险者对晚辈的教育罢了。</p><p>「话是这么说，该怎么做好呢？」</p><p>我想不出任何能让那个型男屈服的方法。如果有那种不但能表现出我的伟大，又能让对方哭着求饶的发展就好了。</p><p>「喂。」</p><p>「以目前的状态看来，要靠蛮力让他屈服实在有点困难。」</p><p>「喂。」</p><p>「果然得靠头脑吧。毕竟都说知性的男人充满魅力。」</p><p>「喂——！不要在别人放在店门口贩卖的椅子上坐着不走！也不要擅自翻阅作为商品贩售的书籍啊！」</p><p>「吵死了，好歹也端杯茶出来啊，我可是客人耶。不然拿杯酒来也是可以喔。」</p><p>我明明就是在杂货店前沉思，竟然这样大吼大叫妨碍我，这间店对客人的态度真是糟透了，到底懂不懂什么叫服务业啊？</p><p>「看来有必要由我从头指导你待客的基础呢。首先是要爽快地把酒、下酒菜还有玩乐的钱交出来。」</p><p>「所谓的客人是会付钱的对象。你就只是个累赘、垃圾、达斯特。」</p><p>「你这家伙！要是继续因为我为人厚道就这样得意忘形，我就要在附近散布负评喔！这里的老板明明因为赌博欠下一屁股债，还大白天就疯狂灌酒，四处找女人搭讪！」</p><p>「那是你的日常生活吧！而且如果你那叫为人厚道，那我就是类似神明的存在了吧？」</p><p>「哼，还真敢讲。我才没空理会大叔你这种闲人呢，我得让大家知道，那个叫响夜的型男跟我比起来，究竟是谁的地位比较高。」</p><p>「响夜？哦，是指御剑先生啊。那种事情根本连比都不用比吧。这就跟是拿无头骑士及僵尸，或是拿艾莉丝教徒及阿克西斯教徒相比一样失礼耶。」</p><p>不论是谁都一个样，每个家伙都只会对型男阿谀奉承。看人是要看内在好吗，内在！</p><p>「对了，说到御剑先生……先前有人来推销一把新人冒险者无法使用的剑，那把剑的外观跟御剑先生的剑很相似呢。虽然重得离谱剑锋又很钝，但想说可以当成装饰品或室内装潢的一环，我还是收购下来了。」</p><p>「砍不了东西的剑除了当装饰之外根本没用吧。」</p><p>「呃，我是收到哪里去了。喔，找到了找到了，就是这把。」</p><p>老板应该也很闲吧。明明就是跑来找碴，却又像这样跟我聊起天来。</p><p>他从店内拖出来的那把剑似乎真的很重，剑尖跟地板一路摩擦。</p><p>这把剑的确跟御剑那把非常相似。与其说相似……根本是同一把剑吧？</p><p>无论是外型还是剑本身所散发的魄力，都不是作为装饰品应有的等级。至于钝到砍不了东西这点，可能是因为用魔法动了手脚，或是设定了某种条件。</p><p>……咦？这么说来琳恩好像有说过御剑持有魔剑吧？我先前曾经听说过，所谓魔剑依照种类……也有那种除了获选之人外无法使用的东西耶。</p><p>要是只有御剑才能使用的剑，对其他人来说就毫无价值。没错，除了御剑本人以外。也就是说……我想到了一个连自己都觉得超棒的点子。</p><p>「喂，大叔，那把剑我买了。」</p><p>「啥？你愿意买下派不上用场的剑我是很高兴啦，但你根本没有钱吧。如果你真的出得起这笔钱，那你就先把欠款结清。」</p><p>「你等我一下，我手边有一顶以前常用，但现在用不到的头盔，你就收购下来吧。那个可是相当值钱喔。」</p><p>「值钱啊……你之前也用过这种手段，打算把从垃圾场捡来东西卖给我吧？」</p><p>「这次是真货啦。你等一下，我这就去把东西拿来。」</p><p>只要待在这座城镇，我就不需要用头盔遮住脸，就算卖掉也不成问题吧。</p><p>反正那顶头盔因为很不通风，戴起来很闷热，最近也完全没在用了。</p><h3 id="_4" tabindex="-1"><a class="header-anchor" href="#_4"><span>4</span></a></h3><p>「这顶头盔虽然看起来简陋，但做工却相当精细……这是个好东西耶。虽然的确足以抵押至今为止的欠款以及这把剑的金额……但这个应该不是赃物吧？」</p><p>老板在仔细研究我带来的头盔好一段时间之后，才总算给出了鉴定结果。</p><p>看来价格相当不错，如此一来就能实行我想到的计划了。</p><p>「我才不会去偷东西呢！所以说交涉成立，这东西就归我喽。」</p><p>「喔、喔喔，谢谢惠顾。」</p><p>很好，这么一来这笔买卖就成立了。只要握有这个，事情就会变得有趣。</p><p>「给我等一下～～！」</p><p>喊这么大声，是谁啊？</p><p>我一回头就看到一个双手扠腰，挺着胸膛的女人。因为她身穿修道服，应该是个祭司吧。虽然看上去就是个美女，但不知为何我却毫无兴趣。</p><p>她的眼神感觉就很危险。而且从那套修道服看来……是阿克西斯教徒啊。</p>`,263),e(f,{src:`/images/E1/09.avif`,alt:`插图`,width:`850`,height:`1206`}),s[8]||=a(`<p>根据传闻，阿克西斯教团是连魔王军都敬而远之的存在。虽然我觉得这个说法太过夸大，但他们的确是个众所皆知的麻烦集团。</p><p>这种人要找我干嘛？可以的话我实在不想跟他们扯上关系。</p><p>「这位大姊，你有什么事吗？想搭讪的话请晚一点再来，但如果是要请我吃饭，那我会乖乖跟你走喔。」</p><p>「以阿克西斯教的美女祭司闻名的我，怎么可能反过来搭讪你这种毫无金钱味的男人啊。不如说你应该要请我吃饭，这么一来我就愿意温柔地在你耳边讲述阿克西斯教的教义。」</p><p>「不需要。耳朵会烂掉。」</p><p>「竟然无法理解阿克西斯教美好的教诲，你真是个悲哀的存在。」</p><p>这么说来我的确没有仔细听过教义，反正那肯定不是什么正经的内容，听了也只是浪费时间而已。</p><p>「光是达斯特就很麻烦了，竟然连阿克西斯教的破戒僧都跑来，看来今天得关店了……」</p><p>大叔一脸沮丧地重重叹了口气。</p><p>先不提我，竟然能让大叔警戒到这种程度，看来这个女人相当恶劣呢。</p><p>「虽然浪费时间离题了，不过我的重点是那把剑。那不是我盯上的剑吗！这是那位实力高强的型男冒险者在用的魔剑对吧。自从我确认那把剑在这间店之后，我就日日夜夜待在这边监视，想看他会不会来把剑买回去！」</p><p>「你未免太恐怖了……」</p><p>这个祭司突然现身讲这什么鬼话啊。</p><p>这家伙所指的正是我才刚买下来的御剑的剑。从语气来判断，她似乎认识那个家伙。</p><p>「你是指御剑吗？如果是的话，你打算怎么样？」</p><p>「把剑免费让给我。那是该由阿克西斯教持有的东西。只要能取得那把魔剑，我就可以用它当成幌子威胁……说服他包养我，从此过着受他宠爱又吃饱睡睡饱吃的怠惰生活。我这次绝对不会再让他逃走了！」</p><p>要热烈地述说自己的决心是无所谓，但她的眼神完全被欲望污染了。我实在不想成为跟这种人一样的存在啊。</p><p>「虽然你好像有某种目的，但竟然要人把买来的东西平白送你？真是厚脸皮的女人啊。」</p><p>「这话轮不到你来说啦。」</p><p>虽然大叔似乎抱怨了些什么，但我没在听。</p><p>「虽然刚刚说免费，不过我当然会给你其他东西作为补偿。毕竟那个价格相当高昂，可以麻烦你在这张签收单上签名吗？」</p><p>「哦，如果是有利可图的东西，我就可以考虑看看。」</p><p>如果那东西的价值比魔剑的卖价还高，那让给她也无所谓。</p><p>跟笔一起递过来的那张纸——是阿克西斯教的入教申请书。</p><p>「开什么玩笑啊！这纸连拿来擦屁股都办不到！」</p><p>「太失礼了！入教申请书可是用对身体有益的材质做成的耶！」</p><p>「重点不在那里吧……」</p><p>一脸疲惫的大叔依然很认真地在吐嘈。</p><p>总觉得他今天一口气老了很多耶。</p><p>「无论如何，我不会把这把剑让给你。如果你真的想要就用钱解决，快拿钱来。」</p><p>「唔！竟然向我要求我最不擅长取得的钱财！这是何等贪婪的男人啊。我要向阿库娅女神祈祷，让你在明天早上口臭变得异常严重！」</p><p>不要许那种讨人厌的愿望！这家伙真的是祭司吗？虽然有听过传闻但这也太夸张了。</p><p>「你在这边等一下，我这就去从艾莉丝教徒那边诈骗金钱过来！」</p><p>「我会在这边等着，你就快点去筹钱吧。」</p><p>阿克西斯教的祭司一讲完就快步离去。</p><p>既然麻烦的女人离开了，那我就来确认一下东西吧。</p><p>我试着拿起刚刚买下的剑……好重。这样根本无法随意挥舞。</p><p>这果然是魔剑呢。这么一来，御剑那家伙无论如何都会设法取回吧。如、果、是、这、样，即使我喊个天价他应该也会爽快付钱喔。</p><p>「呵呵呵，太棒了，这样我就能轻松赚一笔啦。大叔，再见啦，这里已经没我的事了。」</p><p>「不要露出那种邪恶的笑容啊。喂，达斯特，你刚刚不是说要等她拿钱过来吗？」</p><p>「谁要等啊，那只是我用来赶跑她的借口。」</p><p>「你啊……」</p><p>虽然背后传来老板傻眼的声音，但我决定无视并直接离去。</p><p>预防万一，我要先来把这个藏起来，等一切都准备就绪再去找御剑。</p><p>至于究竟能诈取到多少钱，就要看我的本事了。</p><h3 id="_5" tabindex="-1"><a class="header-anchor" href="#_5"><span>5</span></a></h3><p>将魔剑藏到私下借用的仓库后，我就在街上闲晃试图寻找那家伙，没想到却先遇上在散步的琳恩。</p><p>「咦，达斯特？你找到工作了吗？」</p><p>「我没有找到工作，不过最近应该会有一大笔钱入帐喔。」</p><p>「你没有做什么奇怪的事情吧？我不想再去警察那边保你出来了喔。最近甚至被记住长相，连新来的警官都边敬礼对我说『真是辛苦你了』耶！真的是有够丢脸！」</p><p>「那还真是辛苦你了。放心吧，那不是什么犯罪行为，反而该说是慈善事业。」</p><p>当我抬头挺胸回答后，琳恩就用冷漠的眼神盯着我。</p><p>看来她完全不相信我的说词。</p><p>「我说的是真的啦，是在帮人找东西。对方会很高兴，我也能拿到报酬。你不觉得这算得上是互相帮助的美好关系吗？」</p><p>「太可疑了，我打心底觉得可疑。那绝对不是什么正经差事吧……我知道了，那我跟你一起去。如果没有任何问题，我一起去应该也没差吧？」</p><p>唔，事态开始往奇怪的方向发展了。</p><p>这时候我应该要尽可能蒙混过去，但在面对琳恩时，我的谎话不知为何都不管用。如果只是随口说说，她绝对不会相信。</p><p>「喔，是无所谓啊。反正也不是什么亏心事。」</p><p>我冷静地思考了一下，这件事不但不违法，而且还是正当交易，所以应该没差吧。没有任何会被琳恩责备的事。</p><p>就在我带着琳恩走来走去寻找那家伙时，便看见一个慌慌张张地四处乱窜的家伙。那个人是……御剑啊。</p><p>「那是御剑先生吧。他看起来很慌张耶，发生了什么事吗？」</p><p>太棒了，这时机真是刚刚好。虽然他看起来很忙，但还是稍微去跟他搭个话吧。</p><p>「喂～～看你那么慌张，是怎么了吗？」</p><p>「呼……呼……你是……那个时候的……呼……呼……有什么事吗？我现在很忙！」</p><p>满身大汗四处奔走的御剑心情似乎不太好。</p><p>看他慌张成这样……看来是中大奖了。</p><p>「你在大街上那么激动是怎么了？难道是看到美女大姊姊吗？哎呀～～你平常带在身边的剑是怎么啦～～？难不成～～你正在寻找魔剑吗？」</p><p>「为、为什么你会知道！」</p><p>BINGO，这家伙的表情跟态度都太明显了。这么容易被看穿，可是会被坏人抓住小辫子喔。</p><p>「天晓得。所以你找到魔剑了吗？」</p><p>「我找不到！你是知道这点才来跟我搭话的吧。」</p><p>「算是啦。所以说啊，如果那把魔剑现在在我手上，你会怎么做？」</p><p>「咦？」</p><p>「什……！为什么会在你手上？」</p><p>虽然琳恩也是捂着嘴吓了一跳，但跟御剑的反应相比根本不算什么。</p><p>他瞪大眼睛抓乱头发后就朝着我逼近，看来那把剑对他来说似乎相当重要。虽然他应该是那种不会说谎的类型，但真亏他这种个性的人有办法在这世间打磙耶。</p><p>是因为跟在他身边的女人意外能干吗？毕竟她们个性都挺好强的。</p><p>「御剑先生，请你稍等一下，我有话要跟这家伙说。达斯特，你过来这边！快过来！」</p><p>「喂喂，我现在正在进行重要的交涉耶。」</p><p>我一走到背对着御剑对我招手的琳恩身边，她就用手缠住我的脖子小声问道：</p><p>「立刻跟我说明这到底是怎么回事。」</p><p>「亲切的我在杂货店找到那柄魔剑后，就抢在其他人之前先买了下来。我人很好吧？」</p><p>「如果只是这样那的确不是什么坏事……但事情绝对没有那么简单……达斯特，我会跟你一起道歉，我们现在就去杂货店吧。趁现在应该还有一点被原谅的机会。」</p><p>「我又没有偷！我可是付了钱把东西买下来的。为什么每个人都在怀疑我偷东西啊！」</p><p>「除了你平时的言行以外，还会有别的原因吗？」</p><p>琳恩虽然瞪着我不断碎念，但这时候就先别管了吧。我现在正忙着跟御剑交涉耶。</p><p>「嘿，让你久等了。我碰巧在杂货店看到了一把剑，因为很中意就买下来了……结果完全是在浪费钱啊。那把剑重到根本无法使用，我还在想要不要拿去熔了好铸造新的剑呢。」</p><p>「等等，请你稍微等一下！要钱的话我付给你！」</p><p>很好，上钩了！看这个样子就算强硬敲上一笔他也愿意给。好啦，究竟该跟他开价多少呢？虽然是用头盔交换来的剑，不过杂货店开出的价格是十万艾莉丝。</p><p>进行这种交涉时，基本上都是先提出一个超夸张的金额，再来寻找双方的妥协点，所以最初就先来个……</p><p>「我想想喔，因为那把剑相当值钱，所以我最少也想拿到这个价格。」</p><p>我竖起五根手指，试着要求五百万艾莉丝。</p><p>「五百万吗？」</p><p>「等等，也太贵了吧！」</p><p>以便宜的金额买到手的魔剑来说这是相当夸张的价格。我要从这里开始慢慢降价，最后应该会落在一百万艾莉丝上下吧……</p><p>「我知道了！这就付给你吧！」</p><p>「话虽如此，我也不是恶鬼……啥啊啊啊啊？咦，你要付喔？」</p><p>「等等、等一下！不可以被他的花言巧语骗了！这家伙是那种只要开口大半都是谎言及粗话的男人喔，我这就给他一发魔法，让他乖乖说实话。」</p><p>「你到底是谁的伙伴啊！」</p><p>我对着举起魔杖准备魔法的琳恩发出怒吼。</p><p>不要妨碍伙伴做生意啦，只要拿到这一大笔钱，就能还清欠债耶。</p><p>「无所谓，反正不是付不起的金额。」</p><p>「你看，人家都这说了。所以立刻把魔杖放下来！不要再咏唱魔法了！」</p><p>「我觉得为了这个世界着想，最好还是把你烧了……」</p><p>这家伙真的会把魔法砸过来，先前吵架时她就是毫不留情地用魔法攻击过来。</p><p>「那这场交涉就算成立了。啊，想稍微打个折也可以喔。不然再附加上我的旧钱包吧，虽然里面是空的。」</p><p>「不、不了，这样就行了。那是那一位赐予我的魔剑，光是给剑标价的行为就已经是非常失礼的事情，不过那把剑拥有这个程度的价值也是理所当然……应该说还太便宜了。」</p><p>交涉成立的速度快到令人惊讶。</p><p>「那就这样吧……啊，不好意思，因为我不觉得你会这么干脆就答应付钱，所以把东西藏在郊外了。这是钥匙，地点则画在这张纸上。」</p><p>我才刚刚掏出隐藏地点的钥匙跟地图，御剑就硬是抢了过去。</p><p>「喂，等等，钱呢！」</p><p>「真是失礼了。这样应该够吧？」</p><p>这家伙非常干脆地从背包中取出装了金钱的袋子，他总是带着这么一大笔钱走来走去吗？</p><p>我打开袋子确认金额，发现里面装了超过五百万。</p><p>「哇啊，好厉害！竟然轻轻松松就能拿出这么一大笔钱，你到底是多有钱啊？不但是型男还超有钱……这世界实在太不公平了。」</p><p>不要拿我跟御剑相比然后讲出如此痛切的抱怨。</p><p>「虽然这可能是多管闲事，不过你不确认魔剑就付钱真的没关系吗？」</p><p>「你是在担心我吗？真的无所谓，如果这是一场骗局，那我不管做什么都会把剑拿回来。毕竟魔剑格拉墨是我最重要、最重要的，与女神大人之间的联系。」</p><p>女神？那是对他如此重要的人所赠送的东西啊。甚至愿意毫不犹豫就付了五百万。</p><p>哎呀～～真没想到能这么简单就骗到一大笔钱呢，这都得归功于我平常的善行吧。</p><p>「那么，我还赶时间，先走一步！」</p><p>御剑没等我们回应就全力飞奔而去。</p><p>这身体能力太夸张了，没有找他干架真是正确选择。</p><p>「如何？我很和平地赚到钱了吧？」</p><p>我自豪地向琳恩搭话后，她就一脸不悦地瞪着我。</p><p>「喂喂，你这时候应该要为了伙伴赚到钱高兴吧，这样我就能把欠你的债还清喽。」</p><p>「不需要。我不想被卷入犯罪当中。这绝对不是什么正当的事情。」</p><p>「别对我的商业头脑有偏见好吗？这真的是正当买卖，现在我能连同本金加上利息把欠款还你喔。」</p><p>「好啦好啦，如果两天后你还没被警察带走我就收下吧。」</p><p>琳恩背对着我挥了挥手就迈步离去。</p><p>那家伙直到最后都不相信我耶，真是够了。竟然不肯相信伙伴，这个人未免太过分了。就算晚点后悔了，我可不管喔。</p><h3 id="_6" tabindex="-1"><a class="header-anchor" href="#_6"><span>6</span></a></h3><p>好啦，顺利取得不义之财是很不错啦，不过该怎么运用这笔钱呢？</p><p>拿去赌博翻个一倍吗？但我依然被禁止出入赌场所以也没办法，这么一来，拿去做些买卖应该也不错吧。</p><p>「找到了——！我终于找到你了！我不是说了要你等我吗！魔剑呢？」</p><p>竟然被那个阿克西斯教的祭司逮到了，只见她上气不接下气地跑过来。</p><p>我原本希望一辈子都不要再跟她有瓜葛，但果然只要还待在阿克塞尔总是会遇上。</p><p>「卖给御剑了。」</p><p>「你竟然卖掉了！」</p><p>这反应也太夸张了，那本来就是御剑的东西，这也是理所当然的结果吧。</p><p>「你也打算要将那把剑还给那家伙吧？这样不是很好吗？」</p><p>「如果不是由我归还就不能卖人情给他了啊！本来以为在时隔多日后，我终于有机会吃到琼脂史莱姆以外的固体食物了耶！」</p><p>就算再怎么穷也该吃些像样的食物吧。</p><p>而且什么不好选，为何偏偏要吃琼脂史莱姆啊？</p><p>「话说回来，虽然慢了一步，但是你收集到足以买剑的钱了吗？」</p><p>「咦？没有啊。」</p><p>……既然没钱你是来做什么的？</p><p>看到她耸着肩膀露出瞧不起人的表情看着我，实在让我很不爽。</p><p>「虽然没钱，但我可以特别用跟我约会的权利作为交换。」</p><p>「不需要！」</p><p>「以阿克西斯教的美女祭司闻名的我……」</p><p>「这句话我已经听腻了。」</p><p>继续跟这家伙纠缠也只是浪费时间，来看看能不能想个办法能赶走她。</p><p>嗯～～毕竟这个祭司对那个家伙非常执着，那把事情推给他应该是最快的方法。</p><p>「话说，那家伙表示等他找回魔剑就要去招募祭司，还说要去找之前曾跟他说过话的阿克西斯教美女祭司耶。」</p><p>「这种事情你要早点说啊！现在不是跟贪得无厌的好色男讲话的时候了！我必须快点回去准备结婚书约才行！」</p><p>那个祭司飞奔而去，我则是对着她的背影挥手道别。</p><p>这女人这么好应付真是帮了大忙，反正即使谎言被揭穿，会惹上麻烦的也是那个家伙，所以完全没问题……话说御剑的同伙也讲过一样的话，我的脸真的长得那么下流吗？</p><p>「那、那种女人说的话根本不需要在意！这么一来事情就解决了，总算是松了一口气。既然手边有了一大笔钱……赚钱的事就之后再说，先去喝酒吧。」</p><p>镇门附近应该有可以喝到美酒的店才是。</p><p>由于阿克塞尔整个城镇被巨大的城墙包围，所以店家都集中在客流量较大的镇门附近。</p><p>虽然我几乎没有在这一带闲晃过，但这里除了餐饮店外似乎还有形形色色的店家。</p><p>「新鲜的高丽菜跟西生菜便宜卖喔！现在的话西生菜还有大降价！」</p><p>也有在卖蔬菜啊，这些高丽菜就是先前大量收获到的东西吧。</p><p>这么说来，听说有个蠢蛋把西生菜误认成高丽菜还大量捕捉，所以现在西生菜才会这么便宜吧。</p><p>「这个……能够用来赚钱吗？」</p><p>买断所有的高丽菜，然后强硬地高价卖出呢？不过这东西保存期限太短了。</p><p>而且又是大丰收，价格根本可想而知，如果是那种数量稀少的高价蔬菜就是另一回事了。就在我想着这些事情时，某个在栅栏中跳来跳去的红色家伙的标价印入了我的眼中。</p><p>「喂，老爹。为什只有这个的价格超级贵啊？」</p><p>「欢迎光临。你是在找番茄吗？今年的番茄毁灭性歉收，但是跟敝店签订专属契约的农家运气好，收获都平安无事。哎呀，真是幸运啊，毕竟番茄可是人气商品呢。目前摆在货架上的就只有一小部分而已喔。」</p><p>「换句话说，不只有这些喽？」</p><p>「嗯，其他都收在那边的仓库里面。」</p><p>番茄是连餐厅也经常在使用的蔬菜。我还想说为什么最近的沙拉都没有放番茄，原来是这个原因啊。</p><p>歉收就表示无论哪里都缺番茄吧。那么，如果能在王都推销应该就能赚到钱了。而且那边的物价也比阿克塞尔高，就算只是转卖也能赚上一笔吧。</p><p>因为认识能靠「Teleport」在阿克塞尔及王都之间自由往返的家伙，只要去找那家伙帮忙连运费也能省下来。</p><p>「老爹，能让我把包括放在仓库里的所有番茄都买下来吗？」</p><p>「毕竟放着也要花仓储费，如果你能全部买下的确是件好事……不过这可是相当大的一笔数目喔。即使保守估计至少也要五百，你根本付不起吧？」</p><p>这家伙从外表判断我是个穷光蛋吧。</p><p>五百万的话……我付得起。虽然手头的钱会一下子全没了，但之后能加倍赚回来。就连老天爷都站在我这边啊，这果然是因为我平日有多做善事吧。</p><p>「喔，这些应该够了吧？」</p><p>我将刚到手不久装有五百万艾莉丝的袋子递了出去。</p><p>原本狐疑地看着我的老爹在确认袋子里面的东西后，立刻浮现谄媚的笑容并搓着手掌……我实在不讨厌这种简单易懂的态度。</p><p>「谢谢惠顾。只要能够付得出钱，我才不会去在意出处呢。没错，就算不解释也无所谓。毕竟钱就是钱啊。作为服务的一环我把推车先借给您，之后请记得归还喔！」</p><p>在似乎误会了什么的老板用愉悦的语气欢送下，我拉着装满番茄的推车离开。再来就是去找能使用「Teleport」的家伙，啊，不知道琳恩如何？若是她会用就能节省更多开销了。</p><p>『紧急广播！紧急广播！所有冒险者请注意，听到广播请立刻全副武装，成战斗状态到城镇的正门集合——！』</p><p>紧急广播在四周响起，实在很吵耶。</p><p>这个声音应该是在冒险者公会担任柜台小姐的露娜吧。她的语气听起来相当慌张，是发生了什么事吗？既然讲了战斗状态那应该跟魔物有关吧。</p><p>『紧急广播！紧急广播！所有冒险者请注意，听到广播请立刻全副武装，成战斗状态到城镇的正门集合！……尤其是冒险者佐藤和真先生及其同伙，请尽速前往现场！』</p><p>「佐藤和真？那是谁啊？听都没听过呢。」</p><p>如果不参加紧急召集，之后将会发生大问题。但是这么一来，这些番茄该怎么办才好呢？</p><p>已经没有时间运回仓库了，不然就放在镇门附近吧。但是把这些价值五百万艾莉丝的番茄随地放置也是个问题啊，这样很可能会被坏人偷走，我到底该怎么办才好呢？</p><p>拉着推车的我想不到任何可行方法，只能沿途跟逃窜的居民们擦身而过来到镇门附近。</p><p>因为是紧急状况，居民们都远离镇门这一带前往城镇内部避难。转眼间就不见人影了。</p><p>我站在镇门附近的墙边，一边远远眺望接二连三与居民们交错的冒险者们冲出门外，一边抱头烦恼。</p><p>「你在做什么？没听到公会的紧急召集吗？……是说，你为什么拉着放满番茄的推车？这次又打算做什么不正经的事情了？」</p><p>竟然在这里碰到正赶往镇门的琳恩。</p><p>虽然奇斯和泰勒这两名伙伴也在，但是他们只看了我一眼就匆匆离去了。</p><p>「我什么都没做啦，就只是买东西买到一半。那个广播是怎么回事啊？」</p><p>「我也不是很清楚，但露娜小姐听起来相当焦急呢。你也别做奇怪的事情快点过来啦。还有，既然有这么多番茄之后给我一个，你也知道我喜欢吃蔬菜吧。」</p><p>琳恩说完这些就消失在镇门的另一侧。</p><p>城镇的危机和五百万艾莉丝……究竟该选那一边根本不需要考虑吧……唔，不过，这可是五百万耶。之前击退干部的那群人似乎也在，那我不去也无妨吧？</p><p>「但是我也不能抛下琳恩他们不管，干脆拉着推车过去吧？」</p><p>这个主意感觉还不错，比起放在这里担心被偷走，带着一起去反而比较安心呢。好，决定了。就这样带着过去吧。</p><p>当我拉着推车穿过大门后，就看到冒险者们成群并排的背影。</p><p>有好几个人在看到我的模样时吃了一惊，现在是还有这种从容吗？</p><p>因为被人群挡住，我也不清楚到底发生了什么事。魔法师们为何在使用「Create Water」之类的初级魔法啊？</p><p>那个在离魔法师们稍远一点的地方站着不动的人是奇斯吗？</p><p>「喂，奇斯，现在是什么状况？」</p><p>「达斯特，你总算来啦……我说你为什么拉着推车？那样不就无法战斗了吗？」</p><p>「呼，这跟能不能战斗无关，而是我要这样战斗。」</p><p>「你那副样子就算想耍帅，也只会让自己看起来很蠢。不对，现在不是说这个的时候啦！已经有好几个冒险者被打倒了！能发现敌人的弱点是水当然是好事，但是缺乏决定性一击只会让状况越来越恶化啊！」</p><p>有人被打倒了吗！</p><p>不能再这样下去了。绝对不能再继续出现牺牲者，我真的要出手了！</p><p>「让开让开！敌人就由本达斯特大爷来打倒吧！」</p><p>「喂，白痴啊！至少先把推车放下啊！」</p><p>我一全力冲出去其他冒险者就立刻回头，接着拼了命朝我所在的地方冲了过来。在这种情况下仍深受大家的信赖，这样的我实在帅到受不了。</p><p>「你们统统给我去后方等着！我这就去打倒敌人！」</p><p>「白痴！快逃啊！海啸要过来了！」</p><p>「快躲开——！会被洪水吞没啊！」</p><p>啥？这附近根本没有大海，怎么可能会有海啸。这也未免太奇怪了……</p><p>「嗯？这阵类似地鸣的声音是……而且声音还逐渐往这里靠近耶……」</p><p>我在因为冒险者们喊叫的蠢话感到茫然的同时，也将视线转向他们的后方——出现在那里的，是一片巨大的水壁。</p><p>将视线完全填满的水蓝色。</p><p>竟然真的是海啸！这附近明明就没有海！</p><p>「可恶！唔喔喔喔喔喔！」</p><p>我拼了老命地拉着推车往城镇上跑去，但是逐渐逼近的水声越来越大。</p><p>混蛋，这到底是怎样啦！简直莫名其妙！</p><p>「真的假的啊啊啊啊啊啊啊啊啊啊啊啊！」</p><p>在背后感受到冲击的瞬间大水也覆盖整个视野，被浊流吞没的我分不清前后左右，只能任凭水流的摆弄和冲刷。</p><p>「咕噜咕噜咕噜咕噜——！」</p><p>我不会放手的！只有这个装满番茄的推车货篮我绝对不放手喔喔喔喔！</p><h3 id="_7" tabindex="-1"><a class="header-anchor" href="#_7"><span>7</span></a></h3><p>「咳！呼……呼喔喔喔喔喔。总、总算是活下来了啊。」</p><p>姑且是摆脱了在大街上溺死这种意义不明的死因，虽然全身都湿透，但留得青山在不怕没柴烧。只要还活着我就不抱怨了。</p><p>「不过，为什么会有海啸袭击啊？差一点就被淹死了。之后我一定要跟做出这种事的家伙要求赔偿。不对，现在不是讲这种话的时候！番茄，我的番茄怎么样了？」</p><p>四处张望后，虽然有找到破碎的推车及货篮，但是里面的东西——已经彻底消失了。</p><p>沾黏在货篮上的红色液体及碎片就是番茄的……残渣……吗？</p><p>「喂……骗人的吧。这、是、在、开玩笑吧……唔喔喔喔喔喔！五百万！我的五百万艾莉丝！五——百——万——啊————！」</p><p>「喂喂喂，别挡在路上嚷嚷啊。呃，是达斯特啊。」</p><p>第一个向处在绝望深渊的我搭话的人，是杂货店的大叔。</p><p>这时候应该要来个美女安慰我才对吧，结果偏偏是个大叔。</p><p>「唉————」</p><p>「你这口气叹得还真大呢。到底发生什么事了？不但镇上淹大水，连城墙也坏了耶。」</p><p>「是海啸，海啸！我所有的财产也因此付之东流了……我的番茄，番茄啊啊啊啊啊！」</p><p>「别跑来纠缠我！不要边喊着不明所以的事情边假哭还用我的裤子擦身体！番茄不是就在那边的木片间隙当中吗！」</p><p>我朝着大叔所指的方向望去，发现在木片和木片交错的间隙中，存在着一颗奇迹般毫发无伤的番茄。</p><p>「喔喔喔喔喔，番茄啊啊啊啊！」</p><p>我迅速冲上前去将番茄捡起，温柔地把它放在双手上朝天空高高举起。</p><p>「用不着哭成这样吧。这么说来番茄好像歉收耶。唯一有在贩卖番茄的店似乎也售罄了。虽然只有一个，但也能卖个好价钱吧。不然我向你买下来吧？」</p><p>这样啊，最坏的情况下，这个番茄很可能是这个城镇唯一的一颗。</p><p>如果是这样，应该能稍微回本吧？</p><p>我现在也只能将仅存的希望寄托在这颗番茄上了。</p><p>「为什么达斯特像死了一样啊？」</p><p>坐在平常的座位上吃饭的伙伴开口这么问。刚刚说话的人应该是泰勒。</p><p>由于我趴在桌子上，完全看不见伙伴的样子。</p><p>「谁知道呢？他一直都是这副模样喔。」</p><p>「应该是那个吧。因为太晚去讨伐干部了，所以没拿到奖金吧。」</p><p>那种事情怎样都好啦。之后我虽然在附近四处寻找，但找到的番茄就只有最一开始看到的，也就是现在装在腰际袋子中的那颗而已。</p><p>如果相信大叔所说的情报，我应该找地方把这唯一的一颗，有着超稀有价值的番茄卖掉。顺利的话说不定能带来下一次赚钱的机会。</p><p>「啊～～沙拉里面又没有番茄了。真是的，我好像有两个月没吃到番茄了耶。唉，好想吃番茄啊。」</p><p>琳恩不知道我在番茄买卖上亏了一大笔钱的事，所以是委婉地在叫我请她吧。</p><p>为了多少回收一些我泡汤的钱，这颗番茄是必要之物，不是那种可以随便送出去的东西。</p><p>然而看着一直盯着这里的琳恩——我大大地叹了一口气。</p><p>「唉，琳恩，这个番茄给你啦。」</p><p>「咦？可以吗？谢谢，你还是有优点的嘛。」</p><p>用干净的布擦拭收下的番茄后，琳恩立刻大口吃了起来。我则是呆望着她开心的侧脸。</p><p>这就是五百万的笑容啊。算了，也还不坏啦。</p>`,267),e(f,{src:`/images/E1/06.avif`,alt:`插图`,width:`850`,height:`1206`}),s[9]||=a(`<h2 id="第三章-那位勇者的奋斗记" tabindex="-1"><a class="header-anchor" href="#第三章-那位勇者的奋斗记"><span>第三章 那位勇者的奋斗记</span></a></h2><h3 id="_1-2" tabindex="-1"><a class="header-anchor" href="#_1-2"><span>1</span></a></h3><p>「之前那场冒险真的好厉害喔，实在没想到和真这么优秀呢。」</p><p>虽然在公会平常的座位上跟伙伴们喝酒聊天，但他们从刚才开始就一直在讲同一件事。</p><p>看着琳恩眼神闪闪发亮地不停夸奖和真的样子，让我有一点不爽。</p><p>「和真那种随机应变的能力真是不得了啊！即使现在回想起来还是很兴奋！」</p><p>「先前虽然因为是冒险者就小看他，但是他那种全方位的技能实在太出色了。感应敌人、潜伏，再加上初级魔法竟然如此有用。」</p><p>奇斯和泰勒这两个伙伴也是赞不绝口。</p><p>我认同和真相当辛苦这点。因为我亲身体验过那三个空有外表的女人们有多么危险了。</p><p>负责统御她们的人肯定是和真，这点绝对没错。</p><p>但是把我晾在一旁兴高釆烈地讨论和真的事，果然让人很没劲。</p><p>「能找出初级魔法的那种使用方法真是令人钦佩。我都想跟和真一样把初级魔法学起来了。他真的在各方面都能派上用场呢，比起那种虽然有些本领却不断闯祸的家伙，还是想要像和真那样的伙伴呢。」</p><p>琳恩是对和真作为魔法师的随机应变能力深感钦佩吗？既然能使用中级魔法，那初级魔法根本毫无价值啊。</p><p>「只要有和真在，冒险也会轻松许多吧。跟在与魔王军干部的战斗中，拖到最后的最后才参加的某人完全不一样呢。」</p><p>奇斯调整着弓弦，一边用意味深长的视线望过来。</p><p>我当时真的没有那个闲工夫啊。</p><p>「再去请他们交换一次也行喔。」</p><p>连泰勒都把我当没人要的孩子对待。</p><p>「你、你们到底想表达什么啊……别用那种轻蔑的眼神看我。唔、喂！你们不是在开玩笑，而是认真的吗？我在该出手时也是会出手的喔！只是没有遇上那种机会罢了！」</p><p>「还说什么机会……真要讲起来，之前在和无头骑士战斗的时候你为什么没来啊？虽然在那之后变得有够消沉就是了。」</p><p>「别让我想起那件事啦……我真的会很消沉。」</p><p>毕竟五百万瞬间就化为乌有了。在那之后，我明明只是去找蔬果店的大叔要求退钱，他竟然就叫来警察，还跟我追加要求弄坏推车的赔偿……可恶，现在光是回想起来就觉得不爽！</p><p>「比起那些事，我们什么时候要接新的委托啊？因为没钱，就算今天出发我也可以喔。」</p><p>「啊～～我暂时不参加。至少冬天这段期间我都不想接委托。」</p><p>「也是呢，冬天只有凶恶的魔物在活动。讨伐魔王军干部的奖金也还有剩，就算什么都不做也能顺利度过冬天吧。」</p><p>「嗯。因为手头很宽裕，要每天都去那边光顾都行。」</p><p>「喂，笨蛋！」</p><p>「那边是指……？」</p><p>由于奇斯说漏了嘴，琳恩立刻眯起眼睛瞪向这边。</p><p>「那边」是指我们最近才得知，而且绝对不能让女性发现的秘密场所。泰勒则是因为他身为十字骑士又有不懂变通的地方，所以我们没有告诉他。</p><p>我有为了去那里光顾努力存钱的义务。</p><p>「比起那种事！有人打算接委托吗？」</p><p>「「「没有。」」」</p><p>可恶，竟然如此坚决。</p><p>即使想找其他人组队，但这座城镇的冒险者们全都有得到奖金啊。像我一样穷困潦倒的人就只有……</p><p>「喔，这不是和真吗，你正打算去工作啊？」</p><p>听到泰勒的声音后我转头望去，就看到和真一行人站在那里。</p><p>之前看他身边带着三个美女都觉得很是嫉妒，但自从经历过那次之后，反而比较同情他。</p><p>「是啊～～因为讬某个祭司的福，我现在欠了一屁股债。」</p><p>「你想说都是我的错吗！明明多亏有我在才能打倒干部耶，你应该要更加感谢跟称赞我！用唰唰和酥炸蟾蜍代替香油钱奉献给我啊！」</p><p>「吵死了！你以为我是因为谁才会这么辛苦啊！」</p><p>「和真，就先到此为止吧。如果你真的焦躁难耐，也可以尽情痛骂我喔。」</p><p>「我完全不打算要给你奖励！」</p><p>「好啦好啦，只要能让我放爆裂魔法就行了，所以非常乐意去冒险。」</p><p>「算我求你，也学些其他的魔法……」</p><p>「恕我拒绝。」</p><p>真是辛苦啊……虽然说跟我一样为钱所困的就只有和真他们，但我实在没有余力跟他们一起去冒险。</p><p>而且即使靠和真让我参一脚来赚到钱，我在伙伴之间的评价也不会提升。</p><p>「那我们先走了。」</p><p>我没有开口挽留和真，只目送他的背影离去。</p><p>那么接下来该怎么办才好呢？伙伴们派不上用场，去邀请其他冒险者也没用。这么一来，只能去找一个人也能完成的委托了。</p><p>「唉～～要一个人去找工作吗～～就只能孤伶伶地独自去工作啊？如果有心地善良的伙伴愿意出手相助就太好了说——」</p><p>我起身边活动手脚边往伙伴们望去，结果三个人全都避开我的视线。</p><p>「那么，我们就窝进旅馆吧。」</p><p>「别去做蠢事，要认真赚钱喔。」</p><p>「抱歉啦。你就一个人去好好享受吧。」</p><p>没有任何一个人开口说愿意借我钱，就直接把我丢下。这群人实在太冷漠了，即使我以后成为富翁也绝对不会请客！</p><p>「唉，来确认有哪些委托吧。」</p><p>如果有那种尸位素餐的工作就太好了。</p><p>姑且看了贴在布告栏上的委托，但冬天就只有内容艰涩的委托。</p><p>尽是些讨伐一击熊集团之类乱来的工作，独自承接就跟去自杀没什么两样啊。</p><p>「就没有报酬高又简单的工作吗……嗯？这是半兽人讨伐？」</p><p>所谓的半兽人，就是那种脸部是猪的种族。我记得该种族的雄性已经绝种，目前只剩下雌性。由于她们性欲旺盛，所以会捕捉到其他种族的男性，为了生小孩而做到俘虏被榨干为止，可以说是最恶劣的存在呢。</p><p>如果做出这种事的是美女种族的话我甚至愿意付钱，但毕竟是猪啊。</p><p>换作平常，这是我完全不想靠近的存在，不过这个委托的报酬却莫名的好。毕竟其他委托都是物理上不可能成功讨伐的状态。就去打听一下这个委托的内容吧。</p><p>我撕下委托书，拿到那位胸部大得夸张的柜台小姐面前。</p><p>「露娜，关于这个委托，能不能告诉我详情啊？还有，因为我遇上了令人消沉的事，能不能让我揉你的胸部？」</p><p>「哎呀，这不是达斯特先生吗。你之前从来不曾在冬天承接委托，这个情况还真是稀奇呢。我要把你扭送警局喽？」</p><p>不愧是每天都在跟难搞的冒险者们打交道的柜台小姐，能面露笑容俐落地给予毫不留情的应对实在太厉害了。</p><p>「哎呀，只是开个小玩笑啦。因为最近开销有点大，虽然不太情愿但是不工作不行呢。」</p><p>「由于你太晚参加讨伐干部的任务，所以无法取得报酬呢。我看看喔，是讨伐半兽人的委托啊。有人在邻近村落的周遭目击到半兽人，这是该村落的村民提出的讨伐委托。听说村里的男性们都害怕得不敢出门，导致全村人手不足，只能坐困愁城呢。」</p><p>因为听说被母半兽人逮到就会被榨到精尽人亡，男性冒险者碰上半兽人集团时要逃跑可是铁则。</p><p>由于那个种族会筛选优秀的基因繁殖，所以她们有着挂保证的强度。</p><p>加上一旦被逮住就是作为男性结束的瞬间，在这股恐惧的笼罩下，冒险者的动作也会变得十分迟钝。</p><p>「大概有多少只半兽人？」</p><p>「根据目击情报，似乎是十只左右。」</p><p>一两只还有机会，但十只就有难度了。独自一人无论怎么挣扎都赢不了，而且失败时的风险实在太大了。</p><p>「这样的话还是不要接会比较好。」</p><p>「那真是可惜。那个村落有个名为『美人汤』的秘密温泉，不清楚是不是托了那个温泉的福，村民可是美女成群喔。我也一直想去泡泡看那个温泉，但工作太忙了，而且以村落的现况来说根本不是去泡温泉的时候……这么说来，虽然算不上是追加报酬，但村落有留言给接受委托的冒险者，说是如果能尽早将解决这个状况，就会出动所有村民举办欢迎会喔。」</p><p>「请告诉我详情。」</p><p>在我听完委托内容陷入沉思时，突然有人拉了拉我的袖子。</p><p>「啊？是谁啊？」</p><p>一将视线移过去，就看到一名小女孩抓住我的袖子盯着我看。</p><p>「你终于还是为了钱做出诱拐这种事了……虽然给冒险者设定悬赏金令我很痛心，但是公会仍必须给予你严正的处分。」</p><p>「为什么啦！我不认识这个小鬼啊！喂，给我放手！」</p><p>「叔叔，你看来不怎么受欢迎呢。还有，我不是小鬼，是小妹妹喔。你们刚才是不是说了讨伐半兽人？那是我们村落提出的委托吗？」</p><p>这个小鬼是怎样？所以她来自提出委托的那个村子吗？</p><p>也有可能是跟父母一起来提出委托的。</p><p>「哎呀，仔细一看，这位是委托人的女儿呢。」</p><p>露娜似乎对她有印象的样子。</p><p>跟我预想的一样，看来我的直觉真不是盖的。</p><p>「我不是叔叔，是帅气的大哥哥才对。如果你们正因为半兽人出现在村落附近而感到困扰，那就没错了。你是来自那个村子的小鬼吗？」</p><p>「没错，叔叔。但我不是小鬼，是小妹妹喔。」</p><p>「喔、喔喔。明明是个小鬼却很烦人呢。所以你现在有什么事？」</p><p>「那个啊，爸爸被半兽人袭击，虽然最后总算是想办法逃出来，但从那之后他就待在房间里不肯出来。而且一直说着『我的性向很正常，快住手！』之类的话。」</p><p>这、这样啊，真是可怕的遭遇呢。同样身为男人，我对你爸爸深表同情。</p><p>虽然他很幸运能成功逃跑，但我听说被那东西硬上的恐惧感非常不得了。</p><p>「明明妈妈每天都在说『身为男人给我振作一点啊！就是因为你这样才赚不了钱！我最近是真的去跟酒店店员搭讪了喔！』之类的话来鼓励他，但他还是不肯出来。」</p><p>「我真的很同情你爸爸啊……不过，那又怎样？」</p><p>「叔叔，你要来讨伐半兽人吗？如果是那样的话，爸爸在逃跑时把我的生日礼物弄丢了，你要帮我找回来喔。」</p><p>「喂喂，你把我当成什么了。我可是冒险者，讨伐半兽人才是我的工作。」</p><p>「那就拜托你喽，不受欢迎的大哥哥。」</p><p>接着那个不听人话的臭小鬼就跑回应该是她母亲的女性身边。</p><p>小孩子都是自我中心又不肯听人讲话耶……算了，那种臭小鬼的事怎样都好啦。</p><h3 id="_2-2" tabindex="-1"><a class="header-anchor" href="#_2-2"><span>2</span></a></h3><p>决定接下委托后，我边思索之后的事情边前往最能让人冷静的地方。</p><p>虽然感觉就像是被露娜拱上贼船，但我无论如何都得接些委托才行。而且，如果没钱就没办法去梦魔的店光顾了！</p><p>奇斯说熘嘴的「那里」就是指梦魔的店。阿克塞尔城镇与梦魔们之间有着共存共荣的关系。梦魔给予男性冒险者能满足他们情色欲望的春梦，男性冒险者则提供少量的精气和金钱作为代价。</p><p>我们可以神清气爽，梦魔们也能得到精气。这就是所谓的互助互惠，算是相当不错的生意吧。虽说如此，如果被发现在利用身为恶魔的梦魔将会引发各种麻烦，所以这是男性冒险者之间的秘密。</p><p>由于不是在现实中做出的行为，终究只是一场春梦，因此无论是多么色情的场面都能实现，真的可以说是最棒的店了。自从知道这家店后我每天都会去光顾，但现在的我却连那点钱都没有。</p><p>「母半兽人啊，虽然不想战斗，但我已经走投无路了。有没有什么能轻松讨伐她们的方法呢……」</p><p>「喂，喂——」</p><p>「受不了，我正在认真思考事情耶，你就不能机灵一点准备些酒之类的请我吗？」</p><p>「开什么玩笑，你为什么每次都在我的店头赖着不走啊？这里可不是你家！啊，你这家伙竟然在我贴了标价的商品当中混了自己的东西！只要达斯特在这里今天的生意就完蛋了。」</p><p>不过是坐在杂货店卖不出去的椅子上休息一下而已，这家伙的器量有够小耶。</p><p>这点程度就在那边不爽，只会让你本来就没剩多少的头发变得更秃啦。</p><p>「反正你这间店本来就没客人吧，我还没碰到除了我以外的客人过呢。」</p><p>「只要你待在这里客人就不敢靠近，店的评价也会越来越差啦。」</p><p>「喂喂，把赚不到钱的原因归咎在别人头上未免太奇怪了吧。想要我早点回去就给我保护费，不然帮我想个能讨伐半兽人的方法。」</p><p>虽然我也知道杂货屋大叔根本提不出讨伐相关的点子，但我现在已经完全走投无路了，所以试着听听看别人的意见也不错。</p><p>「竟然说保护费，你已经完全是个小混混了耶……那个半兽人讨伐是怎样？」</p><p>「因为我接了讨伐半兽人的委托，所以在想有没有可以轻松打倒她们的方法。」</p><p>「拜托你正当地去战斗然后打倒她们啦……既然那么没干劲，那就不要承接委托啊。这么一来，御剑先生就有可能接下那个委托了。那样对委托人来说也是最好的结果。」</p><p>又是御剑啊。总觉得我最近一直在听和真跟御剑的事耶。</p><p>「御剑啊。真要讲起来，我之所以会损失一笔大钱都是那家伙的错。全是那家伙一口气给出一大笔钱把我搞得利益熏心，我才会浪费掉那笔钱。」</p><p>如果是那个家伙，应该能轻易讨伐半兽人集团。而对于追求强壮雄性的母半兽人来说，御剑也是最棒的饵食。</p><p>嗯……不然利用那个家伙让他去战斗如何？感觉他个性直率相当好骗……只要一切顺利，我不就能收割所有好处了吗？</p><p>「喂，你刚才说的一大笔钱是怎么回事？」</p><p>「那件事跟你无关，我想到一个完美的好方法了，谢啦。」</p><p>「被你道谢只会让我有不祥的预感……」</p><p>好了，接下来我该做的就是想方法把讨伐半兽人的工作塞给御剑……根据传闻，他有着强烈的正义感，对女性也很温柔。只要用这个理由去刺激他，应该就能轻松操控他了。</p><p>正义感和女性是吗。那就去请那家伙帮忙吧。</p><h3 id="_3-1" tabindex="-1"><a class="header-anchor" href="#_3-1"><span>3</span></a></h3><p>「……就是这样。」</p><p>「这到底是什么情况啊，达斯特先生？」</p><p>我去了经常光顾的梦魔店，向熟识的矮个子萝莉梦魔搭话后，她就做出这种反应。</p><p>虽然乍看之下只是间普通的咖啡厅，实际上却是能够实现男性梦想的最棒的店。</p><p>这里依旧是最棒的乐园。只用些许布料把重要的部分遮起来的店员姊姊们，毫不吝啬地裸露自己的肌肤。</p><p>光是能看到每走一步就不停晃动的胸部和屁股，就让人觉得不虚此行。</p><p>「所以说，就是请你假扮成村女，哭着去拜托御剑那个家伙帮忙啊。就说些『村落的男性们都被半兽人给绑架了，拜托您帮帮我们吧！』之类的话。我会负责准备舞台和台词，所以拜托你啦。」</p><p>「我不懂的不是指骗人的方法，而是在问为什么我要帮你做那种事？」</p><p>看来她不想帮忙呢，但这也在预料之中。打从一开始我就不觉得她会乖乖答应我的请求。</p><p>对冒险者来说，事前收集情报是必要的一环。我已经事先调查过你的事情了。</p><p>「我都知道喔，因为和真那件事让你觉得很丢脸对吧？由于工作失败的事已经传开，使得指名你的家伙也变少了对吧？只要你现在愿意提供协助，那我绝对不会亏待你。要我每次都指名你也无所谓。再不然要我介绍一些喜欢萝莉类型的家伙给你也行。」</p><p>「呜，你是从哪里听来的……」</p><p>萝莉梦魔动摇到藏都藏不住了。虽然我的确知道和真那件事，但后半只是我靠直觉随口说说而已，看来是猜中了。关于那次失败的事是在我们去喝酒时听和真说的，不过趁着酒劲当成玩笑散布出去的人则是本大爷。</p><p>「而且御剑不愁女人又个性严谨，根本不会光顾这间店。既然不是客人，就算骗他一下也不会出问题。我在冒险者之间吃得很开，所以也可以帮你宣传喔。如何？这不算什么坏事吧？骗人的技巧在让人作春梦时也很重要，这可是在现实中磨练本事，并借此领先其他梦魔一步的好机会呢。」</p><p>「这样的确有些……吸引人呢。」</p><p>「只要交给我，你总有一天能成为这里的红牌梦魔喔。到时候无论同事或前辈都会拼命夸奖你吧。你试着想像一下未来那个充满了魅力的自己。」</p><p>「红牌……不用再过抬不起头的日子……」</p><p>应该是在妄想自己未来的模样吧，只见她露出恍惚的表情望着远方。</p><p>看她那副模样，应该能成功说服她。</p><p>「就是这样，我在你身上感觉到潜藏的才能！就由我来当你的制作人，一同以梦魔界的顶点为目标！成为最优秀的梦魔，让每个人光是看到你的倩影就会深深着迷！」</p><p>「那、那样的未来！」</p><p>「如果是你一定能够实现！让自己变得更加闪闪发光吧！」</p><p>她的内心因为我热烈的演说开始动摇了。</p><p>我有听说过梦魔的价值取决于能让男人着迷到何种程度。虽然这可能只是传言，但无论哪个业界都有类似评价的东西。</p><p>我的直觉告诉我，只要再推一把她就会答应。</p><p>「你就去帮忙吧。」</p><p>应该是本店经营者的梦魔在这时介入了我们的对话。</p><p>跟萝莉梦魔不同，她那副凹凸有致让人想立刻扑上去的身材，今天依然极度艳丽。</p><p>果然所谓的梦魔就该这样，像萝莉梦魔那种缺乏曲线的瘦弱身体根本让人兴奋不起来。</p><p>「可以吗？」</p><p>「可以喔，达斯特大人是我们重要的客人。你就去助他一臂之力吧。」</p><p>这真是出乎我意料的助力啊。不愧是经营者，非常清楚何谓做生意。今后我也会继续捧你的场喔。</p><p>「我知道了。达斯特先生，我就帮你吧。不过我没办法参与战斗喔。梦魔虽然是恶魔的一种，但我们没有战斗力。」</p><p>「你真是帮大忙了！放心吧，我绝对不会让你受到任何一点伤，那么我们先来套招吧。」</p><p>必须趁现在把用来欺骗御剑的剧情定下来才行。虽然那家伙看起来很单纯，应该会轻易落入圈套之中，不过这种事情还是小心为上。</p><h3 id="_4-1" tabindex="-1"><a class="header-anchor" href="#_4-1"><span>4</span></a></h3><p>我和萝莉梦魔潜伏在山路上边警戒四周边复习今后的作战计划。</p><p>「台词都已经背好了吗？」</p><p>「一字不漏！因为大家都有来帮忙，所以演技也是熟练到不行！」</p><p>大概是因为有着相当的自信，感觉萝莉梦魔的语气相当激昂。</p><p>跟平时在店里时那种高露出度的打扮不同，她今天的穿着相当朴素，看上去就是普通村女。这么一来御剑也不会被发现她其实是梦魔吧。</p><p>「不过御剑先生真的会路过这里吗？」</p><p>「绝对会，那家伙对和真队伍里水蓝色头发的祭司相当执着。所以我拜托熟人散布了一些流言，说她在这座山上遇到危险。」</p><p>「咦？是和真先生那边的祭司吗？啊，呜呜……我会被净化……」</p><p>萝莉梦魔抱着肩膀开始发抖。</p><p>难道她在和真那边失手时，吃了那名祭司不少的苦头吗？</p><p>由于那个女人好战到一点都不像祭司，所以很有可能是这样。毕竟不管是阿克西斯教或艾莉丝教都非常厌恶恶魔。</p><p>「那家伙其实不在这里，所以你冷静点。拜托啦，现在一切的一切都得靠你的演技，可别失败了啊。」</p><p>「交给我吧！我绝对不会再失败了！失败什么的绝对不会再发生了！被大家安慰和同情的日子，永别了！」</p><p>感觉萝莉梦魔异常地有干劲耶，难道「失败」这两个字对这家伙来说是禁语吗？</p><p>这么说来只要提到和真的事情时，她也会有过剩的反应。</p><p>「喔、喔喔，那就期待你的表现了。」</p><p>为了让她能稍微放松一点，我面露微笑轻轻抚摸她的头。</p><p>萝莉梦魔讶然地看向我后就低下头去，接着才用湿润的眼眸抬头凝视我。喂喂，她该不会被我的温柔所触动，还因此迷上我了？</p><p>「达斯特先生……『女性喜欢被摸头』这种事，完全是处男的幻想喔。」</p><p>「吵死了！既然没事就快点去准备！」</p><p>虽然外表看起来相当年幼，但这家伙毕竟是恶魔兼梦魔，对于男女情爱的理解绝不马虎。</p><p>不过啊，面对这种彻底缺乏艳丽感的小女生，我根本不会产生任何欲望所以无所谓啦。</p><p>「盯着人家的身体叹气未免太失礼了吧，你是被我迷住了吗？」</p><p>怎么可能——我硬是把冲到喉咙的话语吞了回去。</p><p>「抱歉抱歉。呃，听到脚步声了，安静点。」</p><p>我潜伏在大树后方，只将握着小镜子的手稍微伸出去，以确认传来声响的山路的状况。</p><p>从那套蓝色铠甲及套着黑色剑鞘的剑判断，应该是御剑没错。他似乎是一路飞奔过来，不但上气不接下气，还用充满血丝的双眼瞪着四周，那副模样看起来完全就是可疑人物。</p><p>那两个女跟班不在啊，这样正好。</p><p>「稍微变更一些台词，这个部分要这样……」</p><p>「达斯特先生的个性真的很恶劣呢。你其实是恶魔吧？」</p><p>「喂喂，我只是顺从自己的内心罢了，别说那么失礼的话。比起那些事，差不多该轮到你出场了，去吧！」</p><p>「好的，我出发了！」</p><p>萝莉梦魔向我敬了一礼后就跑了出去。</p><p>她的头部及身体上都沾上适量的树叶。这次的剧本是萝莉梦魔正奄奄一息地拼命逃跑，接着在途中遇上了御剑。</p><p>到目前为止都照着计划在进行。不愧是能自由自在操控梦境的存在，演技的水准也相当高呢，很行嘛！</p><p>「请、请救救我！」</p><p>「发、发生了什么事吗！」</p><p>在萝莉梦魔即将要跌倒的瞬间，御剑接住了她。</p><p>很好，这时候要用湿润的眼眸往上看！哦，还自己加入了边颤抖边向对方伸出手的即兴演出……看来她根本干劲十足嘛。</p><p>连裙子都恰到好处地翻起来露出大腿，如果这完全是她算计好的，那未免太厉害了，不过应该只是偶然吧。</p>`,209),e(f,{src:`/images/E1/08.avif`,alt:`插图`,width:`850`,height:`1206`}),s[10]||=a(`<p>「半、半兽人集团袭击我们的村子！还把男人们都带走了！拜托你救救村里的大家吧！」</p><p>这演技实在太逼真了。感觉梦魔们完全可以去当演员啊。</p><p>「竟有此事……虽然我也很想帮你，但我正在找阿库娅大人。我不能丢着那一位不管。」</p><p>「阿库娅大人？难道是那位有着水蓝色头发的美丽祭司吗？」</p><p>「没错！你知道她的事吗？」</p><p>这反应真不错，指示她追加这句台词果然是正确的决定，只要这样讲那家伙肯定会上钩。</p><p>「是的。在得知我们的村子遭受袭击后，她毫不犹豫就前往村落帮忙了。」</p><p>「不愧是女神大人，那一位果然既美丽又贤明。我还担心阿库娅大人待在他旁边会不会受到什么坏影响呢。」</p><p>不不不，她原本就是那副样子吧。反而是和真站在监护人的立场设法控管她好吗。虽然御剑对阿库娅相当执着，但说她贤明……他是看见幻觉了吗？</p><p>由于御剑的言行全都充满了戏剧性，我现在感觉就像是在看话剧。</p><p>「所以阿库娅大人现在人在哪里？」</p><p>「我﹑我这里有村里的人努力侦查后，注记了半兽人集团所在位置的地图。」</p><p>萝莉梦魔从怀里取出纸张递给了御剑。当然，那是我亲手绘制的手制地图。我已经事前侦查过半兽人的所在地。</p><p>「我知道了。请放心吧！我会想办法救出村民和阿库娅大人！」</p><p>御剑那副堂堂正正做出宣言的姿态还真是有模有样。所以说，型男这种存在实在是……</p><p>他轻轻地让萝莉梦魔横躺在地上后，只留下爽朗的笑容就跑走了。</p><p>确认御剑的身影完全从视野中消失，我就朝萝莉梦魔走了过去。</p><p>「辛苦了，你很厉害嘛。」</p><p>「如何？我没有失败吧！」</p><p>「非常完美！看到你的那副模样无论谁都会被骗倒呢。」</p><p>「是这样吗，你夸奖过头了啦。嘿嘿嘿嘿。」</p><p>这家伙还真好哄耶。她是不习惯被夸奖吗，竟然害羞到脸颊泛红。</p><p>看来要对付萝莉梦魔时乱捧一通会相当有效，先记下来。</p><p>「好了，我们去见证御剑的活跃吧。如果能帮我全部讨伐自然是再好不过，若是只有削减掉她们的战力，那他被抓住也没关系，只要我趁半兽人沉迷于那家伙时从背后偷袭就好了。」</p><p>「达斯特先生果然是恶魔……」</p><p>「才不是！」</p><p>当然，要是御剑被抓到，我会在他被上之前救他出来。毕竟我没有那么残忍。虽然他要是因此讨厌女人我也没差就是了。</p><p>无视与我并肩而行还眯起眼睛盯着我看的萝莉梦魔，我持续朝着目的地跑去。</p><h3 id="_5-1" tabindex="-1"><a class="header-anchor" href="#_5-1"><span>5</span></a></h3><p>接近半兽人集团的所在地后，我们就放缓速度朝一座视线良好小山丘移动，接着匍匐前进爬上丘顶，探头窥视下方的状况。</p><p>御剑就位于被他打倒的半兽人集团的中心。他独自讨伐了所有半兽人吗？虽然呼吸紊乱却毫发无伤，他果然很强啊。</p><p>「阿库娅大人！您在哪里，阿库娅大人！」</p><p>他一边大声喊着那名祭司的名字，一边进入搭在那里的帐篷确认。</p><p>要是就这样放着不管，他很有可能会跑去村里面询问，这样一来我的诡计将会曝光。</p><p>「可以拜托你帮忙善后吗？」</p><p>「只要跟他说阿库娅大人在救了大家后也跟着离开就可以了对吧？」</p><p>「嗯，那样就够了。」</p><p>萝莉梦魔从背后伸出翅膀，在不被御剑发现的情况下降落到附近并朝他跑去。虽然我听不到他们究竟在说什么，但从肢体语言判断，御剑似乎是理解了。</p><p>很好，这样一来这件事就解决了。再来就是从半兽人那边收集讨伐成功的证据，以及搜刮能够变卖的东西。</p><p>我等到御剑离开后就动身朝下方移动。在跟萝莉梦魔一起搜索半兽人尸体并从中取得相当的收获后，便起身准备离开。</p><p>「明明半兽人这种魔物不会用多好的装备，你却找得相当认真呢。有找到好东西吗？」</p><p>「……完全没有。原本还想说至少能赚到一些钱，结果是白忙一场。不过因为有御剑负责战斗，所以我也乐得轻松。」</p><p>「讲到御剑先生，他对阿库娅小姐未免执着过头了，感觉有点恐怖呢。」</p><p>「毕竟都到去崇拜那家伙的地步了，他应该有哪里不太正常吧。」</p><p>「——你为什么会在这里？」</p><p>这道突然从背后传来而且似曾相识的声音是……</p><p>我战战兢兢地转过头去，就看到御剑双手抱胸瞪向这里。</p><p>「呃，哦，真巧啊。」</p><p>「是啊。因为不放心让女孩子独自回去村落我才回来确认，看来这是正确的选择呢。只是碰巧在半兽人集团的所在地相遇那还好说。不过你为什么会如此亲密地在跟那位村女交谈呢？感觉你们认识呢。」</p><p>这下不妙，他究竟观察到什么程度了？根据他听到的内容多寡，对应的方法也会有一百八十度的转变。</p><p>这时候必须要慎重的选择回话内容。</p><p>「我、我和达斯特先生没有任何关系喔！是刚刚才在这里相遇，连话都没还说过！」</p><p>「笨、笨蛋！你是天然呆吗！」</p><p>这家伙因为太焦急而犯下了致命性错误。</p><p>「哦～～明明都那么亲密地交谈过了？而且如果真的连话都没说过，你为什么会知道对方的名字呢？」</p><p>萝莉梦魔完全不反驳就泪眼汪汪地回过头望向我，拜托你现在别跟我求救啦。你面对逆境时也太没用了吧！</p><p>怎么办，这时候该怎么做才能度过危机？这不是我第一次或第二次陷入绝境了，快点想出一个能起死回生的方法！</p><p>「啊，我到底做了什么……这、这里是哪里？你、你不是梦魔吗！我、我想起来了，我完全是被这个恶魔给魅惑了！全都是这家伙不对！」</p><p>我将实行犯交给了御剑。</p><p>「等、等一下！达斯特先生，你这是在说什么啊！想出了这个诡计的人，根本就是达斯特先生啊！」</p><p>我使劲想推开眼泪汪汪抓紧我胸口的萝莉梦魔。</p><p>啊，可恶，这家伙意外地顽强耶，甩不开她！</p><p>「我完全听不懂你在说什么。喂，御剑，别被恶魔的花言巧语给骗了！恶魔是神的天敌。是你认识的那位祭司的天敌喔！」</p><p>「差劲！这个恶魔！人渣！垃圾！」</p><p>「哼，随便你怎么说都行，我只不过是最珍爱自己罢了！如果你也是梦魔，那至少用那副缺乏曲线的身体诱惑人给我看看！来，看到没有，她有着恶魔的尾巴吧！」</p><p>我把手伸进萝莉梦魔的裙子当中将她的尾巴拉出来后，御剑立刻将视线移开。</p><p>萝莉梦魔则是边不断喊着「变态！」边挥手殴打我，平时的打扮明明更加色情，实在难以理解她的羞耻心基准到底在哪。</p><p>「看来那位女性确实是恶魔没错。」</p><p>「是吧？那你就能理解我是冤枉的吧！」</p><p>很好，从这个走向来看我能得救。即使知道对方是恶魔，但御剑是个很好说话的男人，应该不会对这个至少外表是少女的家伙施暴才对。</p><p>为了让所有人都得救，这就是最好的办法。</p><p>「别被骗了！这个人明明用很便宜的价格买下御剑先生珍惜的魔剑，却用贵到离谱的价格卖给你，大赚了一笔喔！」</p><p>「混、混蛋，你为什么会知道这件事！」</p><p>「不就是你之前喝醉跑来我们店里时，自己很得意地拿来说嘴的吗！」</p><p>啊、啊啊，说起来我好像确实说了那样的话……</p><p>——拔剑出鞘的声音从前方传来。</p><p>「等等，等一下！这时候我们应该把收起武器推心置腹地交流才对。毕竟对话是只有人类才能使用的手段啊。」</p><p>「矮人和精灵，以及我们恶魔和魔物其实也相当懂得如何交流喔。」</p><p>闭嘴，萝莉梦魔！没看到我正拼上性命想让事情顺利收场吗，你识相点啊！</p><p>脸上完全不带一丝感情的御剑举剑摆出上段架势，同时用冰冷的视线看着我们。啊，那是讲再多借口都没有用的表情。</p><p>我迅速绕到萝莉梦魔背后，接着用力掀起她的裙子！</p><p>「哇啊啊啊啊啊啊！你在做什么！」</p><p>「你、你干嘛！」</p><p>你们都是不谙世事的少女吗。趁着御剑因为动摇将目光从这边移开时，我连忙将萝莉梦魔挟在腋下全力逃离现场。</p><p>「你、你给我站住！」</p><p>「哪里会有被叫站住就真的停下来的笨蛋啊！因为被另一根一柱擎天的魔剑妨碍，让你没办法好好奔跑对吧？不要太勉强啊！」</p><p>我没有忘记要在离开之前对他撂下嘲讽。</p><p>虽然没有余力回头确认他的表情相当可惜，但是就这样让我顺利逃走吧。</p><p>「我说啊，你真的不是恶魔吗？」</p><p>「你很烦耶，就说不是了！」</p><p>不要用怀疑的眼神看我啦，我真的只是一介善良的冒险者。</p><h3 id="_6-1" tabindex="-1"><a class="header-anchor" href="#_6-1"><span>6</span></a></h3><p>「可恶，实在有够倒楣耶。满怀期待去了一趟村落，结果跟我说年轻的大姊姊全都离开去大城镇了。还说什么美女成群，根本全都是干燥花嘛。等到隔天回到公会，御剑已经抢先跟各处打了通关，害我连一毛讨伐半兽人的奖金都拿不到。而且我做的事也统统被琳恩发现，她不但看不起我又一脸厌恶，甚至还逼我还钱。这就是所谓的祸不单行吧。」</p><p>「这我非常清楚，因为我也在场。」</p><p>冷静地对我的抱怨做出回应的萝莉梦魔，正忙着打扫店面。</p><p>由于不是营业时间，店内除了我和这家伙外没有其他客人及工作人员。</p><p>「因为妨碍到我了，可以请你回去吗？」</p><p>「这不是对待客人该有的态度吧？」</p><p>「你手边没钱对吧？」</p><p>「……是的。」</p><p>本来我现在应该已经赚了一笔才对，这全都是御剑的错。如果那家伙没做出多余的事，我现在应该正在爽快地喝上一杯。</p><p>「我会没钱全都是御剑的错。」</p><p>「达斯特先生，你知道自作自受这个成语吗？」</p><p>「那种东西早就从我的字典里撕掉了！」</p><p>「你还真是彻底的人渣呢。即使在恶魔当中也很难找到如此的人才喔。」</p><p>萝莉梦魔应该是在傻眼的同时也感到钦佩，只见正用扫帚打扫地板的她露出复杂的表情。</p><p>这个萝莉梦魔虽然姑且还是用恭敬的语气在跟我说话，但是跟初次见面时相比，用词开始变得有些随便呢。毕竟我最讨厌毕恭毕敬的感觉，所以不是很介意……但与其说我们的关系变得融洽，不如说是她看不起我……</p><p>还在对那天我出卖她的事情耿耿于怀吗？这家伙的器量实在有够狭小耶。</p><p>「唉，算了。然后啊，身为冒险者如果一直被人看扁实在有失颜面，所以我想找你稍微帮我一下。」</p><p>「我不要。」</p><p>还没把话听完就直接拒绝，看来这家伙正在警戒我。</p><p>「好啦好啦，你别这样说嘛，至少把话听完好吗？」</p><p>「一旦我听了，你就打算把我拖下泥沼对吧？」</p><p>「你到底把我当成什么了？」</p><p>「人类史上难得一见的人渣。」</p><p>「很好，就算你是女性我也不会手下留情。给我去那边跪坐，我就来让你见识什么是真正的人渣。绝对要把你的身体调教成再也不敢反抗我！」</p><p>当我折着手指朝萝莉梦魔逼近，对方也抓起扫把有模有样地摆出了迎战姿势。</p><p>「要是做出那种事情，你就永远别想再来这间店光顾了！」</p><p>「啧，你不要以为这样就能威胁到我！别太小看我了！是说看你从刚刚就忙着扫除，需不需要我帮忙啊？」</p><p>在听到这种威胁后我也只能屈服，毕竟无法光顾这间店可是事关生死的问题。</p><p>想要在不威胁她的情况下利用这个家伙……其实还有那个手段。</p><p>「抱歉。因为只要靠你当时卓越的演技，无论面对什么样的难关都能顺利度过，使得我忍不住对此抱持期待……才会不小心激动起来。」</p><p>我装作自己正在打从心底反省，并轻轻低下头去。</p><p>好了，在看到我的这副模样后，萝莉梦魔究竟会如何反应呢？</p><p>「真、真是的，听你讲成这样我不就没办法继续生气了吗。」</p><p>萝莉梦魔微微鼓起脸颊将视线从我身上错开……不习惯被夸奖的女人还真是好骗耶。就顺势再推她一把。</p><p>「毕竟你的演技好到连王都的舞台女演员都会自愧不如。由这样的你所施展的春梦肯定很不得了吧。唉～～真恨自己口袋没钱，如果能赚到工资，我下次一定会毫不犹豫指名你！」</p><p>「才没有到你说的那个地步呢。实在太过奖了，呵呵。」</p><p>满脸通红的萝莉梦魔大概是想掩饰害羞，只见她以高速扫着地板。这女孩实在好骗到令人担心。不过现在这样正好，真是帮了我大忙。</p><p>「真是不好意思，我原本认为以你的实力应该能轻易办到，是我不该没确认对方的意愿就开口协商。我会试着去拜托其他梦魔，唉～～」</p><p>失落地重重地叹了口气后，我斜眼瞄向萝莉梦魔确认她的样子，只见她露出一副「真是拿你没办法～～」的开心表情。</p><p>「真拿你没办法，就只有这一次喔。仅此一次的话我是可以帮你啦。」</p><p>身为一名梦魔，她这么好骗究竟是怎么回事啊？这样能够好好地当恶魔吗？像这样会被人类担心的恶魔，是要怎么混下去啊……</p><p>呃，但这不是我该去担心的事，转换一下心情吧。</p><p>「这样啊，那真是太感谢你了！那么，我想拜托你的是这件事。」</p><p>于是我开始在萝莉梦魔耳边低语，她一开始还不断点头，但是讲到最后她先惊讶地瞪大眼睛，接着就露出鄙视的眼神，还用冷冰的视线贯穿我。</p><p>「要我让御剑先生作梦是无所谓，但是这个内容……不会太过分吗？」</p><p>「身为恶魔的你不要摆出那种退避三舍的态度啦。不过就是用那名祭司的外表在梦中以色情的举止诱惑他，然后在离上床只差一步时……变成母半兽人反过来袭击他而已啊。」</p><p>「这个梦肯定会让人留下心灵创伤喔。而且就算想让御剑先生作梦，事情真的会那么顺利吗？那个人很强，他很有可能在我接近之前就察觉到吧？」</p><p>「不用担心啦。他的两名女跟班似乎就住在那家伙隔壁房间，而且每天都在吵吵闹闹，只是些许的小动静应该无法吵醒他。」</p><p>这是从可靠的门路那边得来的情报。好啦，就只是在公会偷听到那两名跟班的谈话罢了。</p><p>「而且，我会先准备好在紧要关头时的退路，也会帮忙把风。」</p><p>「那么……一旦感觉到危险我会立刻逃跑喔。」</p><p>「嗯，就这么做吧。这样一来复仇的准备就完成了。就让我一雪金钱和女人的仇恨吧，啊哈哈哈！」</p><p>「这个人果然是恶魔吧。」</p><p>至于萝莉梦魔的蠢话我决定一概无视。</p><h3 id="_7-1" tabindex="-1"><a class="header-anchor" href="#_7-1"><span>7</span></a></h3><p>我和萝莉梦魔仿佛要划破漆黑的夜晚般在小巷里飞奔。</p><p>「果然还是太勉强了啦！」</p><p>「啊～～吵死啦！现在给我闭上嘴专心逃跑！」</p><p>可恶，为什么会变成这样？直到潜入房间为止明明都还很顺利啊。</p><p>正当萝莉梦魔进入没有其他人在的房间并移动到御剑的枕边，即将开始让他作梦时——那两个女跟班突然就冲入房里，最好是有人能预想到这种状况啦！</p><p>「那两个该死的臭婆娘！女人不要主动去夜袭男人啦！」</p><p>「御剑先生也处于深层睡眠的状态，所以无论如何都无法让他作梦！感觉他应该是被灌醉的喔！」</p><p>这真是糟透了。虽然不知道究竟是谁灌醉御剑，但总算趁着在最麻烦的时机出现的两个人起争执时逃走……</p><p>「这个女色狼！给我站住！我已经记住你的长相了！」</p><p>「你应该没有碰到响夜吧！」</p><p>那两个女人真是纠缠不清耶！</p><p>由于萝莉梦魔是以店内的情色打扮潜入房间，为了不让她是梦魔的事情曝光，现在她身上披了件大衣。</p><p>因为房内很暗，没被看见翅膀和尾巴算是不幸中的大幸。</p><p>「虽然想飞起来逃走，但是这样根本逃不掉！」</p><p>「要是变成罪犯……你可别想独善其身啊。」</p><p>「我才不要！我如果遭逮就会被处理掉，所以请达斯特先生独自去认罪然后被逮捕吧！」</p><p>「我拒绝！被警察逮捕是无所谓，但是我绝对不要『因为潜入男人的房间』被逮！只有这个我坚决拒绝！」</p><p>这种事情一旦传出去，那我无论作为冒险者还是男人都彻底完蛋了。唯一可以想见的未来就是彻底被伙伴们抛弃，所以我绝对要逃掉！</p><p>「啊，可恶！我受够了！总算甩掉她们了。要是真的被抓住，那事情可会变得很麻烦耶。竟然被那种女人给缠上，我都要同情起御剑那个混蛋了。」</p><p>「讨厌，真是的！都是因为达斯特先生，情况才变得这么危险啦！」</p><p>结果我们一路逃到天亮，才总算保住自身的名节。</p><p>外头天色已经变亮。我们一路逃到大街上，看来现在是有些店家准备开门营业的时间了。</p><p>「唉，好累喔。我要先回去睡……达斯特先生，你在逃跑时甚至做出绑架这种行为吗？竟然把这么可爱的女孩子……」</p><p>这个萝莉梦魔到底在说什么啊？只见她紧盯着我……不对，她的视线有往旁边偏移。我顺着她的视线望去，发现有个小鬼站在那里。</p><p>那不是之前在公会的柜台前跑来跟我搭话，来自委托讨伐半兽人的村落的那名小鬼吗。她是从哪里冒出来的啊？</p><p>「叔叔，工作完成了吗？」</p><p>「小鬼，你还真是早起啊。我说过我不是叔叔了吧？」</p><p>「我不是小鬼，是小妹妹喔。所以啊，叔叔﹑叔叔，半兽人呢？约定呢？我的礼物呢？」</p><p>我完全不记得有跟这个小鬼做过什么约定，但是对这个家伙来说，那段对话就已经算是跟她约好了吗？</p><p>「啊啊，吵死了。这样总行了吧？」</p><p>我把一个包装得漂漂亮亮的小盒子朝小鬼丢了过去。小鬼一接住那个就露出白皙的牙齿高兴地笑了。</p><p>「你帮我找到了！谢谢你，帅气的大哥哥！」</p><p>由于那个小鬼不断回过头用力向我挥手，于是我甩甩手要她快点离开。</p><p>接着我的视线跟在一旁看着这段互动的萝莉梦魔对上。只见她速速移动到我身边，脸上更露出别有意涵的笑容。</p><p>「你会那么认真地翻找半兽人尸体的真正理由，就是那个吗？」</p><p>「才不是。只是在找值钱的物品时顺便找找而已，顺便。」</p><p>「哦～～原来是这样啊～～哦～～」</p><p>不要一边窃笑地看着我啦。</p><h2 id="第四章-与那位千金陷入爱河" tabindex="-1"><a class="header-anchor" href="#第四章-与那位千金陷入爱河"><span>第四章 与那位千金陷入爱河</span></a></h2><h3 id="_1-3" tabindex="-1"><a class="header-anchor" href="#_1-3"><span>1</span></a></h3><p>「一旦没钱，自然也没有女人！」</p><p>在公会平时的座位跟伙伴们喝酒时，虽然我起身大声喊叫，却被默默吃着饭的伙伴们彻底无视。</p><p>「那个酥炸蟾蜍看起来好好吃喔。给我吃一口，一点点就好，或是吃剩的骨头也无所谓，让我尝一下味道嘛～～」</p><p>「我、不、要。你先前不是才说过『我暂时不需要钱跟女人』吗？」</p><p>琳恩先用叉子叉起酥炸蟾蜍放进嘴里，接着叹了口气并用冷漠的眼神瞪着我。</p><p>「所以我这两天不是都乖乖的吗？」</p><p>「也不过就两天罢了。你会没钱完全是自作自受吧？你仗着能拿到机动要塞毁灭者的奖金，就赊帐跑去大吃大喝甚至还到处借钱，结果奖金太少不够还债才在伤脑筋对吧？根本不值得同情啦。」</p><p>「是啊，你就趁这个机会学会什么叫节制吧。」</p><p>就连泰勒也配合琳恩开始对我说教。</p><p>这群人真是没意思。一点一点存钱这种事根本不是男人该有的行为吧，豪气地花钱再一口气赚回来才是所谓的男子汉。</p><p>「实在不想当穷光蛋呢。哈，这酒真好喝！」</p><p>「喂，奇斯！为什么你有钱？你不是也有赊帐跟借钱吗？」</p><p>明明跟我一样四处挥霍，为什么只有这家伙还能优雅地吃饭啊？这也未免太奇怪了吧？</p><p>「因为我跟达斯特不同，赌博大赚了一笔啊！在穷光蛋面前喝的酒特别美味呢！」</p><p>不要把钞票摊开来扇风！可恶，赢了就在那边炫耀！如果我当时有押中，那现在就完全不同了！</p><p>「既然你这么有钱，那就借我一点啊。」</p><p>「才不要呢。这些都是我的钱，连一毛艾莉丝也不会拿来借给达斯特。不过如果你立刻把我的鞋子舔干净，并且说出『我是奇斯大人顺从的奴仆，一辈子都不会违抗您』这些话来奉承我，那我也是可以请你吃点什么啦。」</p><p>「混帐东西！谁会拜托你这种不讲义气的朋友啊！所以说泰勒，借我钱。」</p><p>「不借。等你把先前欠的还清再来找我。这时候对你严苛一点也是为你好。」</p><p>不愧是十字骑士，还是一样认真到根本是死板了。当伙伴遇到困难时，一般来说应该要爽快地请他吃饭吧。这群家伙真是够了，我身为他们的伙伴都感到丢脸。</p><p>「哼，我不会再拜托你们了！要道歉的话就趁现在喔！目前只要有酒、下酒菜以及十万艾莉丝我就原谅你们！不然等我变成富翁才来奉承我也没用！好了，快哭着求我原谅你们吧！」</p><p>「「「谁理你啊。」」」</p><p>「这个也好那个也罢，尽是些小气鬼！等我赚了大钱绝对要用钞票甩你们脸！」</p><p>然而就算再怎么有干劲，现在我的手边根本没有本钱可以用来投资赚钱。</p><p>虽然我的座右铭是轻松赚大钱，但所谓巧妇难为无米之炊。</p><p>唉，哪里有那种无论是钱或身体都需要人帮忙「处理」的贵族女人啊。算了，即使是我也很清楚，这世上不可能会有这么方便的女人。</p><p>「这不是达斯特吗，你在这里做什么？」</p><p>突然向我搭话的人，是和真小队的金发十字骑士。虽然她的外表和身材都出类拔萃……但是跟这家伙一起冒险过之后，我对她的印象就彻底改变了。</p><p>而且最近得知的那件事更是吓到我。</p><p>「嗨，达克妮丝……不对，拉拉蒂娜。」</p><p>「不准那样叫我！」</p><p>没想到达克妮丝只是假名，拉拉蒂娜这个可爱的名字才是本名。</p><p>我从来不曾想过她其实是号称本国首席参谋的达斯堤尼斯家的大小姐，原来她不只是空有坚硬的身体但攻击都打不中的十字骑士。</p><p>贵族尽是些麻烦家伙——我明明亲身体验过这件事，但是达克妮丝却没有贵族特有的厌恶感。这是因为她没有瞧不起平民，而是站在对等的立场上吧。</p><p>我曾经怀疑之所以完全听不到达斯堤尼斯家的负面评价，是因为他们巧妙地完全隐藏起来，但是现在看来，那些正面评价应该不全然是谎言。</p><p>虽然身为十字骑士，但只要无视那些奇怪的言行，她给人感觉就是一位受过良好教育的大小姐。如果去问她「为什么贵族大人要去当什么冒险者啊？」就太不识趣了。</p><p>「你一个人吗？还真是稀奇。和真他人呢？」</p><p>「我、我又不是随时都跟和真在一起！我们只是伙伴！」</p><p>这也不是什么需要拼命去否定的事情吧？毕竟一起冒险的伙伴，日常的行动模式也会很相似。</p><p>她是产生什么奇怪的误解了吗？不过这也无所谓啦。</p><p>「自从和真得到那栋豪宅后，他懒得出门的状况就恶化了，现在应该还在房里睡觉吧。」</p><p>如果有钱我也想享受那种慵懒地睡到中午，吃饱睡睡饱吃的生活。</p><p>「那你一个人打算做什么？」</p><p>「惠惠抓着阿库娅去一日一爆裂，我就一个人闲到发慌，所以打算久违地跟克莉丝一起出门冒险。」</p><p>「克莉丝是那个被和真偷走内裤还哭出来，胸部没什么料的银发盗贼吗？」</p><p>「喂，你可别在克莉丝面前讲这种话喔，她似乎相当在意这点。」</p><p>原来她会在意喔？那别穿得那么单薄不是比较好吗？话虽如此，但盗贼穿着轻便已经可以算是基本款了。</p><p>「那么，我赶时间先离开了。对了，麻烦你别老是跟和真一起做蠢事。」</p><p>「好啦。但话说回来，我不记得有做过什么蠢事啊？顶多就是在酒吧闹到天亮，对不顺眼的家伙使用『Steal』，让他在没内裤穿的状态下走回家这点程度而已喔。」</p><p>「你们做过这种事啊……没想到会有那样羞耻的玩法。下次得好好教训他才行。」</p><p>看着达克妮丝怒气冲冲离去的背影，我突然想到了一个主意。</p><p>「达克妮丝是达斯堤尼斯家的大小姐对吧。也就是说，她相当有钱喽……呵呵。」</p><p>我对贵族没留下什么好的回忆，但也很习惯应付贵族了。虽然有点在意她先前在战斗时做出的奇妙举动，不过是她的外貌不差，身材更是符合我的喜好。</p><p>如果能顺利骗倒她出钱包养我，那我不就成了人生赢家？虽然结婚会很麻烦，但只是恋人应该不会有问题。总觉得只要随便说些甜言蜜语就能轻松攻陷她呢。</p><p>隐约记得和真曾经说过达克妮丝是个很好哄的女人……好，首先是收集情报。既然要狩猎，就得先仔细调查猎物。</p><p>……去跟踪她吧。</p><h3 id="_2-3" tabindex="-1"><a class="header-anchor" href="#_2-3"><span>2</span></a></h3><p>我隐藏身影追上达克妮丝后，就看到她跟克莉丝在公会门口会合并往城外走去。</p><p>她们真的打算两个人去冒险吗？尽管盗贼和十字骑士的组合平衡很差，但也不是完全无法战斗。不过她们应该不会乱来吧？</p><p>我维持一定的距离偷偷摸摸跟在她们后面。</p><p>在先前的战斗中，我对达克妮丝的印象只有被初学者杀手咬住这件事，如今正是见识她真正实力的好机会，毕竟她当时根本没带武器和防具。</p><p>「那、那个，请问……为什么要带我一起过来呢？」</p><p>这个被我途中抓来的孤独女孩忐忑不安地向我问道。</p><p>「反正你也是一个人闲着吧？」</p><p>「只、只是偶然、碰巧，一个人而已……」</p><p>这女孩跟和真队上的爆裂女孩一样是红魔族，明明是优秀的魔法师却总是孤单一人。由于她非常不擅长交际又很害羞，一旦和真等人不在，她几乎都待在公会角落一个人玩。</p><p>她的名字叫作悠悠……有这种奇怪的名字，就肯定是红魔族。</p><p>「那就没问题啦。反正你除了一个人玩玩卡牌游戏及单人西洋棋外，也没有其他的事情可做了不是吗？」</p><p>「才、才没有那回事呢。我也有好好看个书，还会一个人玩桌游！而且我也很擅长观察人类喔。那个，还有就是……我最近把菜单全都背下来了！」</p><p>把公会一楼酒吧的菜单全部背下来了吗？这么说来，这家伙一直占着酒吧窗边的座位呢。</p><p>「从菜单的第一道开始点，全部点一遍就能得到相当的满足感喔！虽然我已经不记得自己点过几遍了。」</p><p>「喔、喔喔……你下次跟和真他们一起吃个饭吧？」</p><p>「可、可以吗？但是，如果妨碍到他们的小队聚会就不好了。」</p><p>「你就是因为太在意那些多余的事情，才会一直孤单一人啦。这种时候就算脸皮厚一些也无妨。用别人的钱吃饭喝酒根本是最棒的事情了，你为什么就是不懂呢？」</p><p>「我才不孤单呢！而且我必须出钱请朋友吃饭。在红魔之里时，我朋友冬冬菇跟软呼呼都说『我们是朋友』，我也经常请她们吃饭喔。」</p><p>「……如果这次能顺利赚到钱，我就请你吃饭吧。」</p><p>竟然能让我动摇……在听这家伙说话时，总是让我有种坐立难安的感觉。</p><p>悠悠虽然是个十四岁的小鬼，不过发育良好，也称得上是美女。一般来说男人不可能会放过这个目标，但不知为何就是没人要接近她。</p><p>而且悠悠并没有被讨厌，在冒险者之间的评价甚至可以说相当高，却还是……</p><p>「咦？你要请我吗！什么？达斯特先生要请客？所以是打算要我帮忙犯罪吗？」</p><p>「你说话也未免太毒了吧！我请客有那么奇怪吗？」</p><p>「很奇怪。」</p><p>「不要毫不犹豫就回答啦！比起那些事，把话题拉回来吧。我现在开始要去跟踪达克妮丝她们。你也跟我一起去。」</p><p>「咦？跟踪……达斯特先生也是那种不敢跟熟人打招呼，所以会在完全不曝光的情况下，偷偷跟在对方后面一整天的类型吗？」</p><p>「……至少去打声招呼吧。」</p><p>「怎、怎么可以呢。突然去打招呼要是打扰到对方就不好了。而且如果对方不把我当一回事，选择无视我不是很令人伤心吗……」</p><p>「就算再怎么不熟，也不会有人因为被打招呼就感到厌恶吧。我觉得你真的可以再坦荡一些……不对，只要跟你讲话就会一直跑题耶。我之所以要跟踪达克妮丝是有原因的。就是那个啊，那个……」</p><p>实在想不出什么的好理由。但是为了让悠悠接受就必须说出合适的谎话。</p><p>「你想想，虽然我跟和真是朋友，但跟他的伙伴们却算不上很熟对吧？既然是朋友的朋友，当然会想跟对方好好相处啊，这你应该可以理解吧？」</p><p>「我懂，我可以理解！如果能跟朋友的朋友成为朋友，就能慢慢增加朋友对吧！」</p><p>这家伙意外地对「朋友」这个关键字难以招架呢。</p><p>……为了不让悠悠被坏人骗，之后要偶尔提点她一下，但现在就让我利用她这种个性吧。</p><p>「是吧。这时候为了跟对方成为朋友，就必须先收集情报。如果能知道对方喜欢的东西或平常在做些什么，那聊天时也不用害怕没有话题了，你说对吧？」</p><p>「嗯嗯，的确是这样。因为惠惠就只会偷吃和闯祸，别说是找话题了，根本只能顾着去阻止或留意她而已。」</p><p>那个爆裂女孩干过偷吃这种事喔，这家伙已经很不得了了，但是那家伙也相当另类啊。</p><p>「而且，如果能跟达克妮丝成为朋友，那你不就能加深跟爆裂女孩之间的友情了吗？」</p><p>「是、是这样吗？惠、惠惠的事情怎么样都无所谓，但是你都说到这个地步了，就让我一起去吧！」</p><p>这女孩这么好懂真的帮大忙了。</p><p>虽然我是假装偶然遇到悠悠，但实际上是我在跟踪达克妮丝的途中，顺路绕去这家伙可能会出现的地方。</p><p>如同我的预测，她在书店前面盯着刚发售的新书。</p><p>当她站在恋爱小说区域边确认他人的视线边准备买个几本时，我正好开口搭话，让她吓了一大跳。</p><p>只要跟这家伙在一起，就算之后被发现也能把她当成借口吧。</p><h3 id="_3-2" tabindex="-1"><a class="header-anchor" href="#_3-2"><span>3</span></a></h3><p>达克妮丝她们在平原上移动一段时间后，前方冒出了哥布林。虽然是两人队伍，但敌人也只有两只，应该能轻松取胜吧。</p><p>首先是达克妮丝冲进哥布林当中，接着两只哥布林立刻扑了上去。</p><p>虽然达克妮丝的攻击连擦边都办不到，但即使被敌人的棍棒打中她也毫不畏惧。</p><p>或者该说她是自己冲进敌人的攻击当中？虽然克莉丝似乎打算伺机攻击，却被达克妮丝过大的动作给妨碍到。</p><p>「『Bind』！」</p><p>哦，克莉丝发动了能束缚对手的盗贼技能。这样就能封住哥布林的动作……喂，达克妮丝被绑住了耶。哥布林们也趁着达克妮丝被绳索一圈一圈缠住时上前围殴她……这是在干嘛？</p><p>啊，克莉丝移动到专心殴打达克妮丝的哥布林背后解决了一只。接着用相同的方法处理掉另一只。</p><p>……这个「Bind」的用法未免太奇怪了吧？一般不是对敌人使用吗？而且就我所见，达克妮丝似乎是主动跳进「Bind」当中。</p><p>「咦？咦？她刚刚是不是自己跳进『Bind』当中？」</p><p>「我也这么觉得。」</p><p>我不自觉地向拍着我的肩膀向我问道的悠悠表示肯定。</p><p>不过我们跟对方毕竟隔了一段距离，虽然表面上看上去如此，但实际上可能是两人的合作出现问题。这时候应该多观望一下再来判断。</p><p>两个人重新开始移动后不久，又出现了新的哥布林。这次总共有五只，以双人组合来说可能会有些难对付。所以我也考虑要是真的有个万一就下场帮忙。如果能在这时候留下好印象，那搭讪的成功率也会上升。</p><p>目前她们注意力都在敌人身上，应该没有余力发现我们。趁这时候移动到靠她们较近的岩场吧。这样就能在最好的时机现身。</p><p>虽然已经来到相当近的距离，不过无论是她们或哥布林都没有发现我们。</p><p>接近到这个地步也多少能听到她们的对话声了。</p><p>「达克妮丝。现在有五个敌人，你可不要再做出奇怪的事情喔。」</p><p>「知道了。我不会轻易地就向卑劣的哥布林屈服！」</p><p>「啊，嗯。但我要说的不是屈不屈服之类的事。」</p><p>「就算再怎么抵抗也只会被推倒，即使被那湿润又下流的细长舌头舔遍全身，我也不会那么轻易就陷落！你们要是办得到就试试看吧！不如说，快这么做！」</p><p>「达、达克妮丝！等等，等一下！」</p><p>达克妮丝就这样挥舞着大剑冲了出去。</p><p>虽然我隐隐约约有感觉到……但那家伙应该很有问题吧？虽然嘴上说着不会向哥布林屈服，但是那既兴奋又松懈的表情……</p><p>「啊啊，都是因为铠甲的扣环松脱，害铠甲自己脱落了！」</p><p>喂，为什么那个十字骑士边跑边熟练地脱下自己的铠甲啊？</p><p>「武器因为汗水从手中滑落了……唔，我失去所有抵抗的手段了吗……这么一来我不就要被哥布林蹂躏了吗……！」</p><p>这个人……竟然把武器丢掉了！</p><p>呼吸粗重，嘴角似乎很高兴地上扬……这家伙难不成是真的很兴奋吗？</p><p>虽然我知道战斗狂在战斗时情绪会特别高昂，但感觉达克妮丝的状况完全不同。这个感觉……比较像是梦魔店的客人所露出的表情。</p>`,319),e(f,{src:`/images/E1/02.avif`,alt:`插图`,width:`845`,height:`1200`}),s[11]||=a(`<p>「真是受不了你，给我老实一点！『Bind』！」</p><p>克莉丝对准达克妮丝发动了技能！</p><p>达克妮丝再次被绳索缠住并倒在地上。</p><p>「竟然在这种情况下动弹不得，我太大意了！」</p><p>不是吧！你根本没打算要躲开啊！</p><p>「你们打算对动弹不得的我做什么！难道，是想用那尖锐的爪子划破我的衣服吗！而且还打算只在胸部和重要的地方留下些许布料，然后用你们形状下流的棍棒——」</p><p>「我不会再让你继续说下去了！」</p><p>克莉丝向明明应该语言不通却退避三舍的哥布林发起了攻势。</p><p>哥布林也将注意力自达克妮丝身上移开，转头面对克莉丝。</p><p>「克莉丝，你再稍微等我一下！五分钟就好！只要再一下就行了！」</p><p>「不要露出一脸遗憾的表情！」</p><p>由于达克妮丝喊着难以理解的话语将哥布林的注意力拉走，克莉丝便趁机挥舞小刀划过它们的要害。</p><p>虽然两人的团队合作相当不错……但该怎么说呢。</p><p>单就结果而言两人完封了哥布林，但是我也开始有所犹豫，觉得跟达克妮丝扯上关系说不定是比我想像中还要无谋的行为。</p><p>她的言行不管怎么想都很危险。即使外表相当不错，甚至可以说很合我胃口……不过那些发言实在是……</p><p>「啊，咦？达克妮丝小姐的动作果然很奇怪吧？不知道是不是我的错觉，但是她似乎很喜欢挨打……」</p><p>「你果然也这么觉得吗？」</p><p>「啊，不过，说不定在跟人组队一起战斗时，这样才是正常的状态。毕竟我几乎没有跟别人组队战斗过……」</p><p>「别突然说出那么悲伤的事情啦……没这回事，是那个人超级异常。」</p><p>达克妮丝恐怕是所谓的——被虐狂。那种能够将肉体和精神上的痛楚转化为快感的变态。</p><p>「明明身材无可挑剔却是个变态啊……而且她根本已经病入膏肓了……」</p><p>「那个那个，请问挨打还能很开心究竟是怎么回事呢？」</p><p>「这种事小鬼不用知道。如果你无论如何都想知道详情，之后再去问爆裂女孩吧。」</p><p>看达克妮丝被哥布林用棍棒殴打时那副开心的表情，那家伙根本是超爆级的危险对象。最好还是别跟那种麻烦的女人扯上关系。</p><p>放弃吧，能握住那家伙缰绳的人也就只有和真了……还是在被发现前赶快离开吧。</p><p>原本我静静地转身准备离去，却在听见两人的交谈后不由得停下脚步。</p><p>「达克妮丝，如果老是做出这种事情，你总有一天会被和真他们抛弃喔。」</p><p>「你说什么……所以他们在彻底利用完我之后，就打算把变成破抹布的我丢掉吗！啊啊，这是何等的屈辱！」</p><p>「虽然嘴上这么说，但是你看起来很高兴呢。达克妮丝，我从以前就很想知道……你究竟喜欢什么样的男人啊？」</p><p>平时我对女生之间的这种无聊对话根本毫无兴趣，但到了最后至少来听听达克妮丝的喜好吧。只要有这份情报，我可以诱骗奇斯上钩，至少让他请我吃顿美味的大餐。而且……</p><p>「达斯特先生，请再稍等一下！我们再稍微听一下她们的对话吧！」</p><p>悠悠也死抓着我的袖子不放。只见她呼吸变得粗重，还露出兴致勃勃的眼神仔细聆听两人的对话。</p><p>……女人真的很喜欢恋爱话题呢。</p><p>「关于这点啊。体型是胖是瘦都无所谓，但是常用猥亵的视线盯着其他女人并露出下流的笑容，必要条件是整年都在发情看起来就很好色。如果是那种小看人生辛劳，只想尽可能轻松度日的废物分数会很高。如果还负债更是无可挑剔！而且还要成天喝酒不去工作……」</p><p>「够了，已经够了！达克妮丝，看来我得找机会跟你好好谈一谈！」</p><p>那家伙喜欢那种垃圾般的男人啊。如此恶劣的混蛋可是相当难找……喂，悠悠，你为什么要看着我？</p><p>「与其说达斯特先生完全符合条件，不如说根本就是在讲达斯特先生吧？」</p><p>而且还说出这种难以理解的话。</p><p>「喂喂，别说这种蠢话。我还没有烂到那种地步好吗？」</p><p>受不了，竟然如此看不起我。真要讲起来，那明明就是在指和真吧。</p><p>「呃，那么，请你回答我接下来提出的问题喔。」</p><p>「为什么那么突然啊？」</p><p>「第一个问题，如果有符合你胃口而且打扮煽情的女性出现在酒吧，请问你会怎么做？」</p><p>「遇上这种事还用多说，当然是立刻冲上去搭讪，然后假装喝醉伸手摸她的屁股啊。」</p><p>「…………」</p><p>喂，回点话啊。为什么要默默移开目光啊！</p><p>「第二个问题，什么都不做就能获得足以玩乐一辈子的金钱，以及与伙伴们一同渡过难关，并且在打倒强敌后取得大笔金钱和名誉，请问你会选哪——」</p><p>「当然是可以游手好闲的那一边啊。」</p><p>「竟、竟然急着抢答，唉。」</p><p>看着别人的脸叹气也太失礼了。刚才那题不管是谁肯定都会这么回答啊，完全不需要犹豫吧。</p><p>「第三个问题，请问你现在有欠债——」</p><p>「有啊。这根本是理所当然的事。」</p><p>「……第四个问题，不用工作就能喝到的酒比较好喝——」</p><p>「超棒的啦。」</p><p>「你跟达克妮丝小姐根本是天造地设的一对呢。」</p><p>这家伙竟然眯起眼睛露出温柔的笑容看着我。</p><p>刚刚那些问题无论拿去问谁，肯定都会说出跟我相同的回答吧。根本没有必要犹豫。</p><p>原本一在自说自话的悠悠突然陷入沉默，接着双手抱胸低下头开始碎念。她怎么突然变成这样啊？</p><p>持续碎念了好一阵子后，悠悠突然用力抬起头盯着我的脸，接着又重重点了一次头。</p><p>「啊！难道说，达斯特先生喜欢达克妮丝小姐吗？你是为了了解自己喜欢的人才会一路跟踪她啊。这么一想我就懂了。达斯特先生会这么关注她原来是为了这个！我有在小说中看过这种不坦率的主角喔！」</p><p>这、这家伙产生了相当严重的误解。</p><p>虽然一开始的确是这么打算。但在看到达克妮丝至今的言行后，我就彻底失去干劲了。</p><p>「虽然我之前认为跟达斯特先生交往这种事对女性来说根本是种拷问，但是在听到达克妮丝小姐的喜好后我就放心了。这件事情就尽管交给我吧！我可是看过很多本恋爱小说喔！」</p><p>「啊，看你激动成这样我也有点不好意思，但是达克妮丝实在太危险了……」</p><p>「不只是书，因为我对现实的恋爱非常有兴趣，所以我会好好加油！巴尼尔先生那次的状况实在太过特殊，但这次一定要成功！」</p><p>这家伙不行了，完全不肯听人说话。</p><p>这么说来，先前发生巴尼尔老大的恋爱骚动时，她也是一个人超级兴奋呢。</p><p>唔……关于达克妮丝的癖好，其实只要假装没看见就行了。</p><p>虽然一旦跟贵族这种存在牵扯太深，之后只会变得很复杂，不过还是尽可能让她沉迷并包养我吧。就这样决定了！</p><h3 id="_4-2" tabindex="-1"><a class="header-anchor" href="#_4-2"><span>4</span></a></h3><p>从那之后过了两天，悠悠把我约了出来，到她指定的咖啡厅一看，发现在场的并非只有悠悠，一位戴着面具身穿燕尾服的男人——巴尼尔老大也坐在她旁边。</p><p>巴尼尔老大似乎是魔界的公爵，拥有强大力量的恶魔。因为一些因缘，我和悠悠还有巴尼尔老大常会聚在一起。</p><p>至于那个契机，就是老大打工的那间魔道具店经营不善，我们原本是在冒险者公会讨论该怎么赚钱，最后却不知为何变成帮悠悠找起朋友。</p><p>在那之后虽然几经波折，但还是多少消解了这家伙交不到朋友的状况，我们也就这么一路相处至今。</p><p>话说回来，为什么老大会出现在这种地方？</p><p>「太慢了！明明说好是快中午时集合，但现在都已经是下午了！啊，不好意思！我们晚一点才要点餐。」</p><p>悠悠不断低头向女服务员致歉。看来女服务员在我抵达前已经等了好一段时间，只见她一瞬间露出不悦的神情，接着就往店内走去。</p><p>「想让我遵守约定你还早了十年啦！」</p><p>「为什么迟到的人还能那么嚣张啊！」</p><p>「汝还是跟以前一样，是个出色的人渣呢。吾是因为看见能够品尝到汝的优质负面情感的未来才决定参一脚，但没想到竟然让吾等了这么久。」</p><p>「抱歉了，老大。只有这家伙的话让她等多久都无所谓，但我不知道老大也在啊。」</p><p>「因为这个对『朋友』一词有过度反应的红魔族小姑娘，突然跑来到吾打工的店全神贯注地看书。吾在偷看她的未来后发现事情似乎会变得很有趣，于是便跟着来了。」</p><p>「什么叫作『让那家伙等多久都无所谓』啊！唉，算了。比起这个，重点是追求达克妮丝小姐的方法。」</p><p>「追求达克妮丝……你在说什么？」</p><p>真是受不了，她是刚睡醒吗？竟然说出这种莫名其妙的话。</p><p>为什么我要去追那种超爆级的被虐女啊？</p><p>「你、你是真的忘记了吗……难道说你的脑袋里面其实塞满了琼脂史莱姆？如果从达斯特先生那边夺走欲望，究竟还能留下什么啊？」</p><p>我本来以为她会生气，结果却是突然用同情的眼神看着我。</p><p>「啥？人类这种生物不就是为了欲望而活吗？虽然偶尔也会出现那种为了工作而活的人，但他们肯定是脑袋进水啦。只为了满足自身欲望而活，为了得到能拿去玩乐的钱而工作，这才是所谓的人类！」</p><p>对，即使活得正直清廉也不会有什么好事。这么一来当然要尽情享受自己的人生。这可是只属于你，跟别人无关的一生啊。</p><p>「这种话还能说得如此斩钉截铁，反而令人感到佩服呢。明知这是废物特有的想法，但内心还是多少有点动摇……」</p><p>「真是深受恶魔喜爱的人类啊。太棒了，这种颓废的想法真的是太棒了！虽然汝想表达的只有『我想轻轻松松地活下去』，但这种靠打高空来掩饰的说法真是太厉害了。」</p><p>「能得到老大的夸奖，真是令我感到光荣。」</p><p>咦？等一下？被身为恶魔的老大夸奖真的是值得开心的事吗？感觉这就像是在说我身为一个人很有问题……不过现在就先不要去在意吧。</p><p>「等等，那种事根本无所谓！明明是你硬逼着我帮忙，结果当事人却忘了这件事到底是怎样啦！」</p><p>「啊，好像有这么一回事呢。因为昨天拍和真马屁让他请我喝酒，所以全都忘光了。」</p><p>「我记得和真先生还有跟国家预算相当的欠款吧？你竟然让这种人请客……」</p><p>「没错，谁教我跟和真是挚友呢！」</p><p>「那才不是挚友！就只是损友……」</p><p>悠悠抱着头叹了口气。</p><p>这家伙完全不懂，损友跟挚友根本就是同义词。</p><p>「你为什么那么累啊？该不会是在晚上努力过头了？」</p><p>「你、你、你到底在说什么？怎么可以对女孩子说这种话！」</p><p>「喂喂，你是不是误会了什么。我只是担心你晚上看书看得太专心导致熬夜，所以现在才这么累啊。所以说你到底误会了什么？快用那张可爱的嘴巴详细地告诉我吧。」</p><p>「这、这是性骚扰！」</p><p>虽然悠悠小题大做地说了什么性骚扰，但这只是在跟女性打招呼罢了。虽然要是跟柜台小姐露娜说出类似的话，她会有大约一个星期完全不分发工作给我。</p><p>在那个家伙面前不能讲到跟男性有关，或是恋爱话题。听说是工作太忙让她完全没空交男朋友，所以在面对露娜时，绝对不可以说出「结婚」这个会让她反应过度的词汇。这算是冒险者之间的共同默契。</p><p>「唔嗯，真是美妙的负面情感！看来只要有汝等在，吾就无须担心会饿肚子呢。顺带一提，那个在关键时刻总是犹豫不决的弱鸡冒险者，已经有足够的金钱能还清债务了。」</p><p>不知不觉间和真也混得越来越好了呢。</p><p>听说他是透过将新的发明卖给老大来赚钱，看来他作为商人的本事相当值得学习。</p><p>「回到刚才的话题吧。为了了解最近的恋爱观，所以我重新学习了一番。请看这个，这些是我的部分藏书，是最近非常流行的恋爱小说。」</p><p>悠悠将原本堆在桌子角落的小说拿到我面前排开。</p><p>由于她总是一个人独处，所以非常了解跟书本有关的事情。</p><p>《您的名字》、《在魔界的中心躲避姊夫》、《想吃你和内脏》，这些书名怎么都这么奇怪啊？</p><p>「这些都是同一位作者写的作品，据说那位老师来自遥远的国度，非常擅长写恋爱小说。在他生前似乎经常把『这部作品是我的原创，绝对不是抄袭！』这段话挂在嘴边，好强调自己的独创性呢。」</p><p>「那些事情怎样都好啦，所以你想讲什么？」</p><p>「这些都是在年轻女性之间人气很高的恋爱小说。换句话说，这里面描绘了女性梦寐以求的理想恋情。」</p><p>「原来如此。我对这些一窍不通。」</p><p>「唔嗯，吾之管辖权不包含人类的恋情呢。」</p><p>「果然如此。在露娜小姐的那件事当中，我已经彻底体会到两位在恋爱上有多么不可靠了。所以我就参考这些小说，试着思考能让女生怦然心动的场面。这就是我的成果！」</p><p>悠悠取出她事先准备好的纸张，啪的一声用力放到桌面上。</p><p>纸上密密麻麻写满了字。这家伙刚要她帮忙时明明那么不甘愿，一旦开始动手又变得干劲十足了。</p><p>「从最简单的开始尝试吧。首先是壁咚！」</p><p>「哦，那个的话我就知道。因为我在威胁别人时经常会用到。」</p><p>「这是靠着展现强大的腕力，来显示自身雄性魅力的手段吗？」</p><p>在酒吧强迫看起来就很软弱的家伙请客时常用的手段。先把对方逼到墙边，接着用力拍墙壁让对方吓到腿软。</p><p>「不对。虽然做法类似，不过这跟那个不一样。巴尼尔先生明明跟达斯特先生不同，平时都非常可靠，但是一遇上跟恋爱有关的事就派不上用场了呢。所以说，趁着女性靠在墙边时站到她面前，然后把手咚的一声按在那位女性头边墙壁上的行为，就是所谓的壁咚。」</p><p>「……根本完全一样吧？面对这种事情，到底为什么会高兴啊？啊，不过达克妮丝是那个，所以可能会很高兴呢。」</p><p>「那位有着特殊癖好的女孩应该会高兴吧。不如说不要对墙壁，而是直接殴打她身体效果应该会更好喔。」</p><p>「不可以做那种事情啦！再来就是最经典的场景，当她陷入危机时飒爽登场出手搭救也是一招，毕竟大家都对这种场面充满了憧憬！」</p><p>「这样的话，得请奇斯帮忙袭击达克妮丝啊……但那家伙在真的遇上危机时，反而会很高兴吧？」</p><p>「唔嗯。比起负面情感，吾应该会收到愉悦的情感吧。」</p><p>由于仔细观察过达克妮丝所以我对此抱持确信。既然老大也持相同意见那肯定不会错了。</p><p>「是、是那样吗？那么这个方案先保留吧。不然就是赠送礼物，这你觉得如何？毕竟不会有收到礼物反而感到不高兴的人。」</p><p>礼物啊。虽然我喜欢收礼物，却非常讨厌送别人礼物。不过我也知道这招的效果很好。但要让达克妮丝收到会非常高兴的礼物啊……</p><p>「你收到什么样的礼物时会觉得高兴？」</p><p>「我吗……我想想喔，例如可爱的花朵，只、只是愿意当我的朋友也可以。」</p><p>先不管前半，后半的部分……虽然最近像我和老大这样能和她交流的人有逐渐增加，但是她的朋友依然压倒性的少。</p><p>「顺便问一下，老大觉得送什么礼物会比较好？」</p><p>「鞭子、蜡烛以及麻绳是很好的选择吧？不然送三角柱她应该也会很高兴。」</p><p>「咦？送别人那种东西是要用来做什么呢？」</p><p>悠悠歪着头问道，但是我不打算跟她仔细说明。</p><p>虽然我觉得老大的提案很棒，但是感觉刚递出去就会被砍啊。</p><p>不过要送礼物啊……这么说来达克妮丝到底喜欢什么？</p><p>「如果能知道她的喜好那就简单了。」</p><p>「达克妮丝小姐喜欢的东西吗？不然问问她的朋友吧？」</p><p>「也对，来去问问看和真等人吧，他们应该至少会知道一两个她喜欢的东西吧。」</p><p>「能够看穿一切的大恶魔巴尼尔在此宣言！就让吾作壁上观吧，这样才能迎来最有趣的未来。」</p><p>「虽然很在意巴尼尔先生的发言……但我也会试着去收集情报，我们一起加油吧！」</p><p>悠悠感觉比我更有干劲耶。虽然嘴上说了那么多，但女生果然都对恋爱相关的事情很有兴趣呢。</p><p>我也稍微努力看看吧。</p><p>「请问，是不是能请你们点餐了？还有，请安静一些。」</p><p>从旁介入我们对话的人，是太阳穴上冒着青筋仍努力压抑怒火，脸上挂着专业笑容的女服务员。</p><p>这么说来这里是咖啡厅呢，聊的太专心都忘了这件事。</p><p>「对、对不起！那个，不然就点个三人份推荐套餐吧？」</p><p>「你在说什么啊？不要擅自帮我点餐！当然如果你要请客我是可以吃啦，但这样还不如找间更像样的店顺便请我喝酒。附带一提，即使要我付钱我也没钱就是了。」</p><p>「讬那个无能老板的福，吾现在手头很紧，所以不打算付多余的开销。而且考虑到成本，比起在这种靠装潢赚取暴利的店消费，买材料回家自己煮还更加划算。」</p><p>听到我和巴尼尔老大老实说出内心的想法后，女服务员脸上浮现出血管。她深深地吸了一口气，用力瞪着我们开口：</p><p>「请你们立刻离开！」</p><h3 id="_5-2" tabindex="-1"><a class="header-anchor" href="#_5-2"><span>5</span></a></h3><p>几天后，我们召开了作战会议。</p><p>由于悠悠表示「已经不能再去了……」，不愿意去先前那间咖啡厅，没有办法的我只好选择能够免费使用，而且大家都很熟悉的地方——杂货店的门口作为集合地点。</p><p>由于巴尼尔老大忙着处罚老板，所以要晚一点才过来会合。</p><p>「虽然目前还没收集到完善的情报，不过达克妮丝小姐似乎没什么物欲，这可是我从惠惠那边得到的确切消息喔。据说被问到想要的东西时，她是回答『硬要说应该是武器和防具』。不过这方面也因为收到新的铠甲作为讨伐魔王军干部的报酬，所以我觉得效果会不太好。」</p><p>「哦～～是这样啊。」</p><p>悠悠还真是有够认真耶。明明跟自己无关，却非常认真地帮忙做了调查。</p><p>感觉她因为总是孤单一人，所以有人请她帮忙让她很开心吧，只见悠悠非常雀跃地发表着她情报收集的成果。</p><p>「还有还有，达克妮丝小姐似乎很讨厌别人叫她的本名拉拉蒂娜。所以无论如何，都请你不要用本名称呼她喔。」</p><p>「哦～～哈呼哈呼。」</p><p>「喂，达斯特，别吃我便当的配菜！」</p><p>「大叔你实在有够小气耶，这又不会怎样。我可是从昨天开始就什么都没吃耶！」</p><p>真是够了，只是配菜被夺走就生气，真是幼稚。真希望你能成为那种只要看到有饿着肚子的年轻人，就会主动请他吃饭的伟大大叔呢。</p><p>「由于很可能无法靠物品吸引她的目光，所以送花束说不定比较妥当。毕竟女孩子收到花束都会很高兴。」</p><p>「哦～～好，那个也是我的了！」</p><p>「哼，怎么可能让你得逞。」</p><p>可恶，大叔靠着出乎意料的灵敏动作守住了配菜，真没想到他连在杂货店狭窄的店内都能顺利躲开。</p><p>那么我也展现出自己靠冒险磨练的技巧吧，就让大叔好好认清我们的等级差距。</p><p>我对准便当盒里的配菜发动了连续攻击。然而大叔就仿佛能预料我的行动般，轻巧地退了几步拉开他跟我之间的距离。</p><p>「我可是日日夜夜都在跟小偷及奥客战斗，你可不要小看我的实力。」</p><p>「你还真是厉害呢，大叔。那我也只能拿出真本事了。」</p><p>我朝着打算死守便当的大叔一步步逼近。</p><p>这位大叔的动作毫无破绽，难道说他原本是冒险者？</p><p>「你到底在做什么！有认真在听我说话吗？」</p><p>「事情都变成这样了你还看不懂吗？我现在正在忙，你的情报我之后再听。」</p><p>「你这家伙每次都把别人的店面当成自己的集散地！这里没有任何给你吃的东西！连一粒米都没有！」</p><p>撂下狠话后，大叔就在我的面前将剩下的便当一口气吃光了！</p><p>「你这个混蛋！那可是我贵重的能量来源啊！」</p><p>「讲什么鬼话，这些全都是属于我的东西。话说这位小姐，如果跟这种小混混走得太近，只会让你的人生变得一塌煳涂喔。无论如何，都别再靠近达斯特了。」</p><p>大叔摆出一副令我不寒而栗，极度不适合他的温柔表情把手搭到悠悠的肩膀上……这是性骚扰喔。</p><p>「非、非常感谢你愿意像这样担心我，但是……那个……好歹……即使只是假设，我和达斯特先生也是名义上的朋友。」</p><p>「达斯特……虽然我从以前就觉得你是个人渣，不过你到底干了什么丧尽天良的事……」</p><p>大叔不但用颤抖的手指指着我，还露出至今不曾出现过的冰冷目光。看来他彻底误会了。</p><p>「喂喂，不要误会我好吗？我只是因为看这个落单的家伙很寂寞的样子，所以才当她的朋友而已！」</p><p>「小姐，这家伙就像是用来摆在人渣展示会上的样品。要是跟他走得太近，会在不知不觉间感染达斯特细菌，让你从精神上变成废人，所以千万要小心啊。」</p><p>「很好，大叔，给我出来输赢，我要矫正你那个已经腐烂的本性！」</p><p>「如果说我的本性已经腐烂，那你还没烂到回归尘土也未免太奇怪了吧？」</p><p>就在我跟大叔的额头撞在一起互不退让时，悠悠从旁介入用力想把我们两人拉开。</p><p>「够了，请两位都适可而止！」</p><p>「看来你捡回一条命了，大叔。看在这家伙的面子上，我今天就放过你吧。」</p><p>「那是我要说的吧。你不要再来了！但如果是小姐自己来，我就很欢迎喔。」</p><p>大叔挥挥手要我磙到一边去，我才刚竖起中指比回去，就被悠悠拉着手臂拖开，我只好不情不愿地离开杂货店。</p><p>在朝着大街移动的途中我回过头，就发现悠悠的脸颊如同松鼠的颊囊般鼓了起来。她是在嘴里塞了什么食物吗？</p><p>「真是够了，为什么达斯特先生无论去哪里都要引发问题啊！」</p><p>「我才没有引发问题呢，明明是别人擅自造成骚动。」</p><p>「竟然毫无自觉，看来已经没救了……」</p><p>又是细菌又是没救，这些家伙还真是想说什么就说什么耶。如果不是悠悠目前正在协助我，我绝对要好好惩罚她。</p><p>啊，不过这家伙毕竟还是个小鬼。虽然发育得很好，但我跟和真不同，可不是萝莉控。</p><p>「那个，你刚刚是不是在想非常失礼的事？」</p><p>「别在意。然后你刚才说了什么？」</p><p>「所以说，你对达克妮丝小姐有没有什么新的认识？你应该有调查过吧？」</p><p>「啊，那个啊。因为我忙着奉承和真要他请客，都完全忘了这件事。」</p><p>「你又让和真先生请客……」</p><p>「还不是因为那群人都禁不起奉承。毕竟轻松就赚了大钱，所以也很简单就愿意请客。人果然就该结识这么大方的朋友啊。」</p><p>「算了，我已经没有力气去吐嘈了。我也差不多学会『不该对达斯特先生抱有期待』这件事了。」</p><p>你不用垂头丧气失落成这样吧？那么一来不就搞得好像我很没用了吗。就不能别去在乎细节，活得更加豁达吗？</p><p>「哎呀，看来吾错过能品尝负面感情的时机了。」</p><p>「嗨，老大。你的事情都处理好了吗？」</p><p>巴尼尔老大今天也是一副引人注目的打扮呢。</p><p>虽然老大很适合燕尾服及白手套，但是那副面具实在太过可疑，何况他今天还穿了一件粉红色的围裙。</p><p>这副打扮原本应该会被好奇的眼光围观，但这座城镇的居民都早已习惯，所以没人在意。</p><p>「因为吾用巴尼尔式杀人光线将她烤得恰到好处，所以没问题。」</p><p>「我觉得充满了问题耶……」</p><p>「如果那家伙会因为那种程度就挂掉，那吾也不会这么辛苦了。」</p><p>说起来魔道具店的老板虽然是个大美女，但似乎是个废物。听说她拥有能将巴尼尔老大赚来的钱全都转为冤枉钱的特技。明明身为大恶魔，老大也是很辛苦呢。</p><p>我们三人有一搭没一搭地边走边聊，等回过神时已经走进暗巷当中。</p><p>一般来说这种地方似合用来痛殴找碴的小混混，偶尔也能从丢弃的垃圾中捡到好东西，所以我经常会过来。难道我是下意识就往这边走吗？</p><p>「啊！你把我带进这种暗巷究竟打算对我做什么？难道因为我们成为朋友，你就打算强占我的身体吗！我才没有那么随便呢！」</p><p>为了保护身体，一脸惊恐的悠悠紧紧抱住了自己。</p><p>「别闹了。我怎么可能对毫无魅惑度可言的臭小鬼出手啊！」</p><p>「啊！你竟然说我是臭小鬼！跟惠惠相比我发育得要好多了，请你更正那段发言！」</p><p>「这个臭小鬼还真是麻烦耶！老大，你也帮我说些什么啦！」</p><p>突然被我点名的巴尼尔老大轻轻歪过头，用手抵着下巴陷入沉思。</p><p>接着他啪地一声拍了手，在点了几次头之后说道：</p><p>「唔嗯。因为在恋爱上被挚友远远甩开而感到焦急的女孩啊，汝的朋友最近将会取得相当不错的进展喔。」</p><p>「这、这是谎言对吧？咦，那个『不错的进展』究竟是到什么程度？」</p><p>「真的吗，老大！和真那个混蛋，他打算比我早一步踏上大人的阶梯吗？」</p><p>看到我和悠悠情不自禁开口逼问，老大的嘴角浮现出邪恶的笑容。</p><p>这个发展是……</p><p>「真是美味的负面情感啊。不用担心，那个到了关键时刻就会退缩的男人，不会立刻就有什么太大的进展。」</p><p>「太、太好了。要、要是真的接吻了，那惠惠肯定会跟我炫耀。」</p><p>「你是在担心接吻喔……」</p><p>「如果汝是刻意这么说，那么吾应该会谴责汝吧，不过吾也不相信这是汝的真心话。」</p><p>「呃，咦？我说了什么奇怪的事情吗？」</p><p>「先不要管小孩子了，请详细告诉我和真他们的进——」</p><p>「你、你们在做什么！」</p><p>这时暗巷中突然响起女性的声音。</p><p>虽然那个语气比起惨叫感觉更像是在喝骂，不过是年轻女性的声音。</p><p>「刚才那道声音的来源应该是在对面！」</p><p>「了解！」</p><p>我当机立断往声音来源冲了过去。巴尼尔老大和悠悠也从后面追了上来。</p><p>「我好意外喔。达斯特先生竟然会毫不犹豫就去救人。」</p><p>「嗯，吾原本以为汝会嫌麻烦选择无视呢。」</p><p>「我下次再仔细询问你们到底是怎样看待我，但这是理所当然的行为吧。这里可是那种地方喔！无论对方是被小混混或色狼缠上，都肯定是发生了犯罪行为。只要赶去搭救，不仅能从女性那边收取谢礼，如果一切顺利甚至能搭讪对方。再加上可以从被打倒的小混混那边搜刮钱财，这完全是一举数得吧。」</p><p>「哇、哇啊……」</p><p>「真是个深深符合恶魔喜好，理想中的小混混呢。」</p><p>我没有急着现身而是潜伏在暗巷的转角后方，暗中观察声音的来源。</p><p>一名女性正遭到数名蒙面人包围。其中两人拿着短剑，还有一人握着长枪，遇袭的女性没有穿戴铠甲，手上也没有武器，只是面露恐惧……恐惧……喂，她感觉很高兴耶，甚至可以说非常愉悦。</p><p>……为什么达克妮丝会出现在这种地方啊？</p><p>「必、必须去救……」</p><p>「嘘，再稍微观望一下。」</p><p>「由吾出手搭救未免太不识趣了，吾就在一旁看戏吧。」</p><p>悠悠才刚追上来，我就立刻捂住她的嘴巴让她闭嘴。</p><p>对方的人数实在太多，再加上达克妮丝看起来也没有受伤，所以我们也不用急着跳出去。</p><p>虽然对巴尼尔老大而来说，那种程度的对手根本不算什么，但是他似乎不打算出手。毕竟身为大恶魔的巴尼尔老大会随着心情行动，所以太依赖他反而会吃大亏。</p><p>因为感觉没有人注意到这边的动静，我决定竖起耳朵暂时观望接下来的状况。</p><p>「你们打算做什么！」</p><p>「你就是拉拉蒂娜大人对吧？」</p><p>「知道我的身分仍做出这种犯行吗！你们究竟有什么目的！」</p><p>「那个就要请你之后自己去问你的父亲了……如果还想要平安跟家人团聚，能请你老老实实跟我们走一趟吗？」</p><p>看来这是比想像中还要严重的大事呢。明知达克妮丝是达斯提尼斯家的千金依然动手袭击，这表示对方的目的如果不是权力争夺，就是打算勒索赎金。</p><p>「……真麻烦。」</p><p>「咦？你刚刚说了什么？」</p><p>哎呀，不小心讲出真心话了。虽然经验告诉我，最好不要跟贵族的纠纷有所瓜葛，但是也不能装作没有看到。</p><p>「抓住我之后你们打算做什么！」</p><p>「呵呵呵，这就要取决于你的态度了。」</p><p>「难道你们打算将我当成威胁父亲的手段，边说不会加害我边强行将我的衣服割开，并且将过程全都拍成照片保存吗！」</p><p>「……啥？」</p><p>「接着为了防止我逃跑，你们打算在福斯面前展示我几乎全裸的模样，将麻绳绑在我的脖子上，要我爬行阿克塞尔城镇一圈对吧！这是何等卑劣的发想！」</p><p>「……咦？」</p><p>虽然因为他们都蒙着脸看不到表情，但连我都能感觉到这群人正在动摇。真是可怜，他们因为不知该如何是好，所以显得相当狼狈呢。</p><p>这群人肯定没有想到自己打算绑架的千金大小姐会是这副德性吧。</p><p>「看来还是过去帮忙会比较好吧？」</p><p>「这个……真的很难说呢。」</p><p>「吾只能从最近开始在意起腹肌的女十字骑士那边，感觉到喜悦的情感耶。」</p><p>我的心情跟不知所措的悠悠一样。如果相信巴尼尔老大的判断，那过去帮忙也只是多管闲事……</p><p>当事人的癖好先放着不管，目前的状况的确相当危险。</p><p>要是放过了这场绑票事件将会引起大骚动。而且和真总是在请我，怎么说我也欠他一个人情。这种时候怎么样……也不能见死不救。</p><p>「我将会在这种肮脏的巷弄中，被素不相识的男人们为所欲为吗！呼、呼……但是我身为骑士，绝对不可以这么简单就屈服！」</p><p>后半句我觉得根本毫无说服力。</p><p>看到达克妮丝的眼神中透露着期待，嘴角也松懈到几乎快要流出口水……让我渐渐不想上前帮忙。</p><p>那群蒙面人同样也是不知所措。被逼入绝境的一方敞开双手迈步前进，蒙面人反而向后退开。</p><p>这能称为一进一退的攻防战吗？</p><p>虽然觉得放着不管也不会出事，但我却在这时想起了我们最初的目的——要让达克妮丝见识我帅气的一面。</p><p>「来啊，怎么了！你们就只有这点程度吗！我这个弱女子现在毫无防备，这时候你们礼貌上应该要袭击我吧！快让我见识一下你们身为坏人的尊严啊！」</p><p>弱女子？这里有这种存在吗？</p><p>「喂，这家伙真的是贵族的千金大小姐吗？」</p><p>「虽然跟我拿到的照片长得一样……但也有可能只是长得很像吧……」</p><p>那群蒙面人开始变得疑神疑鬼了。不过话说回来，我真的是太小看达克妮丝的变态程度了，想跟这种人交往什么的根本就脑袋有洞。</p><p>「怎么了？是在害怕手无寸铁的女人吗！难道你们打算要我自己亲手一件一件脱下衣服，用行动表示我不会反抗吗！是先从上衣开始吗！还是要先从鞋子开始！」</p><p>如果她真的打算脱衣服，那我就晚一点再去救人吧。</p><p>「不了，我们没有那种兴趣。」</p><p>「看到那种过度成熟的身体也没意思吧？」</p><p>「就是说啊。」</p><p>这群人是怎样？为什么突然冷静下来了？</p><p>就连情绪高涨的达克妮丝也因为对面的态度变得不知所措，不再继续吐露自己的妄想。</p><p>双方的视线交错，现场充斥着诡谲的气氛。</p><p>「我觉得已经可以回去了。」</p><p>「唔嗯。看来不会有比目前更加有趣的发展了。吾能从那些男人那边感觉到相当复杂的负面情感。这是……不悦的情感啊。」</p><p>「那个，这姑且算是少女的危机吧。如果她真的被绑架那事情就不妙了。」</p><p>悠悠说的也没错……如果这是特殊玩法那直接无视也没关系，但是绑票我就无法接受了，趁现在攻其不备应该能打倒两个人吧。</p><p>「那我现在就冲过去，万一局面变糟了你要来帮我。」</p><p>「好的，这当然没有问题……但是我用魔法赶跑他们应该更快吧？」</p><p>「这样我就没办法卖人情给达克妮丝了。即使状况不妙你也要等到最后一刻才出手啊，拜托你了。老大怎么打算？」</p><p>「由吾出手未免太无趣了吧？就让吾旁观吧。」</p><p>我早就预料到老大不会出手。</p><p>趁着那群蒙面人的注意力都在步步逼近的达克妮丝身上，我用入鞘的剑放倒了背对我的两个人。</p><p>「你、你是什么时候！」</p><p>「这不是达斯特吗！」</p><p>「喔，我来救你了。」</p><p>「……就算再晚一点来也无妨啊……」</p><p>我向吃惊的两人轻轻挥了挥手。虽然能听见达克妮丝的低声细语，但这也在我的预料之中，所以就当作没听见。</p><p>蒙面人无视达克妮丝，并将枪尖对准了我。</p><p>长枪啊。虽然一般人都觉得长枪在狭窄的巷弄内会被长度干扰很难挥舞，但要是以突刺作为主要攻击，敌人也会因为没有闪避空间无法靠近自己……如果是长枪手应该会这么思考吧。</p><p>「要是敢碍事，我就用这把枪刺穿你！」</p><p>对方的架势相当到位，看来他对自己的本事很有自信。</p><p>面对这样的对手，我将收到鞘中的剑扛在肩上，漫不经心地前进。</p><p>「看来你很想死呢！喝啊啊啊！」</p><p>枪尖伴随尖锐的呐喊向我刺出，我则是挥动剑鞘使其偏移轨道。</p><p>真是可惜。如果你的武器不是长枪，说不定还有那么一点点能够打倒我的可能性呢！</p><p>虽然因为戴着面罩使得我看不到他的表情，不过他应该是因为吃惊当场愣住了吧。当我对准他的眉心准备挥剑时——</p><p>「头目！」</p><p>听见后方传来一道破风的声音，我的身体立刻就往一旁跳开。</p><p>箭矢就这样掠过我的侧腹刺入地面。</p><p>回头一看，发现眼前有三名新来的蒙面人从另一条路出现！</p><p>「来得正好。你们快把那个小子解决掉！」</p><p>「这下不妙了。果然不该抱持什么奇怪的正义感啊。」</p><p>正面迎击这么多对手实在相当吃力。就算想逃，在被包夹的状态下我也无路可退。</p><p>而且虽然很有可能是错觉，但是我能感受到带着杀意的视线正从某处传来。还有其他厉害的同伙啊……</p><p>该向悠悠寻求协助吗？但是这么一来，功劳应该会被她全部抢走吧。</p><p>「你原本是打算出来耍帅吧，真是太可惜了。」</p><p>那副面罩底下肯定堆满了笑容。光是听到那道令人不爽的声音，我就仿佛能看见他愉悦的表情。</p><p>好啦，该怎么办才好呢？这时候我应该要展现出聪明才智，好让自己的股价继续提升吧？</p><p>「哼。如果你们立刻夹着尾巴逃走，那我就放过你们。」</p><p>「哈，你是搞不清楚清楚现在的状况吗？你靠着偷袭打倒的那两个人也差不多……喂，快给我起来！」</p><p>「唔，该死的家伙……」</p><p>连倒地的两人也复活了。六对一已经不是棘不棘手的问题，而是根本不可能有胜算。</p><p>虽然我用视线向正在巷子转角偷看的悠悠发出求救信号，她却悠哉地挥手帮我加油。</p><p>这家伙完全不懂我意思啊！难道她就是因为不识相才交不到朋友吗？</p><p>啊啊可恶！既然老大和臭小鬼都无法依靠，那我也只能自力更生了。</p><p>「够了。就算只有你也好，快逃吧！我早就想说说看这个台词了。嗯，感觉真不错！」</p><p>达克妮丝，在你这么高兴的时候泼冷水真是抱歉，但目前看起来是逃不掉了。这么一来，我该做的就只有一件事！</p><p>「你们以为老子是谁啊！老子可是打倒了魔王军的干部，还想出方法破坏掉那个机动要塞毁灭者的人物……和真啊！」</p><p>靠虚张声势蒙混过去！抱歉了，和真。现在就让我借用一下你的名字吧。</p><p>「头目，我有听说过这名字。说是打倒了魔王军干部，无头骑士贝尔迪亚的冒险者。」</p><p>四周立刻泛起一阵骚动。这群人果然不是这座城镇的居民。看到我这个在小混混当中也算有头有脸的人物却没有任何反应，就表示他们其实是外来者。</p><p>那么，现在只要靠和真的英勇事迹狐假虎威——</p><p>「等一下，刚才那边那位拉拉蒂娜小姐不是叫你达斯特吗？」</p><p>「……那是你的错觉吧。」</p><p>「不，我确实用这对耳朵听到了。」</p><p>糟糕啦啊啊！这么说来，达克妮丝的确叫了我的名字。可恶，这下搞砸了！</p><p>「呃，那也是骗你的——」</p><p>「你以为这招会管用吗？够了，快点把他解决掉！」</p><p>这下实在不妙了。难道真的没有退路或是落跑的方法吗！</p><p>「就是这边！警察先生，就是这边！坏人就在这里！」</p><p>「什么，有坏人吗！」</p><p>某位女性以及警官的声音响彻巷弄，这群人也立刻有所反应全都转过头去。</p><p>天助我也！那是悠悠的声音吧，比起用魔法助阵，那家伙选择了这种方法来衬托我的活跃吗！她明明就很上道啊！</p><p>悠悠从暗巷里冲了出来，在她后面还跟着三名并排成一列的警察。</p><p>「啧，撤退了！立刻逃跑！」</p><p>那群背对着我逃进暗巷里的蒙面人就交给警察去处理，我没有必要冒着危险追上去。</p><p>那道危险的视线也已经消失，看来就算松懈下来也无妨了。</p><p>「呼哈……实在好累啊，果然不该做这种不习惯的事情。」</p><p>「达斯特，其实再放置我一段时间也无妨，不过非常感谢你来救我。虽然我对你的印象就只有会跟和真一起干蠢事，但你意外的也是有优点呢。」</p><p>「『意外』是多余的形容啦，不过你就别客气了。」</p><p>这家伙明明是贵族却愿意低头道谢吗？真希望其他的贵族能好好向她学习。</p><p>「达斯特先生，你没事吧？」</p><p>悠悠尽全力往我这边跑了过来。虽然她拖到最后一刻才出手帮忙，但我还是道个谢吧。</p><p>「刚刚真是多亏你找了警察过来才能得救。」</p><p>「啊，那其实是骗人的，我没有找警察过来喔。」</p><p>「啥？那里不是站着三个警察吗？」</p><p>穿着制服排成一列在那边整队的三个人，不管怎么看都是警察啊。</p><p>「啊，那个是巴尼尔先生。」</p><p>「是由吾化身而成的警察是也。」</p><p>中间那名警官的声音确实是巴尼尔老大，但剩下的那两个呢？</p><p>那两个站在老大旁边，容貌还长得一模一样的人到底是谁？</p><p>「然后，这是吾脱皮后留下来的空壳。因为用细棍将手脚连接起来，所以能够做出跟吾相同的动作。」</p><p>伪装成警官站在中间的老大一举起手，他身旁的两个空壳也跟着举起手……那东西意外地灵巧呢。</p><p>「真是帮大忙了啊，老大。」</p><p>「要是让汝这种擅长引发负面情感的人死去，吾也会很困扰。」</p><p>「嘿嘿，被夸奖成这样我会害羞啦。」</p><p>「这真的……是在夸奖吗……」</p><p>我无视歪着头感到疑惑的悠悠，朝那群人逃跑的方向做了确认。</p><p>感觉不到任何人将从巷弄深处现身的气息，那道不舒服的视线也消失了。</p><p>总而言之这次的事件算是告一段落了。唉，虽然白费了许多功夫，不过这也没办法，接下来应该可以开口要求救人的谢礼吧？</p><p>「喂，达克妮丝，关于我搭救你的谢礼——」</p><p>「请问你愿意跟达斯特先生交往吗？」</p><p>出现在我眼前的是大吃一惊的达克妮丝。</p><p>我大概也是露出同样的表情吧……这个臭小鬼到底在说什么啊？</p><p>「怎、怎么回事？悠悠？还有巴尼尔也在？」</p><p>看见解除变身的巴尼尔老大，达克妮丝瞪大了眼睛。</p><p>「其实，达斯特先生从以前就喜欢达克妮丝小姐，他今天也一直在寻找告白的时机。结果却碰巧撞见刚刚的状况……」</p><p>喂、喂、喂喂，喂喂喂喂喂喂！这家伙依然误以为我想要搭讪达克妮丝吗！等等，等一下，老实说我已经不想再跟这女人有所牵扯了。</p><p>「咦？是这样吗……原来你是那样看待我的啊。」</p><p>不要害羞地扭动身体！也不要在那边偷瞄我！</p><p>臭小鬼也不要摆出「我帮上忙喽！」的态度，一脸得意地竖起大拇指！</p><p>「我、我很高兴你有这份心意。但我在意的……不、不对！我很担心和真他们。如果我不在，真不知道他们会做出什么蠢事。所以，现在不是谈恋爱的时候。」</p><p>为什么我明明没有告白却被甩了啊……</p><p>「还会有下一次相遇喔！你要加油！」</p><p>喂，住手。别鼓励我啊。这样不就像是我真的被拒绝了吗！</p><p>达克妮丝也不要一脸歉意地看着我啊！别这样！</p><p>「该怎么说呢。先不说我，如果你真的想受女性欢迎，那最好多注意平常的言行喔。」</p><p>为什么我要被变态用居高临下的态度给建议啊？</p><p>「就是说啊。另外就是在修养跟金钱观方面最好不要那么邋遢。」</p><p>连擅自暴冲的悠悠也得意忘形起来。</p><p>「呼哈哈哈哈哈！真没想到形成如此滑稽的展开！」</p><p>「老大，你也高兴过头了！」</p><p>啊——！越来越令人火大了！</p>`,417),e(f,{src:`/images/E1/14.avif`,alt:`插图`,width:`850`,height:`1206`}),s[12]||=a(`<p>「别开玩笑了！谁会喜欢达克妮丝你这种几乎快出现腹肌线的肌肉变态啊！悠悠也一样，明明就没有能聊恋爱话题的朋友，少在那边讲得好像自己有多懂男女关系！根本全都是从书上现学现卖吧！」</p><p>将不满彻底爆发出来后，心情总算是舒畅多了。啊～～果然不该一直累积压力呢。看来这两个家伙也被我的怒火所压制，畏畏缩缩地闭上了嘴巴——</p><p>「喂，你再说一次看看。究竟是谁有腹肌线啊……」</p><p>「恋爱……朋友……」</p><p>「等、等等，是我说的太超过了。冷静，请冷静一下，把你捡起来的短刀放下好吗？还有，在城镇中使用魔法会引发各种问题喔。好啦，这只是所谓的措辞问题吧？我们应该要平和地对话——」</p><p>「我要宰了你！」</p><p>「我、我、我还是有可以聊恋爱话题的朋友！」</p><p>「这真是美味的负面情感！」</p><p>就这样，我浪费了整整半天时间，才总算从眼角泛泪挥舞着魔杖和武器的两人手中逃脱。</p><h2 id="第五章-那个梦魔与敌对势力" tabindex="-1"><a class="header-anchor" href="#第五章-那个梦魔与敌对势力"><span>第五章 那个梦魔与敌对势力</span></a></h2><h3 id="_1-4" tabindex="-1"><a class="header-anchor" href="#_1-4"><span>1</span></a></h3><p>「听好了，不能只顾着提升露出度，重点在于害羞感。」</p><p>「害羞吗？但是男人不都很喜欢裸体吗？」</p><p>「我们的确不讨厌裸体。不过到脱光为止的过程也很重要。而且如果有若隐若现的部分将会提升期待的程度，这可是能让兴奋感倍增的情色香辛料哟。就算要脱衣服，也千万不要忘记装模作样。还有如果不是自己动手而是让对方来脱，那更是加分。」</p><p>「受教了！」</p><p>萝莉梦魔专心倾听我的建议同时记着笔记。</p><p>认真向学是件好事。虽然她在情色表现上还有不成熟的部分，但是在我的指导下，她肯定可以成为超一流的梦魔。</p><p>「你们真是够了……别在我的店门口讨论那种猥亵的事情！」</p><p>气得满脸通红的杂货店大叔向我们发出怒吼。这个大叔还是老样子，度量实在有够狭小。</p><p>「我也没办法啊，谁教那间店现在不能进去。」</p><p>「不好意思，给你添麻烦了。」</p><p>其实根本不需要跟大叔道歉，萝莉梦魔总是在一些奇妙的地方特别有礼貌。</p><p>「你这次又骗了别的女孩吗！这位小姐，不可以和这个人渣来往喔，这家伙会连你的骨髓都吸干，不停从你身上榨取好处。」</p><p>「喂喂，虽然你每次都把我当成坏人，但是我跟这家伙可是互助互惠的关系啊！啊～～我受伤了～～我纤细的心灵几乎要破碎了！」</p><p>「哼，等破碎之后就会出现长着钢铁刀刃的心脏吧？」</p><p>「两位的感情还真好。」</p><p>「「好个屁！」」</p><p>我跟大叔异口同声地说道。</p><p>我很清楚，这家伙其实每天都打着呵欠在顾店，有人能陪他打发时间，他内心其实非常高兴。明明是大叔竟然是个傲娇。</p><p>「真是的，别说这种莫名其妙的话。我要回去店里了，你们也赶快离开。」</p><p>大叔说完就转身离去。碍事者消失后，耳根子总算是清静了。</p><p>「大叔走的正是时候。我刚刚就想问你，为什么那间店这几天都没有营业啊？」</p><p>梦魔店这几天不知为何一直都没有营业，包括我在内的男性冒险者们全都欲求不满到快爆炸了。</p><p>「关于这件事……到了这个节骨眼，就算是达斯特先生也无所谓了，你能不能帮我们想想办法呢？我们一定会好好道谢。」</p><p>「哦？麻烦事就交给我来解决吧。如果是跟小混混有关的问题，那我的面子还算管用，一定可以把问题处理好。」</p><p>「跟小混混无关。我们面对的是更麻烦的组织……」</p><p>萝莉梦魔只说到这里就闭上嘴巴，双眼紧紧盯着我。</p><p>她认真的模样仿佛是在表示一旦继续听下去我就无法回头了。</p><p>不要小看我。无论面对什么对手，老子达斯特都无所畏惧。</p><p>「嗯，赶快告诉我吧。不管对手是谁都放心交给老子吧！」</p><p>「既然你都这样讲了，那我就继续说下去喽。那个团体是由女性所构成的恐怖组织……『女性婚期保护协会』！」</p><p>「……啥？」</p><p>由于听见意料之外的名称，使我发出很蠢的回应。</p><p>女性……婚期保护协会？婚期就是指那个吧，那个叫作适婚年龄的东西。</p><p>「女性婚期保护协会？这个莫名其妙的组织和梦魔店有什么关系？」</p><p>「关系可大了。你知道阿克塞尔城镇的冒险者单身率很高吗？不仅如此，就连情侣都很少喔。」</p><p>「是喔……这么说来，我认识的冒险者当中，的确几乎没有已婚或是有恋人的家伙。」</p><p>我的队友泰勒、奇斯以及琳恩都单身。也几乎没有听认识的朋友聊过这类话题。</p><p>我原本以为冒险者就是这种存在，不过连有一定年纪的大叔冒险者似乎也都单身……</p><p>「总之，我现在知道这里有很多单身汉了，但是这跟梦魔店有什么关系？」</p><p>「当然有关系。阿克塞尔是许多新手冒险者滞留的城镇，而且男性冒险者大部分都有来光临我们的店。毕竟我们店里的客人只需要支付相符的金额跟男性的精气，就能在梦中得到梦寐以求的性生活，性欲也能获得宣泄。」</p><p>「嗯，是啊。每次都受你们照顾了。」</p><p>「谢谢惠顾。总之男性冒险者大半的性欲都因此得到满足，那个……一旦男性的性欲降低，对女性的需求自然也会减少对吧？最后的结果，就是积极追求伴侣的人数锐减。虽然男性可以透过我们的店宣泄欲望，但是女性就没有办法这么做了。即使已经过了适婚年龄依然小姑独处，只有不满的情绪持续累积……集合这样的女性们秘密成立的组织，就是那个女性婚期保护协会。」</p><p>「竟然还有这种组织，就连我也是第一次听到。」</p><p>「就跟我们的店只有男性冒险者知道一样，那似乎也是只有接近婚期，或是已经过了婚期的单身女性才知道的秘密组织。」</p><p>就和我们隐瞒了梦魔店的存在一样，女性之间也有男性不知道的秘密啊？阿克塞尔这座城镇果然不容小觑。</p><p>「那个女性婚期保护协会似乎掌握了某些情报，正在怀疑我们的店，最近经常有乔装过的关系人士在我们的店附近徘徊。」</p><p>「还真是被麻烦的团体给盯上了。」</p><p>「是啊。由于在店里只有请大家填写调查表，表面上只是没有任何可疑之处的咖啡厅，所以才能顺利蒙混至今……但是明天警察好像会来店内搜查，所以我们正在讨论对策。」</p><p>「喂喂，这真的是不太妙呢。是那个组织去告密的吗？」</p><p>我这么一问，萝莉梦魔就愁眉苦脸起来。</p><p>这到底是肯定还是否定啊？</p><p>「我们一开始也是这么认为，所以打算去拉拢高层人员。」</p><p>「如果是受到梦魔诱惑，即使对方是警察也会立刻被攻陷吧。这真是不错的主意。」</p><p>如果梦魔说只要这次放她们一马今后都可以打折，那对方的态度肯定会立刻改变吧。是我的话肯定会果断接受。</p><p>「话虽如此……但是负责指挥这次行动的是一位女性检察官，而且她似乎还是女性婚期保护协会的会长。」</p><p>「真的假的……？」</p><p>「是真的喔。虽然对梦魔而言，即使对方是女性也可以用魅惑来进行控制。但是对方跟警察有关连，而且又是女性婚期保护协会的会长，如果态度突然转变会非常可疑吧？加上该组织的会员中也有祭司，魅惑很可能会被解除。」</p><p>无论是艾莉丝教或阿克西斯教都非常讨厌恶魔。万一梦魔身分曝光，教团肯定会倾全力讨伐她们。</p><p>「那个会长究竟是谁啊？」</p><p>「会长的名字……好像叫瑟娜。」</p><p>嗯？……我知道那个家伙。是那个有着一头黑色长发，唯一的优点只有胸部很大，性格非常难相处的检察官。</p><p>那家伙在审判和真的法庭上叫我小混混，是个非常讨厌的女人。</p><p>「这么一来你们就无法笼络高层了。不过让他们去搜查也不会怎样吧？店里不是没有任何可疑之处吗？」</p><p>「是没错。但瑟娜检察官很可能……会把那个测谎用魔道具带来。一旦用了那个……」</p><p>「是那个该死的魔道具吗！因为完全不相信我的说词，警察在审问我时一定会使用的那个吗！每次都叮叮叮叮吵得要死……那个真的很不妙啊。」</p><p>「嗯……所以我想问问达斯特先生是不是有什么好办法。」</p><p>即使调查店内应该也找不到什么可疑的证据。虽然我觉得该把调查表处理掉，然而服务毕竟是在梦中进行，根本不可能找得到物证。</p><p>所以最大的问题……就是那个魔道具了。那群笨警察打从心底相信该道具的判断。要是有什么能蒙混过去的手段就好了。</p><p>「如果一切顺利，我应该能收到谢礼之类的吧？」</p><p>虽然受到她们诸多照顾，但我也不打算当慈善家。</p><p>「就知道你会这么说。关于这点，不然让你免费光顾本店一星期，这样如何？」</p><p>「很好，交涉成立！」</p><h3 id="_2-4" tabindex="-1"><a class="header-anchor" href="#_2-4"><span>2</span></a></h3><p>经过缜密的部署后，我在当天以客人的身分上门光顾。</p><p>突袭搜查的情报是由警察内部人士外泄给店家，对方是后来当上警察的前冒险者，至今仍是梦魔店的常客。警察那边应该作梦也想不到这间店会在事前得知搜查的情报吧。</p><p>只有今天，这间店伪装成听取男性冒险者的烦恼与牢骚，帮他们出主意的占卜屋。虽然表面上只是咖啡厅，但有暗中帮冒险者们进行占卜——以上就是我们这次的设定。</p><p>说谎的诀窍就是要在谎言中混入部分真实，这么一来谎言将更难被看穿。本作战是将操作梦的部分替换成占卜，好让讲法更具有真实性。</p><p>梦魔们也都穿上普通服务生的制服，像是一般店员一样服务客人。</p><p>因为只有我一个客人肯定非常奇怪，所以萝莉梦魔事前从常客中挑出一个人，让对方以客人的身分坐在稍远的座位上……这是无所谓啦，不过那家伙是谁啊？</p><p>如果只是穿着华丽也就算了，令人在意的是对方头上——戴着头盔。由于那是将整张脸都遮起来的头盔，让他跟现场非常格格不入。</p><p>「喂，那家伙是怎样？」</p><p>我向打扮成女服务生坐在我面前的萝莉梦魔小声问道。</p><p>「那是其中一位常客，也是进行达斯特先生的作战不可或缺的人物。由于那一位是贵族，所以长相不能曝光。」</p><p>「就算是要把脸藏起来，这个做法也未免太夸张了吧。而且那顶头盔……跟我先前卖掉的好像喔。」</p><p>「那是很常见的设计吧？对我来说就只是一顶经常在武器防具店看到的头盔喔。」</p><p>我以前戴的那顶头盔的确不是什么独一无二的设计，所以这件事就先不管了。不过只是要把脸遮起来为什么要戴头盔啊？这样反而会更加显眼耶。</p><p>「你刚刚说那家伙是执行作战不可或缺的人物，难道头盔男有什么能搞定那个的东西？」</p><p>「是的。那个人带着某种魔道具，能够干扰甚至反转测谎用魔道具的判定。那好像是非常稀有的高级魔道具，在贵族之中很受欢迎。」</p><p>「哦——还真是肮脏，不愧是贵族大人，他们是把那当成不让自己恶行曝光的对策吗？」</p><p>这是很有可能的事。对贵族来说，那个测谎用魔道具是非常麻烦的存在，当然会去准备应对的方法。</p><p>「请不要说这种话。那一位可是很爽快地就答应协助我们的作战喔。」</p><p>「这样啊。虽然也有很多令人不爽的贵族，但是愿意帮忙自然就另当别论了。」</p><p>「毕竟对方愿意协助我们，就算有什么内情也完全不用在意。没错，不可以在意喔。」</p><p>萝莉梦魔竟然特意强调不要在意，这根本就是在说这家伙别有隐情啊。</p><p>「……唔，这是怎样？」</p><p>感觉到视线的我一转过头去，就看到头盔男似乎很在意地盯着我看……由于看不到表情，让我觉得有些毛骨悚然。</p><p>不过……虽然无法直接看见，但是那道视线让我有种背嵴发凉的奇妙感觉。那家伙是在揣测我有没有协助的价值吗？</p><p>「大家准备好了吗？警察来喽！」</p><p>听到冲进室内的梦魔如此宣告，所有人立刻回到自己的岗位。</p><p>今天的方针已经传达给全体人员，接下来就是看我们怎么瞒过那些警察了。</p><h3 id="_3-3" tabindex="-1"><a class="header-anchor" href="#_3-3"><span>3</span></a></h3><p>「统统不准动！我们是警察！」</p><p>眼神锐利的女检察官瑟娜用力打开门闯了进来。</p><p>跟随在后接连闯进来的警察也全都是女性……感觉这些女警有些奇怪耶。该说是鬼气逼人吗？她们每个人的眼里都充满了血丝。</p><p>「……警察当中好像也有几位是女性婚期保护协会的成员。」</p><p>萝莉梦魔在我耳旁低声说明，这样我就能理解了。是一群跟瑟娜一样即将走投无路的人啊。梦魔们全都装出困惑的模样，老老实实听从警察的命令……她们的演技真棒，这群梦魔果然都有成为演员的天赋。</p><p>在那群警察当中，有一位胸部很大，帽沿压得很低的女性……明明看不到她的脸，却不知为何令我很在意，她比其他人都要认真地搜查着店内，总觉得我好像在哪见过这个人……？</p><p>「还没找到证据吗？」</p><p>喔喔，瑟娜开始焦急了。她可能认为这里是违法的风月场所吧。真是可惜。虽然你没有弄错，但是这里没有任何能当成证据的东西。</p><p>「奇怪了！冒险者们肯定都有都在光顾这间店啊？」</p><p>「露……咳咳，难道说那个情报有误吗？」</p><p>「不，这里肯定是男性冒险者都极力保密的那间店，绝对没错，而且他们还经常一起在公会里讨论。由于每个人都严守秘密，无法问出更多情报，所以我也不清楚详情。」</p><p>那位巨乳警察和瑟娜讨论了起来。</p><p>从对话内容来看，那名警察似乎很清楚公会的事情耶？没想到女性婚期保护协会的爪牙已经深入公会了啊。</p><p>好啦，差不多该去搭话看看对方的反应了。</p><p>「喂，我们可以回去了吗？」</p><p>「不行，因为你们是重要的证人……啊，是你！由于品行不良多次遭到逮捕的小混混冒险者达斯特！」</p><p>「咦？达斯特先生？」</p><p>检察官竟然说我是小混混……虽然瑟娜的发言令我很不爽，但重点是女警叫了我的名字，那道声音好像有在哪里听过……</p><p>「还真是感谢你详细的说明啊！」</p><p>「你为什么会在这里？」</p><p>哎呀，做出这个反应啦。那接下来就是重头戏了。</p><p>「啊，因为这里愿意听男性倾诉烦恼喔。无论抱怨什么她们都笑着倾听，加上以女性的立场所给出的意见可是相当有用呢。」</p><p>「你会有烦恼吗……」</p><p>「喂，你想表达什么？」</p><p>「不，没什么……比起这个，那真的是你的目的吗？根据审讯店员所得到的情报，这里虽然是咖啡厅，但同时也有在帮客人占卜，这是真的吗？」</p><p>不要一次问这么多问题啦，看来瑟娜相当焦急呢。</p><p>「是啊，没错。这里的大姊姊都很有包容力，让人可以轻易倾诉心情。因为周围净是些强势的女性，只有待在这里的时间才能让我的心灵平静下来。亲切待人的女性实在太棒了。」</p><p>「啊呜。」</p><p>「咕啊。」</p><p>瑟娜以及她旁边的女警察同时起了反应。</p><p>「话说回来，你们究竟把这里当成是什么店才跑来搜查啊？」</p><p>「关于这点，因为有人举报这里表面上是咖啡厅，私底下却在经营色情行业。而且听说还是男性冒险者经常光顾的秘密店家。」</p><p>「会把冒险者当工作的人毕竟都是莽汉，我们怎么样也不想把自己找女性抱怨，甚至把相信占卜这种事公开给女人知道吧？当然会严加保密啊。」</p><p>「确、确实如此。这座城镇的冒险者之所以对女性没有欲望，全是在这间店倾诉烦恼并得到治愈的关系吗……原来是有着这种理由吗……」</p><p>瑟娜双手抱胸碎念了起来。如果继续蒙混下去应该能顺利赶走她们。就算有准备对付那个魔道具的方法，但是她们愿意直接撤退当然再好不过。</p><p>「这里没有什么可疑之处吧？你们赶快回去吧。不然店家可能会告你们妨碍营业喔。」</p><p>「这么说也对，看来是我们弄错了。我们去向店长道歉后就回去——」</p><p>哦，成功了吗？这样应该就不需要使用那个手段了。</p><p>「瑟娜小姐，请等一下。不管怎么想达斯特先生都不可能把弱点暴露给女性知道，如果是抓住别人的弱点威胁对方也就算了，现在这样实在太过可疑了。」</p><p>这家伙竟然说的好像自己很了解我一样。虽然不清楚她到底是谁，但是竟然给我在那边口无遮拦，就这么想让我揉爆那对巨大的胸部吗？</p><p>「的确，从这个人平常的言行判断，他是那种比起烦恼会先行动的类型。而且这种荒度人生的男人根本不可能会有什么烦恼……吧。」</p><p>「喂喂，你还真敢说啊。哼，就是因为你们那么多疑，所以才会不受男人欢迎吧？」</p><p>就在我对这群看不起我的家伙冷哼了一声并开口挑衅后……四周突然传来类似空间碎裂的声响。</p><p>怎、怎么了……为什么所有的女警全都转头，还用几乎能射杀我的眼神看过来？难道说……这些人全都是女性婚期保护协会的会员吗？</p><p>这下糟糕了，强烈的杀气令我的背后冒出大量冷汗，衣服黏在身上的感觉非常不舒服。这个状况太不妙。如果不快点讲出关键的一句话彻底改变现场气氛，那我的小命就不保了。</p><p>「啊——但是像瑟娜这种脸蛋漂亮身材又好的女性一定很受欢迎吧。抱歉，抱歉。我刚才竟然说出如此失礼的话，我道歉，请原谅我。」</p><p>这时候绝对不能拐弯抹角，直来直往的讲法才是最好的选择，杂货店贩售的那本《讨好女性的一百种方法》上面就是这样写。</p><p>「没、没这回事啦，别说这种明显的客套话了。」</p><p>虽然嘴上这么说，但是她脸上的笑意根本藏不住。</p><p>瑟娜的心情多少有恢复一些，但是剩下的那群人眼神反而变得更加锐利。看来必须给一个在场的所有人都能接受的理由。</p><p>「不过阿克塞尔这座城镇的美女还真多。光是这里的警官也各个都是美女，如果是由各位负责审讯，我还真希望每天都能被逮捕呢。」</p><p>虽然有几个人被我的说词打动，但是大部分的女警依然维持狐疑的眼神。一般来说的确没有那么简单就能搞定，这都在我的预料之中。</p><p>「对了，你们可不要说出去喔……各位不觉得这座城镇未免太多单身的男性冒险者了吗？明明周遭就有那么多美女，却很少有男人积极去追求女性。」</p><p>「我们从很久以前就这么觉得了。」</p><p>看来她们对于这个话题非常有兴趣，不只是瑟娜，就连其他女警也往我这边靠了过来。她们成半圆形将我包围，目光也集中到我身上。</p><p>虽然和原本想定的计划不同，但我打算就这样开始执行作战。</p><p>「这件事其实是秘密喔……这座城镇的男性冒险者，其实大部分都是基佬。」</p><p>「基佬……那是所谓的男同性恋吗？」</p><p>「嗯，是啊，这是只在男性冒险者之间流传的秘密——阿克塞尔其实是基佬的聚集地。所以，聚集在这里的尽是那种男人，大多都是对女性毫无兴趣的家伙。」</p><p>「唔……！」</p><p>我听见倒吸一口气的声音了。由于自尊上她们可以接受自己是因为这种理由没有人追，但是常识也在告诉她们这根本是不可能的事，所以两种想法正在互相冲突。</p><p>这时候就该动手补刀。</p><p>「请各位仔细想想看。这座城镇充满了像你们这样的美女喔，就常识来判断，男性们应该会更加积极地四处搭讪吧。」</p><p>「你说的是真的吗？这座城镇的男人都是基佬……也就是大多都是同性恋吗？所以男性们总是黏在一起卿卿我我吗！」</p><p>「啊啊，瑟娜小姐请你冷静一点。你的腐女兴趣都写在脸上了！你先前也因为兴趣曝光导致相亲失败过吧！」</p><p>女警们闯入我和瑟娜之间，拼命阻止瑟娜朝我逼近。</p><p>看来瑟娜依然相当怀疑。是因为她太过动摇吗，感觉她呼吸急促而且满脸通红耶。</p><p>那个腐女兴趣究竟是指什么啊……？反正应该是无关紧要的事，就不要太在意了。</p><p>好了，接着就来让她们见识我真正的本领吧。</p><p>「没错，就是这么一回事。请各位仔细想想，你们也认识的和真明明就被美女包围，为什么他迟迟没有对任何人出手？各位不觉得奇怪吗？」</p><p>「这么说起来的确是这样。佐藤先生明明在背地里被称为人渣真、垃圾真，还跟三名女性住在同一个屋檐下，却从来没有传出那方面的流言。难道说佐藤先生也是那一边的人……他应该是受吧？或者其实是攻？」</p><p>「瑟娜小姐，你的本性都曝光了，请克制一点。」</p><p>我虽然没有听到瑟娜后半的自言自语以及那位巨乳女警对她说的话，但是她们两人对望着陷入沉思。</p><p>瑟娜向那位巨乳女警，以点头确认自己的想法是否正确，紧接着对方也用力点头回应。</p><p>「那个，和真先生和他的同伴们似乎并非那种关系。根据我最近的观察，和真先生更像是在担任监护人。」</p><p>其实我非——常理解和真为什么不出手。那三个家伙虽然外表很美，但是内在实在太「那个」了。除了格外好事的家伙、虐待狂、有钱人或是圣人般的存在之外，没有人可以顺利驾驭那三个人。不然……就只有和真了。</p><p>虽然也有可能只是和真太没用，所以一直不敢出手而已。</p><p>不清楚那三名女孩本性的瑟娜似乎接受了这个说词。这时候就算有些勉强，也要一口咬定这个说法。</p><p>「我已经说过很多次了，光是没有被你们这些美女吸引，就可以证明这里的冒险者们有问题了。」</p><p>「是、是吗？」</p><p>瑟娜害羞地用手指卷着头发。虽然还不到萝莉梦魔的程度，但这家伙也是个好骗的女人啊。瑟娜没有人追的理由非常明显，即使那对胸部很吸引人，但她毕竟总是作为检察官在取缔血气方刚的冒险者，加上个性又如此好强，自然没有人愿意接近。</p><p>「没错！我看到你这样的美女就忍不住精虫冲脑，那边也几乎都要炸膛了。不然我立刻脱下来给你看吧？」</p><p>「住、住手！不然我以公然猥亵罪逮捕你喔！对、对了，如果这是实话，我们就请这间店的客人帮忙，在测谎用魔道具面前提出证言吧。」</p><p>很好，终于来了。我等这句话很久了。</p><p>其他的警察也点头同意瑟娜的判断。</p><p>「我们就调查几名常客，如果其中有同性恋，那就相信这个说法……」</p><p>「那个，检察官小姐，可以打扰一下吗？」</p><p>这时萝莉梦魔突然从旁插话。</p><p>虽然因为她整个人探出身子使得屁股出现我面前，不过这家伙没胸部也没屁股，就连长相也跟小孩子一样，根本无法燃起我的欲望。</p><p>「你是这里的服务生吗？」</p><p>「是的，没错。请问这样要不要请那一位协助调查呢？他也是本店的常客，而且……」</p><p>萝莉梦魔向我的后方撇了几眼小声说道。</p><p>在她视线前方的正是那个头盔男。到目前为止都完全按照作战在进行，那么接下来就看瑟娜是否会上钩了。</p><p>「嗯，是那个人吗？如果你说的是实话，那么那个人确实足以作为证人。好吧，魔道具放在哪里？」</p><p>「收在店门前的马车当中。」</p><p>「请各位稍微等一下，我这就去拿魔道具。」</p><p>瑟娜没等我回答就直接冲了出去。有几个人跟在她身后，剩下的女警们则是为了不让我们逃走留下来警戒，还全都退到店门口监视着这里。</p><p>「总算是成功修正好轨道。再来就看头盔男能不能派上用场了。」</p><p>「肯定没问题啦，麻烦您过来这边。」</p><p>萝莉梦魔一招手，头盔男就摇摇晃晃地走了过来。这家伙的呼吸相当急促，如果真的喘不过气，为什么不把头盔拿下来呢？</p><p>这家伙一坐到我的旁边就向我伸出手，这是在要求跟我握手吗？</p><p>「虽然和男人握手只会让我觉得恶心，但这次就算了，感谢你的协助。」</p><p>我握住他伸出的手之后，他立刻用力回握。</p><p>因为就在旁边，让我更加在意从头盔中传出的呼吸声，感觉变得比刚才还要急促了。</p><p>「喂，我虽然能明白你不想暴露身分，但要是很不舒服，还是把头盔拿下来吧？」</p><p>但头盔男只是勐烈地左右摇着头，坚持不肯拿下来。</p><p>这家伙虽然是个怪人，但现在毕竟是重要的协助者，必须要好好相处才行。如果证人是贵族大人，那么欺善怕恶的检察官也比较能接受结果吧。</p><p>「虽然跟你不熟，但总之拜托了。」</p><p>头盔男纵向点着头。看来这家伙意外的人不错呢。</p><p>「喂，你也差不多可以放手了吧，喂。」</p><p>话说回来，这家伙为什么还抓着我的手不放啊？</p><p>因为手汗整个黏黏的感觉好恶心，而且他的手指搓来搓去弄得我很痒耶。</p><p>「喂，快点给我放手！」</p><h3 id="_4-3" tabindex="-1"><a class="header-anchor" href="#_4-3"><span>4</span></a></h3><p>就在我努力把这家伙的手扯开时，瑟娜回来了。</p><p>「那就让我调查一下吧。」</p><p>她勐力地把魔道具放到桌上。由于讨厌的经验已经渗入我的骨髓，光是看着这个我的身体差点就摆出戒备态势。</p><p>「呃，这边这位先生……请问我该怎么称呼你？」</p><p>「就叫我头盔人吧。」</p><p>头盔中传来一道模煳的声音。虽然听起来像是年轻男子，但实在很难确定。</p><p>「那、那么，请达斯特先生和头盔先生一起作答。」</p><p>「了解。」</p><p>「我要先澄清啊，我喜欢的是女人。」</p><p>我在瑟娜来之前有先跟本人确认过，头盔男持有的那个魔道具是贵族为了隐瞒罪行，透过黑市所取得的禁断魔道具。</p><p>只有持有者本身的发言能够被反转。所以就算我站在旁边回答，那个测谎用魔道具也能够做出正常的判断。</p><p>还真是便利的魔道具啊。虽然还是有正经的家伙在，不过大部分的贵族都是人渣，就算这家伙拥有这种东西也不是什么稀奇的事。</p><p>「那么，我要提问了。请老实回答。你喜欢女性？」</p><p>「嗯。」</p><p>魔道具没有响，这也是理所当然的事，因为我没有说谎。</p><p>「那么，请头盔先生回答同样的质问，你喜欢女性？」</p><p>「不。」</p><p>没有反应。也就是说，魔道具判定他不喜欢女性了。</p><p>那家伙持有的魔道具是真货啊。这么一来无论头盔男再怎么撒谎也不会被发现了。</p><p>「以防万一，达斯特先生，接下来的问题请你回答『是』。你喜欢男性？」</p><p>「是。」</p><p>铃铛叮了一声。魔道具判定我不喜欢男性。</p><p>「原来如此。那么，我重新向两位提问，请老实回答。你喜欢男性？」</p><p>「开什么玩笑啊。」</p><p>「是。」</p><p>对于我和头盔男的回答，魔道具……没有反应。</p><p>最令人在意的是头盔男每次回答时都会偷偷看向我。别担心，你的谎言并没有被揭穿。</p><p>「虽然我很难理解。没错，完全无法理解，但是你喜欢男性的什么地方呢？」</p><p>质问开始变得比较具体了。毕竟瑟娜很习惯在这种场面下审问犯人，所以开始向麻烦的地方进攻了。</p><p>不过质问中莫名充满了热情这点，让我多少有些在意。</p><p>这时候如果随口回答将会露出马脚，所以只能期待头盔男的演技了。</p><p>我悄悄朝头盔男瞄了一眼，就听见一道沉重的吸气声。</p><p>「我希望你不要误会，即使我喜欢的是男性也并非完全不挑对象。而且与其说我喜欢男性，不如说我喜欢的对象恰好是男性，碰巧对男性对象产生了性冲动罢了！……我的这份感情可能一生都无法传达给对方。但即使如此，也没有任何人可以阻止我喜欢对方的心情！看着他作为冒险者赌上性命满身大汗地工作，我就无法压抑内心的兴奋……我想尽情去嗅他那件沾满汗水的衣服！但是我实在没有那种勇气，只能在远处默默地望着他的身影，只能在夜晚为自己的懦弱泪洒枕头！有时候还会抱着为他买的红色内衣，期望他总有一天能为我穿上并沉沉睡去！由于听说阿克西斯教团承认同性恋，自从入教之后，我每天都在努力祈祷——」</p><p>「原来如此，原来如此。这里有着超越性别的纯爱啊。我在此对怀疑你说谎一事道歉。」</p><p>瑟娜直接接受了头盔男满腔热血的回应，并且真诚地向他道歉。</p><p>说实话，最令我难以接受的是瑟娜通情达理到让人恶心的地步。</p><p>不过连我都有一瞬间怀疑这家伙可能真的是同性恋，他的演技实在太好了，他可能是想当演员的少爷吧。</p><p>如果是贵族的三男，有不少人可以自由选择自己的生活方式，实际上也有后来成为冒险者的贵族。</p><p>在那之后，虽然瑟娜又问了几个是否真的喜欢男性的问题，但是头盔男的谎言始终没有被识破。</p><p>「看来是真的了。不过，这个魔道具过去曾经出现过几次奇妙的反应……所以太过依赖它也不太好。那么是否能让我们看看你真的喜欢男性的证据呢？这是必要的确认，绝对不是因为我自己想看。」</p><p>瑟娜感觉就像是在找借口。</p><p>「啥？你在说什么啊？不是已经证明我喜欢女性，他喜欢男性了吗？不然像这样勾肩搭背你就可以接受吗？」</p><p>我一将手搭上头盔男的肩膀，瑟娜就眯起眼睛看着我们。那是狐疑的眼神……她为什么要遗憾地咂舌啊？还有，头盔男的呼吸声好吵喔。</p><p>看来要装得更像一点。可恶，虽然不想被男人碰，不过现在是非常时刻，只能先妥协了。</p><p>「……抱歉，虽然有些恶心不过忍耐一下吧。我晚点会请你喝酒，你就假装是那样来触摸我的身体吧。」</p><p>为了不让瑟娜听见，我隔着头盔跟对方悄声说道。</p><p>经过刚才的演技后，只要再加上有模有样的行为，那无论是谁肯定都会相信吧。</p><p>虽然有些对不起头盔男，但这都是为了保住梦魔的店。</p><p>「我很乐意……」</p><p>嗯……？刚刚这家伙……是不是说了什么奇怪的话？一定是隔着头盔让声音太过模煳，所以我才听错了。</p><p>头盔男的手轻轻放上我的胸部，手指不停地在上面滑动。</p><p>啊啊啊啊啊，虽然全身毛骨悚然但是我要忍耐。头盔男发挥他逼真的演技，做出跟真的一样的行为。我必须要忍耐……</p><p>「喂，喂！那里，不可以！喂，你打算把手伸到哪里去啊！快住手啊啊啊啊啊！」</p><p>「呼……呼！摸一下又不会怎样，稍微碰一下而已，只要再一点点就好了！我只是想稍微摸摸头！」</p><p>「那个头是指哪里的啊！」</p><p>这家伙的力气还真大。虽然以演戏来说非常完美，但是那里真的不行！如果觉醒了奇怪的癖好该怎么办啊！</p><p>「喂，瑟娜！不要只是红着脸看戏啊！快点来阻止他！喂，等等，警察小姐，警察小姐啊啊啊啊啊！」</p><p>「我、我知道了。这怎么看都不可能是演技。接下来的行为就请在别的地方继续，我绝对不会去打扰。」</p><p>瑟娜等人总算将头盔男从我身边拉开。</p><p>「喔、喔喔，你这下能明白了吧？」</p><p>「……啧。」</p><p>头盔男啧了一声后，心不甘情不愿地放开了手……虽然听说他是贵族，不过感觉很可疑。不，难不成他其实真的是……不会吧……</p><p>身为贵族或王族如果不会演戏，会很难在这个世上混下去。头盔男肯定只是拥有这方面的才能……就先当成是这样吧。</p><p>「那么，最后一个问题……这座城镇的男性们大多都是同性恋，请问这是真的吗？」</p><p>竟然一脸平静地问出如此不得了的问题。不过也不是不能理解，毕竟只靠我跟这家伙作为证据未免太薄弱了。</p><p>不过，这时候我只要闭嘴交给头盔男去回答就行了。毕竟他持有的魔道具可以反转测谎用魔道具的判定，所以不会有问题。</p><p>「你也听到了吧，快点回答她吧。」</p><p>「…………」</p><p>喂，不要沉默不语，代替我好好回答啊。你不是已经证明那个魔道具的性能没问题了吗？</p><p>「啊～～应该是因为他戴着头盔所以没能听清楚吧？」</p><p>萝莉梦魔突然在这时探头介入我们的对话。</p><p>虽然她可能是打算帮忙，但是只要头盔男好好作答这件事就结束了，难道说他是真的没听见吗？</p><p>「你刚刚问是不是有很多基佬？这个问题真是可笑。即使是坐在我旁边的达斯特先生，在他的内心某处肯定也觉得男性很有魅力，认为跟男人变成那种关系应该也很不错！魔道具之所以没有反应，只是因为他还没有察觉到自己真正的想法罢了！没错，肯定是这样！」</p><p>喂，不要把我牵扯进去！</p><p>虽然我很想尽全力否定，但这时候必须忍耐。</p><p>测谎用魔道具对头盔男的热烈说词毫无反应，那个反测谎魔道具的性能真好。</p><p>虽然听在我耳里只觉得是因为他说出了真心话，所以魔道具才没有反应……不对，绝对不是这样吧？</p><p>「魔道具……没有反应呢。看来这座城镇的男性的确大多都是那一边的人啊……如果能早点发现，我就能享受各种基情场面了……」</p><p>「你刚刚是不是说了什么奇怪的话？」</p><p>「那是你的错觉。不过我真的没想到连达斯特先生都是呢，竟然男女通吃，你还真是有够恶劣耶。」</p><p>唔唔唔唔！虽然很想反驳！但是，现在一旦开口，至今为止的努力就会化为泡影了。忍耐，要忍耐啊，达斯特！事关一整个星期免费的梦魔店服务啊！</p><p>虽然我几乎就要开口飚骂，但还是悬崖勒马忍了下来。必须让自己冷静下来。我深呼吸一口气将到了嘴边的话语嚥了下去。</p><p>好了，冷静。这只是单纯的表演。为了配合头盔男的演技，我绝对不能生气。</p><p>但是……如果不回个两句，实在难消我心头之恨！</p><p>「那么，请把魔道具收起来吧。不好意思，给大家添麻烦了。」</p><p>确认瑟娜的部下将测谎用魔道具从店里拿出去后，我总算松了一口气。</p><p>这么一来就算说谎也不会被揭穿了。</p><p>「哈！不但随着假情报起舞，最后还对一般客人如此失礼，这就是你们这群大人物的做法吗？如果店面被搜查的情报传了出去，上门的客人肯定会大幅减少吧。」</p><p>「那个，实在非常抱歉。这完全是我们的失误。」</p><p>瑟娜成九十度鞠躬低头道歉，虽然她看起来是真心在反省……但是还不够。毕竟我受过各位警察诸多的照顾，必须趁这个时候好好回礼才行。</p><p>「如果道歉有用就不需要警察了吧？像你们这样只会让冤罪徒增，实在太可怕了。」</p><p>「真的非常抱歉！我们会向高层报告没有在这里发现任何可疑之处！还请您多加宽恕！」</p><p>「哈！只是出一张嘴，都给你说就好啦！这时候最重要的是诚意，没错，要向我们展现出你的诚意。必须弥补妨碍营业期间以及今后的利益损失……这样说你可以理解吧？」</p><p>这时候若是直接开口要钱，那就是最低级的威胁。必须将状况变成让对方自己去感受你究竟想要说什么，即使有个万一还可以一口咬定自己并没有这样说过。</p><p>这么一来就算之后挨告罪行也可以减免。</p><p>「哇啊……真不愧是达斯特先生。」</p><p>不要边说佩服边拉开我们之间的距离喔，萝莉梦魔。这时候应该要好好参考吧，你身为恶魔难道没有任何上进心吗？</p><p>「听说有好几位店员因为警察跑来搜查感到害怕，所以打算辞职了！」</p><p>「咦，你说谁——」</p><p>萝莉梦魔打算说出多余的话，于是我轻拍了一下她的屁股让她闭嘴。</p><p>别瞪我。不过这种程度的打闹就生气，这女人还真小气。亏我特意摸了你平坦的屁股耶。</p><p>「实在没想到事情会演变成这样……我究竟该怎么谢罪才好？」</p><p>瑟娜就是太一本正经了。虽然讲好听一点是忠于职守，但这根本就是不知变通。总觉得只要利用她责任感很强这点，就能让事情变得相当有趣。</p><p>虽然也可以威胁瑟娜赔钱，但是她如此耿直肯定不会同意，所以必须想别的方法……那种可以向这间店道歉……还能为难瑟娜的事……这么一来……有了，我想到一个可以让大家都皆大欢喜的方法了。</p><p>「对了，不然你就来店里帮个一次忙吧？」</p><p>「咦？我来帮忙吗？由于检察官不允许兼职，所以……」</p><p>「只要不说出去没人会知道吧？何况你只要不领工资，这样就只是在参加义工活动罢了，再加上这对你来说实在不是什么坏事吧？这里的店员们都因为强大的包容力深受男性爱慕。能在这种店工作就表示……」</p><p>我在这时稍做停顿，观察起对方的状况。</p><p>瑟娜和巨乳女警向前探出身子仔细聆听。</p><p>果然很在意呢，毕竟都加入那种组织了，怎么可能会没有兴趣呢？</p><p>我刻意缓缓开口，让两人焦急到极点。</p><p>「可以……学习到受男性欢迎的诀窍呢。」</p><p>「受欢迎……」</p><p>喔喔，这个染上了欲望而闪闪发亮的眼神真棒。</p><p>看来事情会变得比想像中还要有趣呢。</p><h3 id="_5-3" tabindex="-1"><a class="header-anchor" href="#_5-3"><span>5</span></a></h3><p>梦魔们要为了明天的事情开会，闲闲没事的我就跑到大街上乱晃。</p><p>想要突破这个没钱可以吃饭的现况，就只有去求伙伴请客了。</p><p>但因为早上的事情，只是开口拜托他们根本没用，我的挚友和真今天也没见到人影。</p><p>「肚子好饿。该去杂货店大叔那边寄生好呢，还是去揍小混混一顿收刮他们的钱好呢……哦，好香啊。」</p><p>正当我不知道之后要干嘛时，附近面包店传来刺激食欲的香气让我停下了脚步。</p><p>刚出炉的面包实在是香到不行，再加上我又是空腹，这样实在是难以忍受。</p><p>我顺着香气摇摇晃晃地走到面包店前方，整个人趴在店面的大玻璃窗上。</p><p>看起来就很好吃的面包摆放在架子上，感觉就像是在等待时机进入我的胃袋。</p><p>如果去下跪拜托应该能免费拿到吐司边吧？不过比起吐司边，我还是想吃刚出炉的面包。</p><p>「好想咬一口那个长棍面包喔。虽然看起来就很好吃，但问题是没钱，所以说这是神明指示要我去吃霸王餐！」</p><p>「你小心会被神明揍喔。还想说你是在做什么，看来是又打算去接受警察的照顾吗？」</p><p>顺着从背后传来的声音转过头去，就看到琳恩双手扠腰站在那里。</p><p>她不是躲在旅馆不肯出门吗？</p><p>「你在这里做什么？」</p><p>「我才想问呢。你最好在还没有被以妨碍营业提起告诉前，快点离开那里。」</p><p>店内的客人及店员正隔着玻璃窗用怀疑的眼神看着我。</p><p>的确，为了自身安全还是快点离开比较好。</p><p>「难道……你是在打吐司边的主意吗！那些全都是我的喔！」</p><p>「才不是呢。唉……真拿你没办法。你是想吃长棍面包吗？如果你真的穷成这样，要不要我借你买面包的钱？」</p><p>「什么？你有什么企图！」</p><p>「平常天天在那边喊着要别人借你钱，等别人主动开口你又那么多疑。我是好意——」</p><p>「啊，达斯特先生！」</p><p>这时萝莉梦魔大声叫着我的名字跑过来。</p><p>明明才刚刚开完会，究竟是有什么事啊？</p><p>「关于刚才那件事的后续……啊，打扰到你们了吗？」</p><p>交互看了看我跟琳恩后，萝莉梦魔轻轻歪过头。</p><p>琳恩皱起眉头看向萝莉梦魔……应该说瞪着她？</p><p>「达斯特，这孩子是谁？」</p><p>「啊～～该怎么说呢。」</p><p>毕竟不能说是梦魔啊，这时候最好是随口胡扯蒙混过去吧。</p><p>「不说也无所谓，反正你的事情根本无关紧要。」</p><p>琳恩为什么突然那么不高兴啊？难道是在怀疑萝莉梦魔吗？</p><p>「喂，等等。你不是说要借我钱买面包吗？」</p><p>「啊，我可以买面包给你喔，毕竟受了达斯特先生不少照顾。」</p><p>琳恩斜眼看了萝莉梦魔一眼后，就不发一语快步离去。</p><p>她到底是怎么了？我真是搞不懂这家伙耶。</p><p>隔天，休假的瑟娜来到了店里……如果只是这样就好了。</p><p>「这里就是和真说的店家吗！虽然因为忍不住回嘴说出我也去帮忙才变成这样……但是你不觉得这间店很可疑吗？」</p><p>——偏偏达克妮丝也跟着瑟娜一起上门。</p><p>我多少可以回想起这家伙跑来的理由。昨晚喝了和真请的酒之后，我趁着醉意说出了瑟娜的事情。</p><p>接着觉得有趣的和真，便兴奋地说出了「不然让达克妮丝也去那边工作吧」之类的话，最后就变成这样了。</p><p>「拉拉蒂娜大小姐，您还是回去比较好……」</p><p>「不准叫我拉拉蒂娜。叫我达克妮丝就行了。虽然是受了和真的挑衅才变成这样，但听说这里的店员很受男性欢迎。在这边帮忙应该能当成很好的锻鍊。『外表虽然不错，但内在完全是变态』——为了让平常总是擅自这样批评我的和真对我五体投地，我应该要好好学习她们的技巧！」</p><p>她毫无意义的充满了干劲呢。虽然这家伙很麻烦，但是在和真那群队友当中，已经算是比较好控制的家伙了……大概吧？</p><p>而且达克妮丝可能意外适合这里的工作。</p><p>「瑟娜小姐，还有……达克妮丝小姐。今天由我负责指导，还请两位多多指教。」</p><p>戴着只遮住眼睛的面具的萝莉梦魔向两人一鞠躬。</p><p>谎称今天是要变装接客的日子，让所有人都戴上面具。因为能靠这招隐藏瑟娜的脸，所以不用担心她身为检察官的事情会曝光。</p><p>「请多指教。」</p><p>「今天就麻烦你了……请问，我们有在哪见过面吗？」</p><p>达克妮丝端详起戴着面具的萝莉梦魔。</p><p>这么说来，我听说她们曾经在和真居住的宅邸打过照面。面具竟然在这时发挥了意想不到的效果。</p><p>「不，没有喔，应该是你的错觉吧。比起这个，我先简单为两位说明我们的工作内容。我们会询问客人的烦恼，绝对不否定对方的说词同时适当做出回应。接着委婉地促使客人决定今后的方针并给予合适的建议。」</p><p>「原来如此，是这样的工作啊。」</p><p>「感觉就很困难呢。」</p><p>瑟娜边点着头边写着笔记。达克妮丝则是一个劲地表达钦佩之意。</p><p>「那么，请两位前往那边的休息室更换衣服。」</p><p>「想直接在这边换衣服也无所谓喔。」</p><p>「请达斯特先生闭嘴不要说话，不然事情会变得很麻烦。」</p><p>萝莉梦魔最近变得很会耍嘴皮子呢，看来有必要再次让她感受一下我有多么伟大。等这件事结束之后，我就来好好教训她一顿。</p><p>在两人的身影消失在门扉的另一侧前，我的双眼一直盯着两人的屁股。她们真的都是身材一级棒的女人，偏偏在个性上……</p><p>「等等，这根本就是内衣啊！」</p><p>「先给我能遮住上半身的外套！请、请不要推我！」</p><p>惨叫声从门的另一侧传了出来。喔，看来她们两个人都很困惑呢。</p><p>今天准备的可是特制服装。虽然对这里的店员来说，就只是平常的打扮。</p><p>随着房门砰的一声打开，穿着梦魔打扮的瑟娜和达克妮丝被从房里推了出来。</p><p>「很适合嘛！」</p><p>那个布料少到只能稍微遮住胸部及下半身的服装，怎么看都跟内衣没两样。加上两人又拼命用手遮遮掩掩，反而使得情色度倍增。</p>`,410),e(f,{src:`/images/E1/05.avif`,alt:`插图`,width:`845`,height:`1200`}),s[13]||=a(`<p>由于其他的梦魔都很习惯这副打扮，所以我从来不曾看过她们害羞的模样，但是瑟娜和达克妮丝都害羞到满脸通红……也太撩人 。</p><p>「我没有办法穿着这么丢脸的打扮出去见人！」</p><p>「竟然让我穿上如此煽情的服装，然后丢到那群饥渴的男人面前，这是何等的奖励……不，我是说何等耻辱！」</p><p>瑟娜努力将手臂挡在胸前，想要掩藏几乎要从衣服中弹出来的胸部，却使得那对因挤压而变形的胸部看起来更加情色。</p><p>至于嘴上说不要身体却很兴奋的变态则是一如常态。</p><p>「没问题喔，因为我们今天只有找常客过来。而且，我们这里禁止客人触碰服务生，所以请放心吧。」</p><p>「我担心的并不是这个。」</p><p>「禁止触碰啊……这样啊……」</p><p>达克妮丝小姐明显感到很遗憾呢。这么想被摸的话，就让我彻底……还是算了。我不想再跟达克妮丝扯上关系，也不打算对和真的伙伴出手。</p><p>将详细说明交给其他梦魔负责后，萝莉梦魔小跑步来到我身边。</p><p>「达斯特先生。客人的准备呢？」</p><p>为了不让瑟娜听见，她在我耳边小声问道。</p><p>「嗯，我只有联络朋友过来。另外也有先跟冒险者们讲好，所以不会有其他客人上门。」</p><p>毕竟要是有不知情的客人来光顾就会马上穿帮。所以今天来场的客人全都是知情人士，我也有事先告知所有人，今天的设定是上门来找占卜师谈心。</p><p>「非常感谢。只要今天一切顺利，应该就没问题了吧。如果明天或后天能开始正常营业就好了。」</p><p>「那些男人们也差不多要到极限了。如果这边不能正常营业，很多事情都会变得很麻烦。」</p><p>「不好意思给各位添麻烦了。」</p><p>说明似乎已经结束，只见两人并排站在墙边。瑟娜低着头用调查表遮住胸部，达克妮丝一眼看上去似乎也很害羞，然而……她嘴角的笑意根本藏不住。</p><p>客人在开店的同时鱼贯而入，不过全都是我熟悉的面孔。</p><p>每个人在往座位移动时，都会用眼神跟我示意。那么，达克妮丝和瑟娜究竟会负责接待谁呢？</p><p>达克妮丝的客人是位一脸严肃的朋克头大叔。我经常会在冒险者公会看到这位大叔，但他没跟别人组队，也不知道他究竟在做什么工作。这位朋克大叔究竟是谁啊？</p><p>至于真正的目标瑟娜……虽然梦魔一直要她去接客，但是她似乎仍犹豫不决，不断重复跨出一步又缩回来的动作。</p><p>我观察了好一段时间，前前后后一小时左右她都是这副德性。再这样下去我想应该也不会有任何进展吧。</p><p>不过这家伙虽然觉得害羞，却很仔细地在观察男性客人。那是在学习接客态度吗？这还真像认真过头的瑟娜会做的事。</p><p>没办法，就让我来助她一臂之力吧。</p><p>「喂，把瑟娜给我叫来。干脆让她来接待我吧。」</p><p>「咦？这个不管怎么说都太过分了吧？」</p><p>「我是看瑟娜孤伶伶站在那边才主动说要陪她的耶。这时候明明就该感谢我，而不是责备我吧。」</p><p>「这么说也对，那我去叫她过来喔。」</p><p>萝莉梦魔的脚步相当沉重，感觉似乎不太情愿。瑟娜在被搭话后看了我一眼，还明显摆出厌恶的表情。她们就这样僵持了好一段时间……</p><p>在经过好几分钟的交涉后，萝莉梦魔拉着瑟娜的手走到我的座位。</p><p>瑟娜眉头深锁到几乎都快要留下皱纹了，这可不是服务业该露出的表情喔。</p><p>「有什么事吗？」</p><p>「瑟娜小姐，请保持笑容喔。我会陪在你身边，所以请放心。」</p><p>「明明就是找你来帮忙，要是都不工作会很没面子吧？所以本大爷才亲切地找你过来，要好好感谢我啊。」</p><p>「那个……非常感谢你。唉……」</p><p>瑟娜移开视线叹了口气。明明就在客人面前，竟然摆出这种目中无人的态度。</p><p>算了，无所谓。毕竟本大爷今天心情很好。好啦，究竟该怎么玩弄瑟娜呢？</p><p>「那么，你就听听我的烦恼然后给我建议吧。」</p><p>「好吧，如果是我知道的事就会回答。」</p><p>怎么感觉店员比客人还伟大啊？被面具后方那道锐利的眼神一直盯着看……感觉就像是在接受审讯耶。</p><p>「那么，就告诉我犯下轻微犯罪时不会被问罪的方法吧？」</p><p>「我怎么可能告诉你这种事！请正当地生活！」</p><p>这应该是最适合拿来询问检察官瑟娜的问题耶。</p><p>「啧，真小气。不然告诉我要怎么做才能让那对胸部长得那么大？我们队伍的琳恩，以及那边那个萝莉实在平到惨不忍睹。你如果能把方法说出来，她们应该也一定会高兴吧。我之后也打算去问问露娜。」</p><p>「不用你多管闲事！」</p><p>我会这么问明明是出于一片好意，结果连萝莉梦魔都气得鼓起脸颊。</p><p>「竟然堂堂正正在检察官面前性骚扰，你胆子不小呢。」</p><p>「这是在说什么啊？你今天只是一介店员，必须要好好接待客人才行吧。快点快点，快回答我的问题。让我见识一下你那能揭露罪行的巧妙话术啊～～」</p><p>我靠着椅背把脚翘到桌子上，一边揉着沉甸甸的眼皮这么说完之后，瑟娜的太阳穴就浮现出血管。</p><p>「你这家伙，下次被逮捕时给我记住。」</p><p>「好啦好啦，我好害怕喔～～」</p><p>这点程度的威胁我早就听腻了，就不能讲些更有内容的说词吗？</p><p>「好了好了，今天两位毕竟是客人与店员，还请稍微冷静一下，不然大家都在看我们。」</p><p>「这可不是什么表演，别给我在那边盯着看！」</p><p>「你这家伙真的是完全无视对象跟地点，见人就咬耶……」</p><p>「我还是会看对象好吗。如果对方是我绝对无法战胜的对手，我也是有愿意跪在地上舔对方鞋子的气魄！」</p><p>「这个人竟然可以如此骄傲地说出这种事……」</p><p>「人渣到这个地步反而令人佩服耶。」</p><p>不需要为这种事感到惊讶吧？这就是所谓的善于处世。</p><p>只有懂得处世的人，才能从冒险者这种危险又不安定的工作中获胜，这可是定论。</p><p>「达斯特先生，可以请你找比较正常的事商量吗？毕竟瑟娜小姐今天是第一次接触这份工作，请尽量提那种简单易懂的问题。」</p><p>就算你这样讲，我也没有什么要跟女人商量的事啊。烦恼的事﹑担心的事……</p><p>「那就钱吧。我想要做些什么来赚钱，你有没有什么方法？」</p><p>「只要辛勤工作就行了吧。不过你会没钱也未免太奇怪了吧？讨伐机动要塞毁灭者的奖金应该已经发给冒险者了，只要有那笔奖金，应该暂时不用为钱烦恼啊？」</p><p>「你说那笔钱啊。那么一点钱，光拿去赌博跟吃吃喝喝就全部用完了。不止如此，我还欠了一屁股债呢！」</p><p>「你的语气为什么还能带有一丝骄傲啊？」</p><p>「…………」</p><p>不要用沉默代替回答！我本来以为能拿到更大的一笔钱，结果大多奖金都给和真他们了。</p><p>不过还真是完全无法羡慕他，我才不想背上那么大一笔债务。和真也真是有够倒楣耶。讨伐魔王军干部时的欠债都还没还完就又增加了。</p><p>光是这样就足以让我放弃人生了，他竟然还要负责照顾中看不中用三人组。</p><p>看着明明一脸高兴，嘴上却说「不要看！不要用那种下流的眼神看我！」假装很讨厌的达克妮丝，我就打心底同情他。</p><p>所以当我听说和真将那笔高额债务还清时，我吓到心脏都快跳出去了。</p><p>「你应该没有因为欠债走投无路，就做出绑架或杀人这种事吧？」</p><p>「不要讲那种危险的事。我才没有堕落到那种程度。绑架倒是干过两次啦。」</p><p>诈欺跟勒索也就算了，我怎么可能去做出那种事情。</p><p>「两次……？」</p><p>「你、你这家伙……」</p><p>不要一脸害怕地向后退啊。</p><p>听到绑架这个词汇，让我不由自主说漏了过去的事。那时候的我还真是年轻啊……虽然也不算太久以前啦。</p><p>「喂，为什么露出那种眼神啊？正直善良的我怎么可能去做那种事。」</p><p>不止是瑟娜，就连萝莉魅魔也对我投以怀疑的眼神。</p><p>「先不管你的发言，是我说的太超过了。抱歉，竟然没有证据就怀疑你。虽然你经常闹事，但也没有犯过重罪……也是，说出来应该无所谓吧。你在小混混之中似乎算有头有脸的人物，那么你是否有听过这个消息呢？最近似乎有个奇特的犯罪集团从其他城镇潜伏进来。」</p><p>虽然瑟娜表情一变严肃地表示，但是我完全没有听说过这种事。</p><p>但是如果讲到最近发生的犯罪行为，那我就略知一二。</p><p>「那应该只是单纯的谣言吧？最近的犯罪啊……听说有强盗偷偷潜入杂货店大叔的店，结果他起动用来对付我的陷阱，就将所有人打退了。」</p><p>「咦、咦？」</p><p>「还有上次债主要求我立刻还钱，于是我跟他大闹了一场。」</p><p>「这种事你是从哪里……」</p><p>「另外就只有达克妮丝差点在暗巷被绑架，却还一脸高兴的事了。」</p><p>「不会吧，这可是大事耶！那群绑架犯后来怎么了？」</p><p>「嗯～～究竟是怎么样了呢？详情你去问达克妮丝不就知道了？」</p><p>「这么说也对，我之后再找机会去问清楚。」</p><p>犯罪集团啊，想在这座城镇犯案其实多少有些无谋呢。这里虽然被称为初学者城镇，不过也是有本领高强的家伙。</p><p>而且这座城镇的居民都尽是不会因为小事动摇的怪人，如果我是犯罪者而且想大干一票，那我绝对会避开这座城镇。</p><p>「那么，我们把话题拉回来吧。这座城镇的男性冒险者们，真的都喜欢男性吗？」</p><p>「喂喂，你是打算翻旧帐吗？这个话题已经结束了吧。」</p><p>「这与我的个人兴趣无关，只是单纯的疑问。如果真的对女人没兴趣只喜欢男人……那他们会像那样一脸猥亵地紧盯着女性看吗？」</p><p>听到瑟娜的疑问后，我的背后冒出大量的冷汗。</p><p>我悄悄往周围的那群人望去，就发现他们全都一脸松懈紧盯着梦魔们的胸部和屁股。</p><p>啊……糟糕啦啊啊啊啊啊！我完全选错人了！这群人压根本就是色鬼！</p><p>怎么办，在场的每个家伙的表情都已经不言而喻了。</p><p>「达斯特，我再问一次。这座城镇的男人们，真的都是对女性没兴趣的同性恋吗？」</p><p>面具后方的双眼非常认真。面对这种情况还能给出起死回生的解释，才是老子达斯特的真本事！别放弃，肯定还有办法！</p><p>「要我再把测谎用魔道具带来也无妨喔。这次就我们两个人单独对谈……如何？」</p><p>「瑟娜检察官，你可不要小看我喔？真是非常对不起！」</p><p>我从椅子上跳起，接着直接把头按在地板上跪地求饶。事已至此，我也只能乖乖道歉了！</p><p>「那就把详细情形全都交代清楚吧，嗯？」</p><p>啊，这下子完全变成审讯了。</p><h3 id="_6-2" tabindex="-1"><a class="header-anchor" href="#_6-2"><span>6</span></a></h3><p>让扮演客人的那群人以及达克妮丝先离开后，所有人都在只剩下梦魔﹑我以及瑟娜的店内跪坐。当然，是除了瑟娜以外的人。</p><p>「没想到梦魔竟然会潜入城镇当中，而且还在经营店家……怪不得有数名上司打算阻止昨天的调查。同性恋的事也是在说谎……」</p><p>毕竟警察内部有不少前冒险者。</p><p>瑟娜双手抱胸低声碎念。似乎是因为事情的发展太出乎预料，让她一时反应不过来。</p><p>「不过，我希望您能理解。男性冒险者与梦魔是互利互惠的关系。实际上，这座城镇的男性犯罪率跟其他城镇相比低上许多对吧？」</p><p>听到担任店长的性感梦魔的发言后，瑟娜变得一脸严肃。</p><p>一般来说冒险者较多的城镇犯罪率也会较高。毕竟干的是跟魔物打交道的工作，莽汉自然也比较多。</p><p>但是，这里多亏有梦魔们适当地吸取精气，冒险者们的欲望才得以降低。身为检察官的瑟娜，肯定比任何人都能亲身感受这件事所带来的影响。</p><p>「但我也不能放过身为恶魔的梦魔……再这样下去，女性的结婚率只会持续探底。」</p><p>果然没有这么简单就屈服啊。不过这个反应也在我的预料之中。</p><p>我在梦魔店长的耳边悄声说了几句后，她的面容瞬间亮了起来并高兴地点头。</p><p>「那么，您愿意跟我们做个交易吗？」</p><p>「竟然要我跟恶魔交易？这提案也未免太蠢了吧。」</p><p>虽然瑟娜一副拒绝对话的模样，但是在听到内容之后，她是否还能说出相同的话呢？</p><p>「如果您愿意放过我们……我们能让瑟娜大人喜欢的男性每天都梦见您，甚至有可能让他喜欢上您喔。除此之外，我们还可以提供各种场景的梦境。即使是瑟娜大人不能对外人说的愿望也能在梦中实现。」</p><p>「愿闻其详！」</p><p>瑟娜以迅雷不及掩耳的速度冲到梦魔面前，并且紧紧握住对方的手。</p><p>「所以这样就解决了吗？」</p><p>我用笑容回应歪着头看向我的萝莉梦魔。</p><p>「是啊。你也辛苦了。可以顺利重新开始工作不是很棒吗。」</p><p>「是的，这样我就放心了。真是多亏有达斯特先生帮忙，太感谢你了。」</p><p>「那么一星期免费的事情就麻烦你了。」</p><p>「好，那从今天开始的一个星期都免费。我身为恶魔，绝对会遵守契约。」</p><p>「喔喔，我很期待。这么一来我就有一个星期不需要担心那件事了，之后只需要确保睡觉的地方跟食物就能活下去。」</p><p>不但被感谢还能收到回礼。这简直太棒了。</p><p>能圆满解决真的比什么都重要。这么一来我就能放心享受今晚的梦境了。</p><p>「这么说来，达斯特先生，我还有事情要找你。」</p><p>似乎跟梦魔达成共识的瑟娜朝我走了过来。</p><p>「怎样啦，为什么讲的那么慎重？这间店的问题已经都解决了吧？」</p><p>「是啊，的确如此，所以跟这间店无关。你刚才似乎有主动供出自己欠债不还，而且大闹了一场的事对吧？由于之前曾有贷款业者来报过案，我希望你能详细交代这件事。」</p><p>脸上堆满了笑容的瑟娜用力抓住我的双肩。</p><p>「等、等一下！」</p><p>「想都别想。你刚刚有要求我让你见识巧妙的话术对吧？没有问题，我打算拘留你两个星期左右，你就在这段时间好好享受吧。真是太好了呢，这样你就不用担心吃住喽。」</p><p>啊，可恶。这家伙的力量出乎意料的大啊！她的手指掐入我的肩膀，完全无法扯开！</p><p>看来她对我刚刚的挑衅仍怀恨在心。</p><p>「喂，不要只顾着看，快来帮我！」</p><p>虽然我向站在一旁的萝莉梦魔求救，但是在看了看我跟瑟娜后，她露出微笑重新面向我，接着在我耳边轻声表示：</p><p>「如果您要接受拘留所的照顾，那我们就无法去打扰了。毕竟那边有驱赶恶魔的结界……而且如果达斯特先生不能来店里告诉我们梦境的内容……啊，不过我们已经缔结契约了耶。」</p><p>契约？该不会是指谢礼吧？应该不是吧？你那道别具意义的笑容究竟是什么意思？</p><p>「咦？喂！难道说……你是指我们约好的一星期免费……」</p><p>「是啊，看来是无效了。既然无法做到，那么也没办法啊。毕竟对恶魔来说契约有着绝对性，所以无法取消喔。」</p><p>「不不不，竟然要我做白工？这是在开玩笑吧！喂，别笑了，你看着我说话啊！等等，瑟娜大人，拘留的事情能不能晚一星期再说？呐，拜托你们听人说话好吗？这群恶魔！」</p><p>「喂！还不能吃饭吗？今天麻烦给我全餐啊！」</p><p>在已经成为我第二个家的拘留所牢房里，我躺在单薄的毛毯上对守卫提出要求。</p><p>「吵死了！不是才刚刚吃过午饭吗！你是老头子啊！」</p><p>「那至少拿些点心来啊。最近大街上不是开了间时髦的咖啡厅吗？那边的东西我还可以接受喔。」</p><p>水桶代替回应当的一声砸中牢房，是那个可恶的守卫丢过来的吧。瑟娜竟然完全无视我的解释将我关进拘留所已经过了两天，看来最少还要被关一个星期以上。</p><p>「反正手边也没钱，这样正好。但一星期的免费服务真是太可惜了。是说我什么都没讲就被关进来了，伙伴们没问题吧？琳恩应该正在生气吧。」</p><p>虽然琳恩外表看来沉稳，实际上却很容易激动过度。以前也曾经一开始说教就立刻朝我轰出魔法……还是先想好借口吧。</p><p>「喂，达斯特！有你的东西！」</p><p>已经相当熟识的守卫拿着用白纸包裹的细长东西，从牢房栅栏的缝隙递了进来。我扯开白纸后，里面是还带有余温的长棍面包。</p><p>这东西究竟是谁送来的根本是一目了然，她肯定是边抱怨边买 的吧。</p><p>「是那家面包店的长棍面包啊……谢啦。」</p><p>我开口向不在场的那位喜欢番茄的同伴道谢。</p><h2 id="插曲-某位贵族的宝物" tabindex="-1"><a class="header-anchor" href="#插曲-某位贵族的宝物"><span>插曲 某位贵族的宝物</span></a></h2><p>「早安，今天的天气也很好呢。」</p><p>我朝着枕边的相框露出了微笑。</p><p>那里有着达斯特先生一脸帅气地在威胁新手冒险者的身影。</p><p>无论什么时候看都很帅气的侧脸。在我委托特别擅长潜伏的盗贼帮忙拍摄的照片中，这是最棒的一张，是我重要的宝物之一。</p><p>「今天起床时的心情依然棒透了，这都是托了梦魔们的福。」</p><p>偶然得知那间店后，多亏有她们让我能梦见自己渴望的梦境，每晚才能过得如此充实，所以必须好好感谢她们。</p><p>那是在现实当中，绝对无法跟达斯特先生一同度过的甜蜜时光。但光是靠着那个梦境，我今天也能继续努力下去。</p><p>身为阿克西斯教徒，向梦魔这种恶魔寻求帮助的行为本来是绝对不被允许的，但是我相信女神大人一定能理解我纯粹的思念。</p><p>换完衣服吃过早餐后，我跟往常一样出门上街。</p><p>达斯特先生在这个时间不是醉到不省人事，就是待在从早上就开始营业的赌场。根据今天早上放在窗边的报告书判断，昨晚一个叫和真的新手冒险者似乎有请他喝酒，所以现在应该还在睡觉吧。</p><p>和真就是那个带着三名女性的冒险者吧。明明已经坐拥后宫了，竟然还打算对达斯特先生出手。我明明只能在远处偷看，或是收收偷拍的照片及记载了达斯特先生日常生活的报告……</p><p>竟然和那个我只能在梦中触碰的达斯特先生勾肩搭背，把酒言欢。</p><p>「实在太令人羡慕了！」</p><p>如果达斯特先生是对女人出手也就算了，我绝对无法原谅有我以外的男人待在他身边！</p><p>哎呀，不能因为这点小事而自乱阵脚。毕竟在我和达斯特先生之间，本来就隔着一道巨大高墙。所以我必须要放宽心胸，绝对不能失去冷静。</p><p>唉……究竟要到什么时候，我才能实际跟达斯特先生交谈，坐在他身边相互接触呢？</p><p>我边散步边巡回各间店家，仔细观察各式各样的道具。毕竟偶尔还是能在古董中发掘出宝物，所以不能小看这些东西。</p><p>像这条项链被当成是能反转谎言的魔道具贩卖，但无论怎么看都是赝品。听说这个最近在贵族之间相当流行，大家也太容易受骗了吧。</p><p>然而这东西价格便宜，加上设计也还不错，所以买下来也无妨。</p><p>「欢迎光临，欢迎光临。这里有最近刚进货的高性能头盔，价格划算喔！」</p><p>这道叫卖的声音，不就是经常和达斯特先生打情骂俏的杂货店老板吗？他每次都像在跟我炫耀般与达斯特先生打打闹闹……咦？写着主打商品放在店头的那顶头盔……难不成是！</p><p>「可以打扰一下吗？」</p><p>「当然，欢迎光临。啊，是贵族大人啊，有什么事吗？」</p><p>毕竟我的发色及双眼正是贵族的象征，所以才会被直接看穿吧。为了守护达斯特先生，我最好还是不要暴露身分。下次出门可能稍做变装会比较好。</p><p>「我想看看这顶头盔。」</p><p>「哦，是指这个吗？您的眼光真是不错！这虽然是二手货，却是品质优良的逸品呢。若是识货的人，肯定能一眼看出这笔买卖有多划算吧。」</p><p>这顶头盔的品质确实很好，但是这些事根本无关紧要。这个形状、这股光泽，难道说这是达斯特先生以前用过的头盔吗？</p><p>「你是从什么管道取得这顶头盔的呢？」</p><p>「关于这点啊，其实有个总是给我添麻烦的小混混冒险者，这正是从他那边高价收购来的头盔。」</p><p>这个……绝对没错！太感谢祢了，阿库娅女神！我有加入阿克西斯教团，而且每天持续祷告，真是太好了。谢谢祢，女神大人！</p><p>我虽然有收到达斯特先生购买魔剑的报告，却不知道他有将头盔卖出去。看来之后必须向盗贼下达更详细的指示才行呢。</p><p>「这个可以卖给我吗？」</p><p>「您要购买吗？那我这就把它装起来，请稍等。」</p><p>「不，这样就可以了。」</p><p>现在无论是一分一秒都很宝贵。动作快，快点把达斯特先生戴过的头盔给我！</p><p>「这、这样啊。谢谢惠顾。」</p><p>「拿去，散钱不用找了。」</p><p>我连付钱都觉得焦躁，接着急忙用类似抢夺的动作接过头盔。虽然老板一脸惊恐，但现在根本不是管他的时候。</p><p>我将头盔抱在怀里，急急忙忙穿过大街跑进巷弄当中。</p><p>附近……没有任何人在。</p><p>这、这、这就是，达斯特先生曾、曾戴过，接触过他头发、肌肤以及嘴唇的头盔啊啊啊！</p><p>「吸————！这就是达斯特先生的味道！混杂残留在铁锈味中的些许汗香，这就是……这个就是——！」</p><p>尽管只是吸了一口气，我都觉得似乎就快高潮了。但还不够。接下来才是重头戏。要动手了，我真的要动手了！</p><p>我用双手握住头盔侧面，把它对着天空高高举起。</p><p>啊啊，接下来我就要与达斯特先生合而为一了……戴上！</p><p>「我现在正被达斯特先生包覆着！这是何等的幸福。啊、啊、啊、啊、啊啊啊！就算把内侧整个舔一遍也没有关系吧！毕竟这是我的东西了！」</p><p>我再也不会放手了！从今天起只要外出我一定会戴着这顶头盔！</p><p>其实我连待在家里时都想戴着，但双亲肯定会反对吧。</p><p>从这天起，我的宝物又增加了一个。</p><h2 id="终章-跨越那段过去" tabindex="-1"><a class="header-anchor" href="#终章-跨越那段过去"><span>终章 跨越那段过去</span></a></h2><h3 id="_1-5" tabindex="-1"><a class="header-anchor" href="#_1-5"><span>1</span></a></h3><p>「事情就是这样，实在有够倒楣。」</p><p>我现在人在常去的那间餐厅，正比手划脚毫无隐瞒地详细向伙伴们交代两星期前的事，但是他们却没什么反应。</p><p>他们始终只有看着我，从头到尾都一语不发。</p><p>「接下来，她就一直把我关在牢房里耶。结果我不但做白工，还受到这种待遇！」</p><p>虽然我把所有事情都交代完，但是无论琳恩、泰勒或奇斯都毫无反应。就仿佛我根本不在这里。</p><p>「虫子飞来飞去的声音好吵喔，奇斯，我们什么时候出发？」</p><p>「是啊，嗡嗡嗡的真是烦死了，再十分钟左右吧，人应该快到了。」</p><p>「他看起来个性相当认真，肯定会严守时间吧。」</p><p>竟然完全无视我开始讨论起别的事情。虽然整整两个星期联络不到人的确很糟糕，不过对我来说这也算是一场意外啊，实在不需要气成这样吧？</p><p>本来还想说既然琳恩知道就不用担心，我实在太天真了。</p><p>「被这样无视我会很受伤耶！既然你们听不见我的声音，那我要开始讲超下流的黄色笑话喔！……所以说，是什么委托？」</p><p>没有人开口回答我。这、这几个家伙……</p><p>「哦，既然各位看不见我那就没办法了。换句话说，现在我无论做什么都可以对吧。首先来将那对平坦的胸——」</p><p>才刚听见咚的一声，一把短刀就插在桌面上——我的手掌旁边。</p><p>至于将这把刀插在桌面上的人，不用说自然是琳恩。她的双眼露出看着害虫的鄙视眼神。</p><p>而且这把短刀不正是我先前在马厩打算对她出手时，差点把我的某样东西切掉的武器吗！</p><p>「唔、呃，对不起。真的很抱歉，琳恩。」</p><p>虽然我把头靠在桌上道歉，但那家伙的回应只有「没钱就去跟那个女孩借啊？」一句话。</p><p>「不好意思让大家久等了！咦，这位先生是？」</p><p>一名我不曾见过的男人露出爽朗笑容走到我们身旁。</p><p>从他穿着皮铠背后背着一把长剑来看，应该是战士系职业。</p><p>「这家伙只是个无业游民，不用太在意。今天还请多多指教。」</p><p>「拜托你喽。」</p><p>「不用太担心，只要仔细听从指示就行了。」</p><p>「好的，请大家多多指教！」</p><p>大家为什么对这家伙这么亲切啊？他们在面对这个看起来就很好骗的男人时，那个态度就仿佛是在对待伙伴……等等，难道说……</p><p>「喂！难道这个家伙是……！」</p><p>「这个人就是代替消失了两个星期的你，跟我们组队的新伙伴。」</p><p>为什么就只有不祥的预感一定会成真呢？</p><h3 id="_2-5" tabindex="-1"><a class="header-anchor" href="#_2-5"><span>2</span></a></h3><p>「可恶，竟然真的关了我两个星期。唉，结果也没得到梦魔的奖赏，就已经没钱了还祸不单行，根本就只有损失啊。」</p><p>我坐在靠窗的贵宾席上叹了口气。</p><p>「这世上有那种能轻松赚大钱的家伙在，同时却也有像我这种明明拼命工作，却依然无法摆脱贫穷的人，实在有够不公平！真是该死！」</p><p>明明我的抱怨响彻整间店面，却没有人回应我。</p><p>巴尼尔老大和悠悠明明也在这里。</p><p>老大似乎正忙着打扫店面，但悠悠就只是坐在对面玩着扑克塔。</p><p>虽然悠悠从刚刚开始，似乎就边偷瞄边寻找邀请我一起玩扑克牌的机会，但是一路被我彻底无视后，她又变得一脸不爽。</p><p>「唉，真是不幸啊。难道就没有温柔的朋友在听说我有多么倒楣后，愿意请我吃饭并给我钱吗？」</p><p>「你不要以为只要说我们是朋友，我就什么都愿意帮忙喔。」</p><p>「如果没有要买东西就快点离开这间店。吾还要想办法处理废物老板买来堆仓的瑕疵品。」</p><p>「无论是老大还是臭小鬼，你们对我温柔一点嘛。」</p><p>巴尼尔老大继续打扫店面，悠悠则开始叠扑克塔的最顶层。</p><p>伙伴们也丢下我出发去冒险了，来个人陪陪我啊。</p><p>「没有必要温柔对待一个叫别人臭小鬼的人吧。」</p><p>听到悠悠不屑地如此表示后，我就不爽地抓住桌角用力摇晃起来。</p><p>「请、请不要这样！今天的扑克塔是使用了两副扑克牌的超级大作耶！」</p><p>「真拿你没办法，我就陪你一起玩吧。就用这座塔来玩抽抽乐，我先进攻！」</p><p>「哇啊！就是因为爱做这种事，你才会不受欢迎啦！」</p><p>正当我玩弄着努力稳住桌面做出抵抗的悠悠时，巴尼尔老大砰的一声将一个小箱子放到桌上。</p><p>「啊啊啊啊啊！刚刚的冲击弄倒我的扑克塔了！」</p><p>「哎呀，原来汝在啊，孤独至极之人。小混混冒险者，吾免费给予汝一样魔道具，作为交换，汝快把这个小女孩带走。」</p><p>「哦，要免费给我吗？真是太感谢了。除了病痛以及阿克西斯教团入教书外，我都会满怀感激地收下。」</p><p>虽然我仔细观察了放在桌上的小盒子，却完全看不出来究竟是什么。</p><p>「老大，这个盒子是什么魔道具？」</p><p>「可以彻底改变冒险时如厕问题的划时代魔道具。只要打开箱子就能够完成搭建，经过魔法压缩过的简易厕所，而且附带完善的水洗、遮音机能，是女性也能安心使用的优秀道具。」</p><p>「喔喔，这东西很棒啊！之后就算说要回收我也不会还喔！」</p><p>虽然不太懂老大究竟在想什么，不过这东西绝对能赚钱。毕竟包含琳恩在内，女性冒险者在野外如厕时的问题相当多。</p><p>「吾才不会说出那么小气的话。只是这东西有个小问题，就是遮音机能的声响太大，可能会引来魔物。另外虽然能产生水，但因为无法控制，所以附加了让周围也积水的额外机能。」</p><p>「这根本就是不良品吧……我还是不要了。」</p><p>「唔嗯。由于不能退货，吾原本想要硬塞给汝呢。那么，换成这个如何？」</p><p>老大在回收简易厕所后，重新拿出了一颗大球。</p><p>不但球体透明，中间还能看到噼哩啪啦闪耀的光芒。</p><p>「老大，这个是？」</p><p>「封印了强力雷击的球。听说其威力足以让凶恶的魔物昏厥。」</p><p>「的确，我能从中感受到强大的魔力。」</p><p>振作起来的悠悠盯着球佩服地表示。既然红魔族都这么说了，那应该不会有错吧。但是……这个发展只让我有不祥的预感。</p><p>「缺点呢？」</p><p>「汝会如此慎重还真是稀奇呢。问题点在于不用双手捧住就不会发动，而且释放出的雷击不是往前射出，而是只会落在正下方，仅此而已。」</p><p>「这根本只能拿来自爆吧……老大，容我拒绝。」</p><p>我把球还给老大后，他就重重叹了口气。</p><p>「果然没人要啊。本来还想说能多少处理一下那个毫无商业才能的老板买来堆仓的废物，看来没办法那么顺利呢。算了，等汝想要的时候就来拿吧，吾可以免费提供。」</p><p>竟然能让总是自信满满地戏弄他人的老大变得如此失落，这里的老板实在不是等闲之辈。</p><p>「先别提那些了，老大，你听我说！我的伙伴们竟然无视我的存在，跟临时雇用的家伙一起去冒险了。这根本难以置信对吧！」</p><p>「他们终于放弃汝了啊，这完全是汝自作自受，此决定乃身为人类理所当然的判断。」</p><p>「就是说啊。不如说真亏他们能包容你到现在。」</p><p>竟然连老大跟悠悠都站在他们那边。</p><p>「所谓的伙伴，不是应该要同甘共苦吗？在我欠债的时候一起帮我还钱，如果朋友赚了钱就要请我吃饭，这才是做人该遵守的道理吧！」</p><p>「这样只有汝得到好处吧。虽然身为恶魔的吾不适合说这种话，不过汝毫无身为人的伦理观念嘛。」</p><p>「达斯特先生在讲做人的道理……这比惠惠宣言『我今天不放爆裂魔法』还没有说服力。伙伴可是非——常重要的存在喔！」</p><p>这两个人不但没有帮我说话，悠悠甚至得意忘形地开始念我。</p><p>琳恩和泰勒也是只要一见面就对我说教。这群人的个性都太过认真了。</p><p>个性严谨不懂变通的人只会徒增辛劳，人生不但得不到好处还很吃亏喔……</p><p>「怎么了？为什么突然陷入沉默？那种担忧的表情根本不适合你喔。」</p><p>「啊，这么认真的表情还真是少见。」</p><p>「少管我。啧，真是有够烦人，我要走了。」</p><p>又想起过去的事情了……在没被追问前快点离开吧。</p><p>我立刻起身往门口走去。</p><p>「与过去诀别的小混混冒险者啊。就让吾这个看穿一切的恶魔给汝一个建议吧。绝对不要大意。」</p><p>「喔、喔喔。虽然不知道老大是指什么，但是谢谢你的忠告。」</p><p>我听了巴尼尔老大从背后传来的忠告，开口道谢后便走出魔道具店。</p><p>「老大早就看穿了吗？我原本以为自己已经彻底舍弃过去了……」</p><p>唉……像这样陷入纠结的思绪中，根本不是我的作风。</p><p>比起过去现在更重要。我得想想该怎么活过今天。</p><p>「看来也只能去工作赚钱了。」</p><p>这么一来，就只能去冒险者公会寻找合适的委托了。</p><p>「实在有够麻烦。」</p><p>持续过了两个星期不用工作就有饭吃的生活后，我实在提不起任何干劲。</p><p>不过现在已经不是说这种话的时候了，就去冒险者公会看看吧。</p><p>「嗨～～」</p><p>当我用力地打开出入口的大门后，所有人的视线都往我身上集中过来。</p><p>「喂喂，为什么每个人都垂头丧气啊，老子达斯特凯旋啦！」</p><p>好一段时间没来这里了。我抬头挺胸迈着大步往公会的正中央走去。</p><p>当我通过几个认识的冒险者聚集在一起的座位时，听见他们正在窃窃私语，于是我放慢脚步竖耳聆听。</p><p>「喂，达斯特根本就没事啊！」</p><p>「到底是谁说达斯特得了怪病所以住院去了？」</p><p>「我是听说他对检察官瑟娜毛手毛脚被捕，至少会被关在牢里一整年喔。」</p><p>「咦？你先前不是说他跑去找御剑先生的碴，结果不得不逃离这座城镇吗？」</p><p>「毕竟那家伙怎么可能整整两个星期不闹事啊。虽然我有去问过琳恩，不过她只给了『我不想管那件事』这种意味深长的回答。」</p><p>我完全停下了脚步。</p><p>这群人会注视我都是因为这些理由吗！</p><p>「你们这些混蛋不要在那边乱说话！老子我活得很好！」</p><p>当我发出响彻整个公会的怒吼后，所有人都陷入沉默——</p><p>「啧，如果被吼一下就会害怕，那就不要在背后说坏话啊！」</p><p>「啊啊，可恶，达斯特根本超有精神啊！」</p><p>「公会最近好不容易才这么和平！」</p><p>「我可是赌达斯特一个月不会出现，而且还赌了一万艾莉丝耶。该死的！」</p><p>接着转变成惨叫及怒骂声四射。</p><p>「你们这群混蛋竟然敢拿我下赌！早点说啊！这样我也能参一脚了！」</p><p>「达斯特先生一出现就让公会充满活力呢，好久不见了。」</p><p>露出苦笑向我搭话的人，正是公会的柜台小姐露娜。</p><p>她那对丰硕的象征今天也闯入我的眼中，让人下意识就把视线往那边集中。</p><p>「喔，你今天也很有精神地在晃动吗？」</p><p>「小心我禁止你进出公会喔。」</p><p>露娜那种顶着专业笑容讲出的反击今天依然很犀利。</p><p>毕竟她每天都在跟冒险者们打交道，不会因为一点小事就动摇。</p><p>「禁止我来对公会来说可是莫大的损失喔。」</p><p>「这就难说了。毕竟即使达斯特先生这两星期都不在，公会依旧能够顺利营运呢。」</p><p>喂喂，感觉露娜今天比平常更带刺耶。虽然她脸上堆满了笑容，魄力却比平常更强，但是我不记得自己有做过什么会让她生气的事啊。</p><p>「这、这样啊。现在有没有适合我的委托？」</p><p>这时候还是干脆一点转换话题比较好，毕竟我最近可是深切体会到女人有多么恐怖。</p><p>「关于这点，毕竟季节已经是早春，要说委托当然是有……不过泰勒先生他们已经雇用临时队员出发去冒险了吧？」</p><p>不要用手指抵着脸颊轻轻歪着头啦，你已经不是能做这种动作的年纪了吧……虽然很想这样讲，但我努力忍住了。</p><p>如果继续多嘴，别说禁止进出公会，甚至连冒险者卡片都有可能被没收。</p><p>「要独自一人完成委托可是很困难的事情喔。虽然最近有位单刷的大魔法师相当活跃。」</p><p>「喂喂，独行魔法师未免太少见了吧，和真那边的爆裂女孩就绝对办不到这种事。」</p><p>「的确是如此。毕竟一般的魔法师多是在前卫的保护下，从后方施放魔法呢。」</p><p>能独自完成任务啊，那家伙的身手应该相当厉害吧。真想知道究竟是谁……嗯？孤独的魔法师……我似乎认识一个这样的人喔。</p><p>虽然有些在意，不过现在的重点是钱。比起别人的事情，自己的事情当然更重要。</p><p>「距离高丽菜的收获期还有一段时间，这么一来就是讨伐巨型蟾蜍了……不过在城镇周边冬眠的巨型蟾蜍，都因为某人深夜在城镇附近施放爆裂魔法而苏醒，所以附近的目标应该都已经被讨伐了，目前并没有驱除巨型蟾蜍的委托。」</p><p>「这么说来……听说我跟和真一起蹲牢房时，每天晚上都有笨蛋在外面大闹呢。」</p><p>虽然似乎引发了相当大的骚动，不过我都睡得很熟所以没啥印象。</p><p>至于半夜打扰居民的犯人则是立刻就被抓到了……与其说抓到，不如说除了那家伙以外不做他想。</p><p>毕竟就是这么一回事。在这座城镇中能使用爆裂魔法的人，就只有和真队上的爆裂女孩和魔道具店的穷鬼老板。至于讲到究竟哪个人会做出这种蠢事，那根本连思考都是浪费时间。</p><p>「所以目前就只有在城镇里打杂，以及要出远门的委托。不过由于是达斯特先生……所以打杂的委托……都无法交给你负责。」</p><p>露娜耸了耸肩没有看向我，还不断摆动着手指……她肯定隐瞒了什么事。</p><p>「平常我是不会接下那种无聊的工作啦，不过现在有些走投无路了。如果能给我轻松的工作，那当然是更好。」</p><p>「都到了这个地步，你还想挑选轻松的工作啊……真要讲起来，你本来就没有挑工作的权力呢。不只如此……算了，直接说出来会比较好吧。所有的委托人全都反过来指名，说绝对不要让达斯特先生接下委托。」</p><p>「啥——？这到底是怎么回事？」</p><p>「一言以蔽之，这是你的平日言行带来的结果。毕竟你总是在城镇中四处引发问题，所以才被大家警戒吧。」</p><p>「喂喂，别胡扯了，你倒是说说我做了什么啊？」</p><p>不过就是在喝醉之后稍微胡闹了一下，这反应也未免太夸张了吧。</p><p>无论是谁都多少做过这种事吧？我绝对要找到讲出这种蠢话的家伙，要求他赔一大笔酒钱治愈我受伤的心灵。</p><p>「竟然你都开口问了……这份资料统整了对达斯特先生的申诉，我就一一念出来吧。偷窥女澡堂、吃霸王餐惯犯、对警察动粗、破坏公物、欺诈、打架骚动、强行搭讪……还有很多呢，你想要继续听吗？」</p><p>「今天就先到此为止吧！」</p><p>我判断继续待在这里不是什么好主意，于是赶紧转身离开冒险者公会。</p><p>不过无法从公会那边接到委托实在太令人困扰了。这全都是因为琳恩他们丢下我跑去冒险害的！等那群人回来之后就等着瞧，我要把他们的奖金一毛不剩全都诈光！</p><p>「唉，饿死啦。」</p><p>我的肚子从刚刚就不断发出咕噜咕噜的美妙声响。</p><p>不过就算能吃霸王餐，如果无法借到钱，那就算捱得了今天也过不了明天啊。</p><p>「钱……这么说来，我不是有个超级有钱的挚友吗！」</p><p>明明直到前阵子都背负着庞大债务，过得比我还要凄惨，却靠着讨伐魔王军干部的奖金一口气变成大沃尓沃的那个家伙！</p><p>「来去凹和真吧。只要说我找到一间全都是由穿着暴露的大姊姊在当服务生的餐厅，那家伙肯定会立刻上钩。接下来只要再稍微煽动一下……毕竟朋友可是很重要的啊！」</p><p>而且就算他小气到不肯请我，也还有跟和真他们组队去冒险这个手段。虽然我不觉得自己可以控制住那群人，不过这种事就交给朋友负责吧。</p><p>也只有和真能够管控那三个女人了。</p><p>当然，我也不会一直让人请客。只要遇到困难我也会帮忙，等我有钱时也打算加倍奉还。只是不知道何时才会有钱就是了。</p><p>「和真那家伙意外地混得不错呢。不知不觉间连豪宅都有了，还能跟美女同居。一般来说我应该会嫉妒到抓狂，但是要跟那三个人住在同一个屋檐下……该怎么说呢……」</p><p>嗜酒如命还喜欢开宴会的阿克西斯教大祭司。</p><p>除了爆裂魔法一无是处的大魔法师。</p><p>攻击永远打不到敌人的被虐狂十字骑士。</p><p>……果然完全羡慕不起来。</p><p>「喔，已经到啦。这栋豪宅还是一样壮观呢。好啦。和真，你在家吗！」</p><p>我虽然在门前大声叫道，却没有任何人出现。尽管我又叫了三次，门内却是毫无声响。难道没人在吗？</p><p>「不会真的没人在家吧？喂喂，这下该怎么办才好？」</p><p>一旦我的救命稻草和真不在，那情况就完全不一样了。</p><p>到了这一步，我只能向琳恩他们低头道歉吗？实在不太想先夸下海口又跑回去拜托，毕竟我还是有自尊的啊。</p><p>但将自尊与金钱放上天秤测量的结果……是大大倾向金钱那一方。</p><p>「等他们回来之后就去道歉吧，没办法了。」</p><p>我确实有些不对的地方，这时候就该像个男子汉低头道歉。</p><p>如果不是前往太远的地方，和真他们应该明天就会回来了。今天只要先想办法确保睡觉的地方，如果有附餐自然更好。</p><p>就没有能让我痛殴一顿并收刮钱财也不会出事的小混混吗？我试着在暗巷绕了一圈，偏偏今天连一个人都没遇上。</p><p>「今天未免太倒楣了。真要说起来，都是这座城镇的治安太好了。」</p><p>阿克塞尔跟别处相比算是相当和平。不但有很多像是巴尼尔老大和大叔那种执着于赚钱，个性非常强悍的商人，就连居民跟其他城镇的比起来也全是怪人。</p><p>冒险者更尽是个性十足的家伙……真是永远不会觉得无聊的城镇。</p><p>「我其实根本不该过来这里吧。」</p><p>现在不是为了这种无聊的事情跟伙伴们闹翻的时候。我这就动身追上他们，然后好好道歉，请他们让我也一起行动吧。</p><p>正当我改变想法，转身打算前往公会询问伙伴们的去处时，突然有人从背后叫住我。</p><p>「达斯特先生？有什么事吗？」</p><p>一身村女打扮的萝莉梦魔突然从暗巷的转角探出头来。</p><p>难道说在我陷入思考时，身体根据平常的习惯走到梦魔店附近了？</p><p>「啊，难不成你是来抱怨一星期免费的事情吗？因为恶魔非常重视契约，所以无论发生什么事，都不能取消或更改已经签订的契约喔。」</p><p>毕竟当时的我连作梦都不会想到竟然会被拘留两个星期。事到如今，也无法说出「再让我免费一星期」这种话……虽然我很想说啦。</p><p>然而与恶魔之间的契约有其绝对性，也只能乖乖接受了。</p><p>「我才不会说那种小气的话呢。」</p><p>而且我现在必须去找琳恩他们才行。那是愿意跟我这种人组队的伙伴，当然要放得比任何事都重要。比起纠结过去，还是要把目光放在当下吧。</p><p>「这样啊。这还真不像欲求化身的达斯特先生会说的话耶……怎么了吗？」</p><p>「没什么，我现在很忙，如果没有要事那我先走了。」</p><p>如果不快点动身，与琳恩他们的距离会越拉越远。</p><p>「我知道了，那我就只说正事吧。关于先前帮助我们时的谢礼变得无效一事，我还是感到相当愧疚。所以只有今天一天我们硬是让店面公休，好让达斯特先生独自包场，我们会全员出动一起招待你。不过看你似乎相当忙碌，所以很遗憾……」</p><p>「谁说我很忙了！」</p><p>「咦？达斯特先生刚刚才说……」</p><p>「是你听错了。快告诉我详情！」</p><p>虽然很在意琳恩他们，不过等他们回来再说也无妨，毕竟不是什么攸关性命的事。现在这边比较重要！</p><p>「不过，真的没关系吗？你刚刚看起来相当焦急呢。」</p><p>「嗯，不用在意。我也完全不在意喔。」</p><p>这么好的机会绝对不会有第二次了，我怎么可以错过！</p><p>我打心底相信伙伴们肯定也能够理解我的决定吧……</p><p>「那么，请在今天晚上过来我们店里。我们也会准备食物，所以请不要先吃晚餐喔。」</p><p>「好，我很期待！」</p><p>看来有机会从最恶劣的谷底转变成最美妙的一天。</p><p>这么一来也不用担心吃饭问题了，接下来只要等到天黑啊。梦魔们的盛情招待耶，实在太令人期待了。</p><p>到时应该也有包含夜晚的服务吧？虽然在梦中也很棒，不过能在现实中被性感的大姊姊包围……呵呵呵呵，快点天黑吧。</p><p>「所以……成功了吗？」</p><p>怎么，是不是有粗勇的男性声音从某处传来？</p><p>我环顾四周后，发现自己正身处不曾来过的地方。大概是忙着妄想，所以一路走到暗巷深处了吧。</p><p>「是的……似乎已经成功潜入了。」</p><p>这次又传来跟刚刚不同的男声，对方似乎人就在前面的转角。</p><p>来的正好，反正在天黑之前我都很闲，就去观察一下打发时间吧。毕竟我今天相当走运，如果能探听到可以赚钱的事情就太棒了。</p><p>我消除脚步声静静移动到转角，没有直接探头窥视，而是拔出剑将对方的模样倒映在剑身上。</p><p>两个一脸可疑的男人。那副面相一看就不是什么正经的家伙，浑身充满了犯罪的气息。</p><p>「不过这座城镇到底是怎么回事啊？不都说是初学者城镇吗？」</p><p>「先前打探到的消息确实是如此呢，偏偏尽是些麻烦的怪胎，所以进展得很不顺利。」</p><p>「那群家伙真的是新手吗？」</p><p>多亏有那间梦魔店，所以也有中坚冒险者还留在这座城镇，我完全可以理解他们不想离开的心情啊。</p><p>不过，总觉得我好像在哪里听过这个声音？</p><p>「绑架的工作也失败了。实在没想到贵族千金会是那种人……我们明明也是为了钱，才心不甘情不愿地打算绑架她。」</p><p>「毕竟也有人跑来碍事啊。如果不是那种人，我们应该还会有点干劲吧。那实在是看不下去。」</p><p>喂喂，这群家伙该不会是那个打算绑架达克妮丝的奇葩集团吧？</p><p>瑟娜似乎也说过有犯罪集团潜入阿克塞尔之类的事情。</p><p>这时候还是先不要多管闲事吧，毕竟我的身分已经曝光了。换作平时应该会召集伙伴袭击他们的基地，再把值钱的东西全部搬光，但现在只有我孤单一个人。</p><p>加上我今天晚上也没空，就当作没看见……但这样也不行，不然去跟警察通报一下好了。</p><p>正当我轻手轻脚准备离开这里时——</p><p>「在那家伙混进去的队伍中，那个有着娃娃脸的女人是叫琳恩对吧？」</p><p>他刚刚说了什么？如果我没有听错，那他应该是讲了琳恩的名字？</p><p>「是啊，那个长得很可爱的女人名叫琳恩。所属的队伍成员为两男一女，听说是因为少了一名队员，所以简简单单就接受他加入了。」</p><p>「多亏那家伙长得一副漤好人的模样，能简单博得对方信任实在太轻松了。男人们只要迷昏后剥光就好。对男人就算再粗暴也无妨，但是对待女性时就要温柔点，绝不能让她哭。如此的娃娃脸可是很珍贵的。」</p><p>「如果能再年轻一点就好了，不过外表看起来比实际年龄幼小这点分数很高呢。」</p><p>「要是连肉体都很稚嫩自然很棒，但也不该奢求太多。是说那种明明活了好几百年，肉体却依然是萝莉的发展，最对我胃口了。」</p><p>「萝莉老太婆吗？这我就难以理解了。果然年幼的精神跟稚嫩的肉体共存才能算是真正的萝莉吧？」</p><p>「就是因为这样你的地位才会一直爬不上去啦。看来萝莉这个词的定义已经定型化了，你的内心应该要更宽容地去接受各种萝莉才行啊，有没有听过反差萌这个词？」</p><p>「反差萌……这个迅速渗透我的心灵，听起来无比甘美的词汇究竟是什么？」</p><p>虽然后半的对话我大多都没听清楚，不过他们明明是在讨论绑架这种严重的事情……是不是有些奇怪啊？</p><p>该说他们是在夸奖琳恩吗，我甚至多少觉得这群人温柔得不像是罪犯呢。</p><p>「如果不是老客户提出的委托，我还真不想把人交出去呢，毕竟没钱什么都不能做。」</p><p>「的确是这样呢，头目。至少在交给贵族之前，我们要好好对待目标，这就等同于是我们的使命。是不是差不多该前往约好的地点了啊？虽然其他同伙已经先出发，但我们还需要做好偷袭的准备。」</p><p>这下就确定……我放过他们的理由消失了。</p><p>泰勒他们也是笨蛋。明明我平常就不断跟他们说了，看起来很善良的人都不能信任。</p><p>虽然他们的谈话中有一些我无法理解的内容，不过可以确定他们就是绑架犯。由于关系到我伙伴的安危，所以不需要手下留情。</p><p>「的确，可不能迟到。」</p><p>「喂，等一下。」</p><p>当被称为头目的男人在听见我的呼喊回过头后，我立刻迎面给了他一拳。</p><p>接着趁另一个人还没反应过来发生什么事时，对准他的胯下踹了上去。</p><p>「唔咕！」</p><p>所谓的偷袭就是这么回事啊。</p><p>好啦，口吐白沫的那个家伙可以先不管，得把倒在地上的头目绑起来才行。既然手边没有绳子，就拿喽啰的腰带来用吧。</p><p>很好，这样他就无法逃跑了。如果要绑我还是比较想绑女人啊……先不讲这个，还是赶紧打听一下详细情形吧。</p><p>「快给我起来。喂。」</p><p>「咳噗！」我朝倒在地上的头目的肚子轻轻一踢，他就像是要把腹部空气全吐出来般咳了起来。</p><p>「醒来的感觉如何？」</p><p>「你做了什么！……你到底在做什么？」</p><p>「看不出来吗？我正在搜刮应该可以换钱的东西啊。」</p><p>毕竟是喽啰，钱包里没什么钱。其他比较值钱的看来就只有一把短刀。啧，实在有够穷耶。对了，干脆把衣服也剥下来卖掉吧。</p><p>「竟然连衣服都抢……太过分了。」</p><p>那个头目似乎在碎念着什么，不过就无视吧，无视。</p><p>想要的东西都拿到手了，接下来就把倒在暗巷地上的玻璃瓶打碎吧。</p><p>哎呀，鞋子也脱掉好了。这么一来就算不小心让人逃走，我也能立刻追上他。前提是这家伙有勇气光着脚在碎玻璃上跑步啦。</p><p>「你们也多存一点钱吧，竟然这么穷……不对，把你们刚刚讨论的事交代清楚。」</p><p>「刚刚讨论的事？我听不懂你在说什么。而且你为什么要问这种事？这跟你无关吧？」</p><p>装什么傻啊，真是有够麻烦。</p><p>我多得是能让你开口的方法，但现在时间有限就快点解决吧。</p><p>「你们打算设计陷害的目标，很可惜的似乎正是我的队伍成员，这么一来我怎么可能视而不见呢。」</p><p>「不是关于萝莉的讨论，而是另一件事吗！」</p><p>头目的脸色瞬间大变，他大概只把我当成是充满正义感的冒险者吧。一般来说，的确不会觉得这个突然冒出来的家伙跟目标有关系呢。</p><p>「好啦，快回答我的问题。要是你敢说谎或是有所隐瞒……」</p><p>「哼，难不成你想说就算要动手也会让我开口回答吗？冒险者大人，你总不会用暴力对待无法抵抗的人吧？」</p><p>「我怎么可能做出那么野蛮的事呢？我想想啊……就让你跟自己全裸的手下愉悦地玩玩吧。」</p><p>「咦？」</p><p>我的发言似乎出乎那家伙的意料，只见他傻傻地张大了嘴巴一脸呆滞。</p><p>「首先就让你跟那个昏过去的家伙来个热烈的接吻吧，然后再让那个家伙张开大腿，把你的脸埋进他的胯下好了。」</p><p>「喂，住手！你、你是在开玩笑吧？」</p><p>「这究竟是玩笑还是会变成现实，就要看你的回答了。」</p><p>不使用暴力，而是温柔地靠交涉来和平解决。</p><p>我脸上堆满了笑容，慢慢朝全裸的喽啰走去。</p><p>当我将喽啰的身体从后方拉起拖过去后，便与眼角含泪勐力摇头地望着这里的头目四目相接了。</p><h3 id="_3-4" tabindex="-1"><a class="header-anchor" href="#_3-4"><span>3</span></a></h3><p>「暖呼呼的那个……暖呼呼的那个……」</p><p>「这家伙相当顽强耶，虽然还是在那阶段让他屈服了。」</p><p>作为他把一切消息都讲出来的谢礼，我将头目跟全裸的喽啰绑在一起。</p><p>希望他不会因此觉醒奇怪的兴趣。</p><p>话说回来，有绑架集团混进阿克塞尔啊。这里是归我管的城镇，我可不打算让外人在这里出头。</p><p>「不过我还真是失手了。」</p><p>头目不清楚会合的地点，就只有那个被踢了男人重要部位的喽啰知道。但是这家伙彻底失去意识，无论我做什么都弄不醒他。</p><p>不过我还是有别的方法能得知这些家伙要去哪里。</p><p>走在路上时突然想到梦魔店就在附近，虽然要绕点路不过我还是去了一趟。即使距离约好的时间还有好一阵子，我仍毫不客气地打开大门。</p><p>「不好意思，今天临时公休……咦？达斯特先生，怎么了吗？我们还没有开始准备耶。」</p><p>整间店内只有我已经看腻的萝莉梦魔。</p><p>「你也无所谓啦。快去通知警察，暗巷有两个被绑住的男人热烈地交缠在一起，那是先前袭击达克妮丝的集团。我现在很忙，后续就麻烦你了。」</p><p>「咦？那是达斯特先生的功劳吧！发生什么事了？如果是平常的达斯特先生，应该会去找警察语带讽刺地自傲一番啊？」</p><p>「我现在没时间，拜托你了！」</p><p>「等、等等，请把详情……」</p><p>没等萝莉梦魔回应，我就动身前往下一个目的地。</p><p>得去公会询问伙伴们前往的地点才行。</p><p>我尽全力跑过熟悉的道路，也没时间调整呼吸就冲进公会。</p><p>就这样直接跑去找站在柜台前面的露娜。</p>`,519),e(f,{src:`/images/E1/07.avif`,alt:`插图`,width:`845`,height:`1200`}),s[14]||=a(`<p>「达斯特先生，你回来得还真快呢。找到能陪你一起接委托的队友了吗？」</p><p>「现在不是做这种事的时候，快告诉我琳恩他们接了什么任务！」</p><p>我没有时间在这边闲聊了。如果不快点问出地点并追上去，很可能就来不及了。</p><p>「发、发生什么事了？请你稍微冷静一点。」</p><p>「别问了，快点告诉我！」</p><p>「呃，关于这点，那个……琳恩小姐他们有吩咐我不可以告诉你，说是『达斯特很可能因为嫉妒跑来捣乱，所以别跟他说我们的目的地』。」</p><p>「那个笨蛋！就只会把脑袋花在这种多余的事情上面。现在状况紧急，拜托你！」</p><p>虽然我双手合十低头拜托，但露娜只是有些慌张，依然不打算开口。</p><p>毕竟对公会来说信用第一，作为公会招牌的柜台小姐露娜会守口如瓶也很正常。然而现在的状况不是坚持这种事的时候。</p><p>看来我只能把一切都说出来了。</p><p>「请详细告诉我理由，不然我绝对不会告诉你。」</p><p>「其实……不是有个家伙跟他们组队吗？那个人其实是潜入这座城镇的犯罪集团成员。」</p><p>「看来……你不是在开玩笑呢。请告诉我详情。」</p><p>看着我认真的眼神，露娜也冷静下来紧盯着我。</p><p>总是与众多冒险者打过交道的人，一瞬间就看出我非常认真。</p><p>「稍等一下，关于这件事我也很有兴趣。」</p><p>瑟娜不知为何突然出现在柜台的另一侧，只见她伸手推了一下眼镜后开口插话。</p><p>「为什么瑟娜会在这里？」</p><p>「我只是有点事情要找露娜商量而已，不用在意。你口中的犯罪集团难道是……」</p><p>「啊，之前也有提过吧，在那间店的时候。」</p><p>「是那个时候……」</p><p>她的脸颊有点红呢，看来是想起自己在梦魔店时的打扮了呢。</p><p>平常的话肯定要好好捉弄一番，但是今天就饶过她吧。</p><p>顺便提一下那两个被绑起来的家伙好了。这样正好，有瑟娜在这件事也会比较有说服力。</p><p>「话虽如此，这不是能在这里谈论的内容。露娜，跟你借一间后面的房间。」</p><p>「好的，没问题，我也会加入讨论。」</p><p>正当我催着露娜起身准备走去后面时，背后突然传来一道声音叫着我的名字。</p><p>「啊，终于找到了！真是的，达斯特先生。你只说暗巷我怎么会知道人在哪里呢？要把详细地点告诉我才行啊。」</p><p>我一回过头，就看到皱着眉头一脸愤怒的萝莉梦魔站在那里。</p><h3 id="_4-4" tabindex="-1"><a class="header-anchor" href="#_4-4"><span>4</span></a></h3><p>「换句话说，先前打算绑架达克妮丝的集团，这次欺骗了达斯特先生的伙伴加入队伍当中，打算在埋伏好的地点袭击他们，等抢夺完值钱的物品后，就绑架琳恩小姐交给某个贵族。这可是贩卖人口呢……」</p><p>听完我的说明后，瑟娜开口做出总结。</p><p>在这个本来用来与委托人商谈的狭小房间中，挤了我、瑟娜、露娜以及不知为何跟进来的萝莉梦魔。</p><p>「若是这样那就另当别论。我知道了，我就把他们的目的地告诉你吧。我们收到委托，希望能派人讨伐基尔地下城附近的哥布林集团，该地点距离阿克塞尔徒步约半天左右。」</p><p>基尔地下城是那个新人冒险者经常用来练习探索迷宫的地点吧，我也有去过那里。</p><p>记得从城镇往山的方向走上半天，之后就只能入山循兽径前进，不然无法抵达。</p><p>「如果中午过后才出发，到那边天都黑了。晚上爬山实在太过无谋，这么一来，就会露宿等早上才会动手讨伐吧。」</p><p>「没错，这可以说是冒险者的常识。手册上也是这样指导喔。」</p><p>露娜说的手册就是放在公会中，用来指导初学者的冒险说明书。里面详细记载了给初学者的建议及说明。</p><p>虽然是作为冒险者都至少该阅读过一次的东西，但我没有印象自己有看过。</p><p>「这么一来，深夜时刻最适合偷袭达斯特先生的伙伴们，只要趁混进去的人负责守夜时下手……」</p><p>「就能轻而易举完成工作吧。」</p><p>我帮语塞的瑟娜说完最后一句。这个推理应该没错，如果我是那群人肯定会这么做。</p><p>「他们已经出发好一段时间了，即使急急忙忙追上去也不一定来得及。」</p><p>「而且根据我接到的报告，对方至少有十人以上。一个人过去太鲁莽了。」</p><p>这种事不用瑟娜讲我也知道。而且他们之中很可能至少有一名高手，就是在达克妮丝绑架未遂事件时感受到的那股视线。从我的经验判断，拿够放出那种杀气的家伙肯定很危险。</p><p>这么一来，只能赊帐雇用冒险者了。毕竟是紧急状况，公会应该也愿意帮忙吧。</p><p>「露娜。现在有正在找工作的队伍吗？」</p><p>「关于这点，靠奖金度过一个冬天后几乎所有人都很缺钱，所以大多都去冒险了……」</p><p>「这也未免太糟了。不过总会有人没出门吧？应该还是能找到几个闲人？」</p><p>「虽然等傍晚工作结束后，大家就会聚集在公会……」</p><p>但是等到那个时候肯定就来不及了。</p><p>我刚刚有稍微环视过整个公会，偏偏在这种时候悠悠却不在。明明她就只有作为魔法师的实力货真价实啊。</p><p>「警察这边也不能因为不确定的情报就调动人手，抱歉了。」</p><p>瑟娜低头道歉，这女人未免太有礼貌了。由于头目一直保持缄默，所以唯一的证据只有我的证词。加上我毕竟常常受到警察照顾，就算瑟娜愿意相信，其他人也不会相信吧。</p><p>「没办法了，我就独自追上去吧。只要能在对方袭击前跟他们会合，应该还是可以顺利解决吧。不过这么一来，就需要移动手段了，最好是马匹或马车啦。」</p><p>事到如今如果徒步去追，就算再怎么挣扎也来不及。</p><p>而且那里不在共乘马车的路线上……最糟糕的情况下，就算得动手偷马也要追上去。事到如今，就算再追加一两项罪状也无所谓了。</p><p>「请稍等一下，关于这件事我有一个办法。」</p><p>一直保持沉默的萝莉梦魔突然拍了手，接着用力点头。</p><p>讲到梦魔认识的人，难道她要找上级恶魔来帮忙吗？</p><p>该不会是指巴尼尔老大？老大是看心情做事，如果是同为恶魔的梦魔开口拜托，可能会比较有用，这时候就麻烦她或许会比较好。</p><p>找巴尼尔老大帮忙虽然有些不安，但现在不是计较手段的时候了，就让我把可以利用的事物都拿来用吧。</p><p>「啥？为什么是这个家伙啊？」</p><p>讲好在阿克塞尔的正门会合后，我就急忙到杂货店及魔道具店收集旅途所需的东西，然后全都装进背袋当中再赶过去，不过为什么是这家伙来帮忙啊？</p><p>绕去魔道具店时，我有看到萝莉梦魔在跟巴尼尔老大交谈，本来还以为她是在拜托老大同行，结果却并非如此。</p><p>「好久不见了，达斯特先生。」</p><p>我对这个隔着头盔的模煳声音有印象。</p><p>不如说这个头盔给我留下了深刻的印象。对方正是在面对测谎用魔道具时，受了他不少照顾的那个头盔男。</p><p>「那个，我需要的是能充当战力的帮手，可没有要找贵族少爷喔。」</p><p>「不用担心。为了成为一名优秀的骑士，我从小就有持续锻鍊，所以对自己的枪术还算有自信。」</p><p>看他轻快递挥动手中长枪的动作，感觉相当有模有样。</p><p>长枪啊，身为贵族还擅长使枪是吗……</p><p>「达斯特先生，怎么了吗？」</p><p>喔喔，不要靠那么近盯着我看。</p><p>虽然你毫无性感魅力可言，但我还是会被吓一跳耶。</p><p>「没事，现在多一个战力是一个。」</p><p>如果真有个万一，就曝光头盔男的贵族身分给敌人知道吧，毕竟对方的目的是绑架人质，这么一来他至少可以得救。</p><p>「我在跟头盔先生告知达斯特先生遇上危机后，他就立刻答应要与你同行喔。不止如此，还迅速帮忙准备了马匹。」</p><p>「那两匹马原来是这样来的喔。」</p><p>不仅毛色很有光泽，肌肉也非常匀称，而且个性似乎很温驯。看来培育得相当不错，不愧是贵族大人。</p><p>「这两匹都是我家饲养的马。达斯特先生，你会骑马吗？不会的话也能坐在我后面……」</p><p>「哎，只是骑个马没问题啦。」</p><p>虽然真的很久没骑马了，不过身体还记得。</p><p>「话说回来，真亏你能联络到这个家伙呢。你是知道他住在哪里吗？」</p><p>「啊，这个……只是头盔先生偶然来到附近，所以我立刻就找到他了。」</p><p>「只是偶然。」</p><p>如果真是偶然，为什么这两个家伙要移开视线啊？</p><p>是做了什么不可告人的事情吗？话说回来，明明身为贵族却经常光顾梦魔店呢。不过也有可能是这家伙准备偷窥女澡堂时，正好被萝莉梦魔撞见。</p><p>「好啦，总之我会帮你保密。」</p><p>我同情地拍了拍头盔男的肩膀后，立刻感觉到有奇怪的视线从头盔中传来。</p><p>他喘着粗气这点也是跟之前一样。</p><p>「是，我也会努力不被发现！」</p><p>「喔、喔喔。」</p><p>这人对偷窥也未免太过执着了。还有别因为受到鼓励就兴奋地把脸靠过来，喘着粗气的声音实在有够吵。</p><p>「喂，你为什么用那种表情看我啊？」</p><p>萝莉梦魔看着我们，一边说着「这下糟了」一边伸手扶着额头。</p><p>是因为我说了会助长犯罪行为的话吗？偷窥这种事是男人的嗜好吧……不过如果在警察面前这样讲，可能立刻就会被关进牢里。</p><p>「好了，废话就到此为止。可以出发了吧？」</p><p>「随时都可以。」</p><p>这回答真棒，听起来干劲十足呢。</p><p>我一跨上马鞍，头盔男也立刻上马。</p><p>「那么，希望两位常客可以平安归来。」</p><p>打算目送我们离开的萝莉梦魔正对着马上的我们挥手。</p><p>竟然刻意用常客这个词汇，还真是会做生意。</p><p>「嗯？你也跟我们一起去啊。」</p><p>我边说边抓住萝莉梦魔的手，没等她回答就将她拉上马。</p><p>「咦？我也一起……为什么啊啊啊啊啊啊啊啊！」</p><p>毕竟那群人似乎很喜欢年幼外表的女孩子，你肯定非常适合当诱饵吧。</p><h3 id="_5-4" tabindex="-1"><a class="header-anchor" href="#_5-4"><span>5</span></a></h3><p>「风吹起来好舒服喔。啊，远处有一只可爱的小鸟！」</p><p>萝莉梦魔坐在马背上雀跃地看着风景。</p><p>一开始还很不情愿，现在心情又变得很好呢。</p><p>「那个头上长了角的兔子好可爱喔！走路的样子也很可爱！真想在店里养一只。」</p><p>「那是一角兔呢，那家伙的手段就是靠这种可爱的动作吸引人，等你毫无防备靠过去就用角捅死你。」</p><p>「咦……」</p><p>那个毕竟也是魔物啊，附带一提还是肉食性。</p><p>这时我因为感受到视线回过头去，接着就与跟在后方的头盔男四目交接……应该吧。虽然我看不到他藏在头盔里的脸，但是他的视线却让我背嵴发凉。</p><p>还真亏他这次愿意帮忙呢。虽然事到如今才讲这个也很怪，但是一般而言应该不会愿意把马匹借给只是在梦魔店认识的点头之交，甚至亲自出马帮忙讨伐罪犯。</p><p>从初次见面时就一直感受到的那股视线也一样，究竟是有什么样的理由呢？</p><p>仔细回想至今为止的事情……啊，原来如此！真是的，我完全没有注意到呢。头盔男的目标原来是萝莉梦魔！因为我经常跟这家伙在一起，所以他在嫉妒吗？</p><p>这次会愿意帮忙，也是因为开口拜托的是他所喜欢的萝莉梦魔——只要这么想就说得通。</p><p>这么说来，他在店里时也没有看向其他梦魔，而是一直盯着我这边，也就是萝莉梦魔所在的地方看。原来如此，我完全想通了。</p><p>「再怎么样也是梦魔啊。」</p><p>「咦？达斯特先生，你刚才说了什么吗？」</p><p>明明声音或身材都还只是个小鬼，虽然我不打算对别人的喜好说三道四，不过这家伙到底哪里好了？</p><p>「那个，一直被盯着看我也是会害羞的喔。」</p><p>在店里的打扮明明总是近乎半裸，真搞不懂她在害羞什么。</p><p>而且现在的服装几乎没有裸露出肌肤，这家伙的基准实在难以理解。</p><p>「达斯特先生，我们没有走错方向吧？」</p><p>头盔男来到我旁边并行开口问道。</p><p>他果然因为我正在与萝莉梦魔聊天感到嫉妒，所以过来碍事了。</p><p>反应会这么大是因为我跟萝莉梦魔看起来感情很好的关系吧，这家伙果然迷上她了。</p><p>毕竟上次跟这次都深受你的照顾，我就来帮你一把吧。</p><p>「维持原路就行了。哎呀，我这匹马因为载着两个人似乎有些疲惫了，可以让这家伙坐过去你那边吗？」</p><p>「我才没有那么重呢！」</p><p>女人只要讲到岁数跟体重的话题就会出现敏感的反应，实在有够麻烦耶。</p><p>这也是为了实现你重要的常客，也就是头盔男的愿望，不要反应过度，好好帮忙啦。</p><p>「让她坐过来吗……真要讲起来，我比较希望是达斯特先生……」</p><p>「啊？你说什么？我没有听清楚耶。」</p><p>由于风声让我没有听清楚他的回答，但是感觉他不大有兴趣呢。我原本以为他会很高兴，是因为太害羞所以正在犹豫吗？</p><p>从今天起，我就为他们多留心一下吧，只要跟钱无关我都愿意帮忙。而且如果顺利撮合，他们说不定还会请我喝酒以表谢意呢。</p><p>「我感受到充满欲望的眼神了……」</p><p>「别在意。」</p><p>「虽然感觉很色，不过并非是在对我发情……」</p><p>「别在意。」</p><p>这家伙为什么一脸不悦啊？</p><p>而且另一名同行者头盔男的视线一直固定在我身上，实在太恐怖了。他的视线连一瞬间都没有移动过。</p><p>虽然现场的气氛不太妙，不过只要维持这个速度，再过几个小时就能追上。</p><p>如果知道敌方的埋伏地点就省事多了，但是那个喽啰一直无法开口。</p><p>我踹下去时如果有手下留情就好了。就算真的破掉，应该也能靠「Heal」治疗吧……真的有必要我还是能帮忙出治疗费啦。</p><p>「现在最优先的事情是跟达斯特先生的伙伴会合对吧，不过如果在途中先遇上犯罪集团，那我们该怎么办才好？」</p><p>「喂喂，不要讲这种话啦，这可是所谓的插旗喔。虽然我也是从和真那边听说，不过这种话只要一说出口就会成真喔。」</p><p>「怎么可能会有这种事呢，如果真是这样，那我们不就会偶然在这里遇上那群罪犯吗？不可能啦，哈哈哈。」</p><p>我不清楚萝莉梦魔究竟觉得哪里有趣，只见她露出天真无邪的笑容。</p><p>接着因为我们看起来聊得很开心，头盔男的视线跟着锐利起来……这到底是什么状况？</p><p>「不过对方的确有可能跟我们走在同一条路上。」</p><p>头盔男也真爱操心，这根本是杞人忧天吧。即使对方有发现我们，但是他们接下来准备袭击我的队友，根本没有空攻击我们吧。</p><p>「话虽如此，但是不用担心啦。那群人不可能毫无计划性就袭击我们，毕竟他们至今好歹也是在执行计划性犯罪喔，不可能跟山贼一样随机袭击。除非那群人是超级大笨蛋。」</p><p>「达斯特先生，你这不就是在插旗吗……」</p><p>还真会讲啊。不过算了，这种事情根本不可能发生啦。</p><p>「两位，看来真的不能小看这个插旗的效果呢。前方有一群人冲出来了。」</p><p>「喂喂，也太刚好了吧。」</p><p>这群人出现的时机好到让我忍不住怀疑，他们是不是事先说好要演这场戏了。</p><p>对方总共七名男性，而且绝非正派人士。虽然看上去很像冒险者，但是浑身充满煞气。从全员手上都握着武器来看，他们似乎不打算进行交涉。</p><p>那道充满杀气的视线似乎不在，但是对方人数有点多，难以收十掉他们。对方似乎没有马匹，不然直接策马冲过去好了？这也不行，有两个人握着弓箭。</p><p>「你们不要开口，只要配合我演戏就好。」</p><p>听到我这么说之后，两人虽然惊讶仍点头同意。</p><p>就让你们见识一下我那足以传遍大街小巷，超一流的鬼点子吧。</p><p>「喂，你们就是头目说的同伴吧？」</p><p>我在对方发动攻击前，就先用亲切的语气搭话，同时边挥手边靠过去。</p><p>「不要攻击我们，是头目雇用我要我带这孩子过来啦。大家不是在收集萝莉长相的女孩吗？」</p><p>我拍了拍外表无论怎么看，都像是年幼村女的萝莉梦魔的头。</p><p>光是这么一个动作，萝莉梦魔似乎就已经理解我要做什么，她立刻就装出害怕的模样。</p><p>「啊、呜……请让我回家……」</p><p>她的演技还是一样逼真呢。这个不知所措苦苦哀求的表情真是太棒了，带她过来果然是正确的选择。</p><p>「等等，所以你们是想加入我们吗？」</p><p>拉近距离后我就放慢马匹的速度，缓缓朝放松警戒的罪犯们靠近。</p><p>「没错。我是在阿克塞尔干小混混勾当时被头目看上。由于我会骑马，头目就命令我来通知大家他会晚点过来。所以说，这个女孩就是给大家的见面礼。」</p><p>「哦～～挺机灵的嘛。一旦袭击了冒险者就无法再待在这座城镇了。萝莉能增加当然是件好事……但是新来的，你太不成体统了！」</p><p>干嘛突然那么激动？难道是看穿我要加入他们这点其实是在说谎吗？虽然我伸手握住剑柄，不过面对这个人数差距实在是压倒性不利。</p><p>「那孩子不是在哭吗！小妹妹，不用害怕，已经没事了。喂，快点把甜点拿来！」</p><p>「是！」</p><p>「「「咦？」」」</p><p>他们出乎意料的应对，让我们发出傻呼呼的回应。</p><p>领队温柔地安慰起萝莉梦魔，其他人则是俐落地准备好折叠椅以及桌子，接着在桌面摆上各式各样的甜点。</p><p>椅子上不但放了软绵绵的坐埝，桌面上甚至还装饰了花朵。</p><p>「好了好了。请坐来这边。」</p><p>「呃，好。」</p><p>虽然萝莉梦魔用眼神向我求救，但我也不知道该如何是好。</p><p>看到我总之先点头，她就心不甘情不愿地下马坐到椅子上。</p><p>望着眼前刚泡好的红茶和点心的组合，萝莉梦魔似乎相当困惑。</p><p>这群一脸凶恶的家伙没有触碰萝莉梦魔，而是保持一定的距离尽心照顾她。</p><p>「味道如何？」</p><p>「非常好吃，嗯。」</p><p>萝莉梦魔胆怯地回答了那个脸上堆满了笑容的男人。</p><p>听到她的回答后，两个男人不知为何高兴地相互击掌。</p><p>「有磨练自己制作甜点的技术真是太好了……我就是为了这一刻活着啊！」</p><p>「太好了！至今为此的辛劳都得到回报了！」</p><p>只见泪流满面的两人互相拍了拍肩膀，其他人也是一脸感动……这是怎样？</p><p>这些看起来很好吃的点心是这家伙做的吗……那个无论是身材或长相都跟熊一样的大叔竟费工做出点心？</p><p>所有人一脸满足地点点头，接着在桌子旁边排成一列。</p><p>看他们全都挺直了腰杆，似乎正打算做些什么，这时候千万不能放松警戒。</p><p>虽然是个诡异的团体，但毕竟是犯罪集团，绝对不能大意。</p><p>「团内规则，第一条！再怎么深爱萝莉，也绝对不能出手！」</p><p>「「「「再怎么深爱萝莉，也绝对不能出手！」」」」</p><p>这群人突然开始复诵起其中一名男人说出的宣言。</p><p>「第二条！绝对不能对萝莉抱持性欲！」</p><p>「「「「绝对不能对萝莉抱持性欲！」」」」</p><p>啊，这些家伙是萝莉控啊。</p><p>他们是货真价实的危险人物。</p><p>萝莉梦魔也开始坐立难安了。由于那家伙的外表看起来相当年幼，应该正中这群人的好球带吧。</p><p>即使这群人的脑袋有问题，还是有着人数差距。这时候先配合他们再找机会逃走比较稳当。</p><p>我原本打算趁他们大意动手偷袭，不过这群人虽然蠢话连篇却有货真价实的战力。从走路时重心的移动及身体的摆动来看，就能确定他们全都是练家子。</p><p>「那个，我们边吃饭边讨论详细情形吧。晚上有重要的工作要做，虽然时间还有点早，但是不快点吃饭然后追上去……」</p><p>「团内规则第十三条！这么说也是……话说回来，我们是不是在哪见过？」</p><p>能够中断他的宣言当然是好事，偏偏这家伙又开始提起奇怪的事。</p><p>他们其中一个家伙也盯着我的脸皱起眉头。</p><p>「真巧。我也觉得似乎有见过这个他。」</p><p>接着又有三个人做出相同的反应。这些家伙是在达克妮丝绑架未遂事件中，跟我打过照面的那几个人吗？虽然我已经印象模煳了，不过似乎就是这几个声音啊。</p><p>啊，这下糟糕。等这几个家伙回想起来我们就完蛋了。</p><p>……现在只能努力装傻蒙混过去。</p><p>「应该是错觉吧？跟我长相类似的男人根本满街都是啊，老大。」</p><p>「我记得那头暗沉的金发是……呜咕！」</p><p>这个即将发现我真实身分的男人，突然被枪柄打中头部并倒在地上。</p><p>不用确认我也知道究竟是谁出手，当然是那个头盔男！</p><p>趁着这群人还没反应过来时，他又从马上打倒了另一个家伙。虽然他的实力确实不错，不过敌人看来也不是省油的灯，第三个人勉强接下了他的枪尖。</p><p>「你这家伙在做什么！」</p><p>我飞身下马挥剑砍向旁边的两名男人，却被他们在千钧一发之际躲过。</p><p>「同伙的说词原来是在骗我们！干掉他们！啊，千万不要伤害萝莉啊！」</p><p>「那当然！」</p><p>所有敌人都退开一步并架好武器。敌方减少两人剩下五人，我方虽然有三个人，不过有一个人不成战力，就这样继续战斗实在太过不利，这么一来能采取的行动就只有那个了。</p><p>「好了，我们撤退！要全速逃跑了！快过来！」</p><p>我重新乘上马，接着伸手抓住萝莉梦魔，一口气将她拉上来。</p><p>「萝莉强盗！」</p><p>「别把人讲得那么难听！」</p><p>虽然有一名男人边喊出奇怪的话边提枪打算刺我，但是萝莉梦魔挡着让他无法顺利攻击。</p><p>我们趁机策马逃离现场，头盔男也跟在后面。</p><p>那群人虽然连忙举起弓箭，但是非常遗憾。</p><p>「可恶，弓弦被砍断了！」</p><p>「我的也是！」</p><p>我刚刚挥剑的目标从一开始就不是你们，而是那两柄弓啊。</p><p>哼，在欺骗对手和逃跑这两件事上，我可不会输给任何人！</p><p>「掰掰！虽然我们不会再见了，不过你们好自为之吧！」</p><p>「给我回来！至少把萝莉放下再走啊啊啊啊啊！」</p><p>虽然能听见败家犬的叫声，不过我决定无视直接逃走。</p><p>拉开一定的距离后，我才放慢速度跟头盔男并肩而行。</p><p>「很好，总算是顺利逃掉了。」</p><p>「竟然连坏人都能骗倒，达斯特先生的手腕真是高超。」</p><p>「骗人的本领真的是超一流呢！」</p><p>「对吧。由本大爷亲自出手就是这么简单啦。」</p><p>那群人的移动速度会随着看是要丢下被打倒的两人继续行动，还是等他们恢复，而有所不同。无论结果如何，只要我们继续骑马前进就肯定不会被追上。</p><p>「接下来就直接去找达斯特先生的伙伴吧？」</p><p>「啥？你在说什么？现在当然是要布下陷阱，准备偷袭刚刚的犯罪集团啊。」</p><p>「咦？」</p><p>不需要惊讶到说不出话来吧？由于看不到头盔男的表情，所以我不清楚他究竟做何反应。</p><p>「不要一脸呆样啦。现在已经知道我们有着对方没有的高机动力，所以没有必要慌张了。虽然继续前进也行，但如果无法顺利找到伙伴，那就只是在浪费时间，这样反而比较困扰。为了问出敌人预定埋伏的地点，在这边打倒他们会比较快。」</p><p>「虽然是这样没错。不过我们才刚从他们手中逃走耶。」</p><p>「正因为如此，他们不会认为刚刚才逃走的人会埋伏偷袭自己。加上他们正拼命从后面追赶我们，注意力肯定相当涣散，即使是再简单的陷阱也无法看穿啦。」</p><p>要是我们先会合了，他们的计划就会完全泡汤，因此那群家伙现在应该满着急的吧。要是他们就此逃走也无所谓就是了。</p><p>「不过设置陷阱所需的道具该怎么办？」</p><p>「这里有着丰富的大自然资源。而且对冒险者来说，情报和事前准备都不可或缺，如果无法正面进攻，那就动脑设陷阱让敌人上钩。在我带来的这个背袋中就有许多好用的东西。」</p><p>「达斯特先生……你要不要转职去当盗贼？」</p><p>「我拒绝。别说废话了，快点开始动手。没剩多少时间了，动起来，快工作！」</p><p>「竟然被达斯特先生要求工作，我觉得有点受到侮辱。」</p><p>这是什么意思啊！如果有空讲废话，不如跟头盔男好好学习。</p><p>他已经把马拴在安全的地方，等着我下达指示了。如果这次进展顺利，我一定会积极促进他跟萝莉梦魔的感情。</p><p>「好了，快点开始动作！」</p><h3 id="_6-3" tabindex="-1"><a class="header-anchor" href="#_6-3"><span>6</span></a></h3><p>陷阱设置完毕，也准备了完美的作战计划。</p><p>分配好每个人要负责的事情后，就只要等待那群人现身了。</p><p>虽然是群让人恨不起来的家伙，不过依然是未遂及现在进行式的绑架犯。而且还说过要把目标交给某个贵族。</p><p>无论理由为何，我都不会原谅那群打算伤害我伙伴的家伙。</p><p>我们埋伏的地点是通往基尔地下城的兽径前方。是个勉强算是道路存在的地点。</p><p>这段上坡路段的宽度最多只能让两名男人并行。道路两旁是陡峭的斜面，而且还长着高达膝盖的杂草。</p><p>我们可以说握有地利。</p><p>这时远方传来许多人的脚步声，而且声音逐渐变大变清晰。</p><p>我趴在路旁的杂草堆中观察敌人的模样，就发现七个男人满身大汗往这边走来。</p><p>这里没有岔路，他们也没有在长满杂草的斜坡上前进的理由。很好很好，目前为止都跟我的计划一样。</p><p>「动作快！如果这次失败，没人知道头目会怎么处罚我们。我的秘密收藏甚至有可能会被悉数夺走！」</p><p>「如果我的爱丽丝大人写真集被夺走，那我就没有活下去的希望了！」</p><p>「我也有几项收藏似乎被头目盯上了。可恶，这条路偏偏在我们急着赶路时特别难走！」</p><p>虽然他们似乎很焦急，不过那位头目目前正在享受牢狱生活呢。</p><p>正当他们开始爬坡时，浑身湿透的头盔男出现在众人前方。</p><p>他仿佛要堵住道路般站在那里，居高临下俯视着那群人。</p><p>「你是刚刚那个家伙！为了让我们剥光在这边等着真是勇气可嘉。剩下的两个人……喂，你在做什么！好痛！」</p><p>头盔男完全无视他们的怒骂，只是默默地用事先捡好，约手掌大小的石头朝他们扔去。</p><p>「喂，住手！你是小鬼吗！不要丢石头，很痛啊！真的要丢就给我换成刚才的萝莉来丢！少女拼命丢着石头的模样……感觉就很萌，呜啊！」</p><p>直接命中脸部啦，虽然没什么杀伤力不过还满痛的。如果打中的地方不对，骨头搞不好还会出现裂缝呢。</p><p>敌人密集站在狭窄的道路上，我方则从高处投掷石块攻击。加上敌人失去弓箭，也没有其他远程攻击的手段，这单方面进攻的景象甚至让人觉得有趣。</p><p>「哈哈哈哈，喂喂，这画面真是不错呢！」</p><p>从侧面的斜坡顶端俯视那群被石头砸中的家伙，我抱着肚子大笑起来。</p><p>虽然这也算是种挑衅，不过一半以上是因为我真心觉得有趣。</p><p>「竟然敢戏弄我们！」</p><p>「你们两个从侧面绕过去！你们想办法处理掉在那边狂笑的家伙！我从正面进攻！」</p><p>想靠斧头保护脸硬是冲上去吗。其中三人从我所在的右侧斜面，另外两个人则是想从左侧斜面爬上去啊。如果那里只是普通的坡道，倒也不是爬不上去啦……</p><p>「呜、哇啊啊啊！这是怎样？这里是刚刚下过雨吗？草上都是水根本站不稳！」</p><p>「咳噗！好痛，有东西绊倒我了！」</p><p>看着这群人不是滑倒，就是在抵达道路前被我用杂草编成的陷阱绊倒后，我更是笑到合不拢嘴。</p><p>「嘿嘿，孩子们没事吧？走得不错，走得不错喔。」</p><p>「别开玩笑了！虽然我喜欢小女孩，但绝不允许有人把我当成小女孩对待！」</p><p>情绪越是焦急，他们的脚步就越是不稳，只见这群人不断跌倒完全爬不上来。</p><p>哎呀，还是丢颗石头给正在爬另一侧斜面的家伙当礼物吧。</p><p>我扔出的石头漂亮地命中敌方的后脑杓，让他连同跟在后面的同伙一起磙了下去。</p><p>「算了，放弃侧面！所有人从正面突破，保护好脸部跟我一起冲上去！」</p><p>看来他们放弃斜坡决定从道路进攻了，一般来说这是最正确的选择。</p><p>毕竟区区石头只要靠防具就能抵挡，不过你们以为我达斯特大人没想过这招吗？</p><p>「聚集得很紧密嘛，拜托你喽！」</p><p>「了解～～」</p><p>萝莉梦魔回应我的信号，从埋伏的树上飞了出来。</p><p>不是村女的模样，而是以很暴露的打扮拍动背上的蝙蝠翅膀，整个人漂浮在空中。</p><p>「什么？那名少女是天使吗！」</p><p>不，那对翅膀怎么看都是恶魔吧。</p><p>萝莉梦魔在飞到吃了一惊的那群家伙的正上方后，就将原本小心翼翼抱在怀里的那颗封印着雷击的魔道具球用双手从两侧抓住。</p><p>「那么，雷击发动！」</p><p>握在她手中球体朝正下方落下雷击，在击中一个人之后，迅速透过湿透的地面四处蔓延，将那群人一网打尽。</p><p>这个道具的威力比想像中还强呢，都可以闻到焦味了，他们应该没死吧？</p><p>「这个魔道具好厉害喔！」</p><p>虽然从天空降落的萝莉梦魔一脸意犹未尽，不过能做到这点全因为她是可以自力飞行的恶魔，对人类来说那个道具就只是缺陷品。</p><p>「那个让地面积水的魔道具也是相当厉害，虽然我因为怕噪音太大出手破坏，结果就吃了苦头。」</p><p>这一带之所以会到处积水，是因为我们用了魔道具店的简易厕所。</p><p>因为噪音实在是太大，头盔男担心魔物会因此聚集而来便动手破坏，结果使得这一带全都积大水。这能算是不幸中的大幸吗……感觉不太一样。</p><p>「那么该拿这些家伙怎么办？」</p><p>「先剥光他们的防具和衣服绑在旁边的树干上，等跟琳恩他们会合后再想要怎么处理就行了。毕竟潜入队伍中的家伙还没解决，所以不要太大意。」</p><p>「说的也是，那就立刻把他们脱光吧。」</p><p>「好喔好喔，我也来帮忙。」</p><p>因为是梦魔，就算要脱男人衣服也毫无抵抗耶。</p><p>至于头盔男的手法可以说相当熟练呢，就只有在脱铠甲时费了一番功夫。</p><p>我也跟着动手帮忙，在几分钟内脱下所有人的装备及衣服，让他们靠着树干坐下，接着用绳子一圈一圈把所有人绑起来。</p><p>「时间花费的比想像中还多，天色已经开始变暗了，我们快点出发吧。」</p><p>我们重新骑上马，登上积水的坡道。</p><p>由于道路在中途转变成兽径，所以无法继续骑马前进，只能把马留在这里。</p><p>「能在这里等我们吗？如果我们一直没有回来，那就先回去吧。」</p><p>我默默地看着正在和马说话的头盔男。</p><p>虽然我不认为马可以完全理解人类的语言，不过较聪明的马匹可以理解某种程度的单字以及主人的心情。</p><p>久久骑一次马感觉也很不错呢。</p><p>「达斯特先生，你刚才露出了非常温柔的表情喔。」</p><p>「我明明一直都很温柔吧。」</p><p>「……是喔。」</p><p>「如果你有什么话想说，就看着我的眼睛讲啊。」</p><p>看到萝莉梦魔移开视线语气平板地回应我，于是我迈步朝她逼近。</p><p>不要在那边吹无声口哨想蒙混过去。</p><p>「让各位久等了，我们走吧。」</p><p>跟马匹讲完话的头盔男转身过来会合，我们便立刻踏上兽径前进。</p><p>虽然只有一个人应该不会做出什么莽撞的行为，但没人知道罪犯究竟在想什么。虽然刚刚那群人似乎很有理性，也不打算对琳恩出手，不过组织内总是会潜藏着一两个想法不同的人。</p><p>万一他做出伤害我的伙伴或琳恩的行为……我实在没有自信能够控制好自己。没事的，他们不会有事。</p><h3 id="_7-2" tabindex="-1"><a class="header-anchor" href="#_7-2"><span>7</span></a></h3><p>「哈！一群没大脑的家伙。哈哈哈哈！」</p><p>看着张大嘴巴熟睡的三个人，我满足地笑了出来。</p><p>看到新加入的伙伴硬是要负责守夜，这群漤好人竟然还反过来觉得不太好意思呢。</p><p>他们在把我叫醒后，竟然就毫无戒心地睡觉去了。</p><p>而我把特制的迷药粉末投入营火，让周围充满催眠效果后，这三个人就成了这副模样。</p><p>这可是相当强烈的迷药，无论周围有多吵闹，他们今晚都绝对不会醒来。</p><p>「距离会合时间还有两个小时左右啊。」</p><p>原本应该要再晚一点才会使用这种药粉，不过我今天刻意提早动手。</p><p>我的双眼紧盯着这个名叫琳恩的魔法师。</p><p>虽然不确定年龄，不过大概是十五岁前后吧。由于这张稚气未脱的脸蛋，肯定是能满足委托人的人才。</p><p>一般人都喜欢有着丰胸翘臀的女性，不过也有人比较喜欢平胸。</p><p>虽然很多人无法理解我们的癖好，但是我所属的团队是由喜欢年轻女性……而且是特别喜欢看起来会被称作少女的女性的人们所组成。</p><p>打从第一次见面，我就发现这个女人完全符合我的口味。虽然也有那种真的只喜欢幼女的人，不过对我来说这样才刚好。</p><p>「外表这么年幼，平常讲话的语气却相当强势这点也很棒。可以对这种女人为所欲为……咕噜，我的口水都快流出来了。」</p><p>虽然团内的规则是就算喜欢少女也不可以出手，但只要没被发现就不成问题。我就是为了这个报酬，才接下最麻烦的任务啊。</p><p>「首先要把斗篷脱掉。接下来该从下面，还是要从上面进攻呢？鞋子跟袜子则是一定要留下来。」</p><p>我对脱衣服的方式也有所坚持。比起全裸，留下一点衣服会更让人兴奋——这正是我的主张。所以先脱掉上衣留下胸罩吧。</p><p>接下来是脱掉裤子只留下内裤。没错，正是如此，就是这个啊！</p><p>尚未成熟的胸部与内裤的完美组合！再加上特别留下的鞋子，这样更能强调被虐性！</p><p>「真是太棒了！好了，那就让我好好享受这副身体吧。」</p><p>我仅伸出食指在女体上滑动。</p><p>这对只有微微隆起的胸部，充满弹性的水嫩肌肤……真是太棒了。好了，再让我享受更多吧。</p><p>如果刻意去抓取很难掌握的胸部，就能用整张手掌去感受那种触感。于是我闭上眼睛，将全身的神经集中到手上。</p><p>「咦？比我想像中还有丰满呢。咦？她的胸部有这么大吗？」</p><p>那是几乎无法一手掌握的强大弹力，难道她隐藏了一对巨乳吗？</p><p>虽然这样也不差，但说实话跟我所追求的东西不一样。外表跟实际相距甚远，这也是女性身体的奥妙之处。</p><p>我睁开双眼确认目前的情况，然而出现在眼前的却是——满脸通红的猪。</p><p>「啊啊啊啊啊啊啊啊啊！为什么会出现半兽人！」</p><p>我刚刚揉捏的不是琳恩的胸部，而是半兽人的胸部？</p><p>这究竟是怎么回事啊！</p><p>「哎呀，我并不讨厌态度强硬的雄性呢。」</p><p>只见呼吸粗重的半兽人双眼湿润地盯着我看。</p><p>一股凉意窜过我的背部。</p><p>「这、这、这、这是……」</p><p>过度惊讶甚至让我无法顺利说话。</p><p>「你是要说婚约吗？真是急躁呢。首、先，就从确认身体的匹配度开始吧。」（注：「这是」跟「婚约」的日文发音开头相同）</p><p>「咿咿咿咿咿咿咿！」</p><p>我连忙拉开距离，以坐倒在地的状态向后退。</p><p>必、必须快点逃走！所谓的半兽人是只有雌性的种族，她们只要看到男人就会出手，等彻底榨干他后就宰掉，对男人来说是最糟糕最凶恶的种族。</p><p>我在酒吧听了无数次被半兽人抓住的男人下场有多么惨烈。</p><p>即使再狼狈，我都必须离开这里才行！</p><p>但腰部使不上力的我无法起身，即使想要就这样拉开距离，背后却撞上了某样东西。</p><p>「哎呀，小哥，你这是要去哪里？」</p><p>骗、骗人，这个声音是……</p><p>虽然我的本能嘶吼着要我别去面对，但是我却不得不回头。</p><p>没错，那可能是我的错觉。我只是单纯撞倒障碍物，那道声音则是幻听。</p><p>我缓缓地回过头……发现自己撞上的不是岩石或树木，而是有着满身肥肉的半兽人。</p><p>而且还有三只。</p><p>「呀啊啊啊啊啊啊啊！」</p><p>「就来好好享受一番吧，今晚可不会让你睡喔，呼——呼——！」</p><p>「今天的我非常粗暴喔！来把这身碍事的衣服撕破吧！」</p><p>「不、不要啊，快住手！不要那么粗暴啊！」</p><p>「我最少想生五十个宝宝，爸爸要加油喔。就当作招呼，要快点跟你的小弟亲一下才行！」</p><p>「不、不用那么客气！」</p><p>虽然我打算转身逃跑，却被一开始那只半兽人绕到背后紧紧抓住肩膀。</p><p>那几张喘着气流着口水的嘴巴正缓缓地、缓缓地朝我这里……</p><p>「有、有没有人在啊啊！快来救救我啊啊啊！」</p><p>在我俯瞰的视线前方，有个在睡梦中发出惨叫并痛苦地打磙的男人。</p><p>一旁的萝莉梦魔则是举起手让男人作恶梦。</p><p>「虽然我有给了一些演出的建议，不过还是有些吓人耶。」</p><p>这个欺骗我的伙伴，还打算对琳恩出手的男人，似乎正在梦中陷入惨不忍赌的状况。</p><p>只见他疯狂地摇头，仿佛正在抗拒某些东西。</p><p>「嘿嘿嘿，这样似乎有点有趣呢。」</p><p>面露微笑的萝莉梦魔好可怕，这家伙该不会觉醒了什么奇怪的偏好吧……从今以后还是对她温柔一点，要是她拿梦境当人质我根本毫无抵抗能力。</p><p>「真没想到这个人竟然是犯罪集团的成员。这就是所谓的人不可貌相吧。」</p><p>琳恩双手抱胸一脸严肃地表示。</p><p>我们趁这个家伙睡觉时悄悄与伙伴会合，虽然他们刚见到我时相当惊讶，不过在我说明情况后马上就表示理解。</p><p>正确来说他们并没有相信我，却愿意相信萝莉梦魔及头盔男的说明！这还能算是伙伴吗！</p><p>「达斯特，多亏你我们才能得救，谢了。」</p><p>「真是令我刮目相看啊，你真是在关键时刻特别厉害的男人呢。」</p><p>泰勒和奇斯都非常直率地赞赏我。</p><p>不过最重要的琳恩却只是双手抱胸紧盯着我看。</p><p>「喂喂，琳恩小姐，你就没有什么话要对我说吗？」</p><p>「啊呜。就、就是那个啦。谢谢你救了我们！」</p><p>虽然是类似怒吼的道谢，不过我知道那只是在掩饰她的害羞。</p><p>所以我——</p><p>「嗯，可要好好感谢我喔。」</p><p>便露出笑容回应她。</p><h3 id="_8" tabindex="-1"><a class="header-anchor" href="#_8"><span>8</span></a></h3><p>由于今天时间已经太晚，我们决定明天才回城镇。现在是所有人都已经睡着的深夜。</p><p>我因为猜拳输了，正独自在这个时间点守夜。原本是要跟琳恩一起把守，不过我没有去叫醒她，而是独自一人望着营火。</p><p>伙伴们和萝莉梦魔都睡得相当舒服。由于头盔男连睡觉时都带着头盔，所以我不清楚他睡着时的表情为何。</p><p>至于受到半兽人乐园彻底摧残过意志的男人，则是被绳索绑起来倒在地上。</p><p>目前这里还醒着的就只有我——以及另一个人啊。</p><p>我起身拍了拍沾在屁股上的尘土。</p><p>「借用一下。」</p><p>我捡起睡着的头盔男放在身旁的长枪。</p><p>从斜后方的大树旁边走过，朝黑暗中不断前进。</p><p>直到走到较宽阔的地方后，我眯起了眼睛。</p><p>「你在那边吧？因为不想吵醒他们，我才会把你引来这里，快现身吧。」</p><p>「哦，竟然有发现我啊，原本还以为你只是个喽啰呢。」</p><p>一名全身黑衣的男人从树木的阴影中现身。他连嘴巴及头顶都用黑布包起，完全与黑暗融为一体。</p><p>其实在用陷阱将那群人一网打尽时，我就隐约感觉到这家伙的视线了。从那之后他似乎就一路跟在后面。</p><p>光是从这名男子的气息及脚步来看，很快就能理解这家伙非常危险，他的实力与先前那群人不在同一个水平。这家伙应该是真正的杀手吧？</p><p>巴尼尔老大口中的不要大意肯定就是指这个家伙。</p><p>「你都放出这么强烈的杀气了，怎么可能会没注意到。我不知道你是谁，不过应该是受雇于那些家伙吧？他们的头目都已经进去拘留所了，即使如此你还是要打吗？」</p><p>「我毕竟受雇于他们，也有先收到报酬了，所以一定要完成货品搬运的任务。」</p><p>「你明明在干见不得光的工作，个性却是如此认真啊。这种不知变通的生活方式只会让自己吃亏喔……就像以前的我一样。」</p><p>「谢谢你的忠告。寒暄就到此为止，我要来完成工作了。」</p><p>面对这名干劲十足的对手，我将视线落在手中的长枪并且紧紧握住它。</p>`,447),e(f,{src:`/images/E1/03.avif`,alt:`插图`,width:`845`,height:`1200`}),s[15]||=a(`<p>毕竟过去可是挥舞长枪到近乎厌烦的程度，才会直到现在双手都还记得啊……</p><p>「如果是为了保护重要的人，你应该会原谅我吧……」</p><p>脑中突然浮现出长相和琳恩很类似，个性却自我中心又过度奔放的那一位的面容。</p><p>我将指头放在道别的那一天作为饯别礼所得到的剑上，重重叹了口气。</p><p>——请让我用一下长枪吧。</p><p>我轻轻弯下膝盖，压低重心摆出架势。</p><p>黑衣男踏着轻盈的步伐从正面冲了上来。</p><p>他的双手各握着一把短剑，看来是二刀流。</p><p>我将枪尖朝那个一口气拉近距离的家伙刺去。然而他却在千钧一发之际躲开，就这样冲向我的怀中。</p><p>黑暗中画出两条反射着月光的银色光芒，其轨迹正直直朝着我的脖子划去。</p><p>我将上半身后仰躲过刀刃，接着顺势来了一记后空翻。</p><p>在落地之前直接于空中挥枪横扫，黑衣男立刻往后方跳开。</p><p>「真是了得。我一直有在暗中观察，看来平常那副模样只是你的伪装呢。」</p><p>「没这回事，倒不如说现在这个样子可能才是我的伪装喔。」</p><p>在耍弄嘴皮子的同时，我也正眼紧盯着对方。</p><p>「不过经过刚刚的攻防后，我已经看穿你的实力了。下一击就解决你！」</p><p>男子自信满满地如此宣言，我则是在他往我这边跨出第一步的同时，将长枪掉头半圈用枪锥对准敌人——拿出真本事，向前放出突刺。</p><p>这一击划破空气，轻松就击中对手的腹部。</p><p>黑衣男惊讶地瞪大了眼睛，在低头确认刺入腹部的长枪后，无声无息地瘫倒在地。</p><p>「抱歉啦，太久没碰我都忘记要怎么用，所以花了点时间啊。」</p><h2 id="尾声" tabindex="-1"><a class="header-anchor" href="#尾声"><span>尾声</span></a></h2><p>「不但一毛艾莉丝都没赚到，还连那间店的接待都泡汤了，唉……」</p><p>结果我在这次的事件当中完全没有捞到好处。</p><p>其实那群人虽然实行了好几次绑票，但都只关了半天就被释放了。这是因为他们不但没有触碰被绑架的女孩，还用如同公主的待遇服侍目标，所以被害者最后全都撤案。</p><p>再加上这群人的靠山好像是某个名门贵族，因此警察也不打算对外公开，既然没有发布通缉，自然也不会有奖金。</p><p>至于受那群人雇用，似乎是杀手的男人也在不知不觉中消失……只要不会再跟他扯上关系就没差啦。那种死板的男人在战斗后应该会认为自己已经尽到义务，所以不会再来找麻烦了。</p><p>伙伴们全都平安无事当然很好，却就只有我亏大了。</p><p>「亏我还对你稍微刮目相看了，你为什么老是这样啊……」</p><p>看到我整个人趴在公会平时使用的桌子上，坐在对面的琳恩嘴角一阵扭曲。虽然看起来似乎很受不了我，不过感觉她并非真心这么觉得，比较像是在苦笑。</p><p>「虽然我也很感谢达斯特，不过还得跟当时在场的另外两个人好好道谢才行。」</p><p>泰勒在这种地方实在相当认真呢。不过如果跟伙伴们介绍那两个人，只会让事情变麻烦。毕竟他们可是梦魔及贵族啊。</p><p>「那个孩子我也认识，不过戴头盔的人究竟是谁啊，达斯特？」</p><p>和我同样是常客的奇斯已经看出萝莉梦魔的身分了，至于头盔男……晚点再告诉奇斯一个人应该无妨吧。</p><p>「下次有机会再告诉你。」</p><p>「不过那个可爱的女孩好厉害喔。我从来没听说过有精神系的操梦魔法呢，下次不知道能不能请她教我。」</p><p>我在解释萝莉梦魔身分时，给了她能使用特殊魔法的设定。毕竟要是不对琳恩隐瞒她的真实身分，我肯定会吃不完兜着走。</p><p>「啊，对了！不然找她加入我们的小队如何？能增加女孩子我也会很高兴，而且感觉你们感情很好呢。」</p><p>「等等，这个就……」</p><p>如果真的做出这种事，她的真实身分将会曝光，请容我严正拒绝。</p><p>「为什么啦，这样不是很好吗！这么说来，达斯特这种人怎么会认识那么可爱的女孩啊？难道说你抓住人家的弱点……」</p><p>「才不是呢！是因为我先前帮她的职场解决了一些问题才认识。跟小混混有关的事啦。」</p><p>「你在那方面的确是很管用啦。」</p><p>她被这种理由说服让我感觉有些不爽，不过现在先忍耐吧。</p><p>「比起这种事情，我们快去接任务吧。趁我还没有染指真正的犯罪前……」</p><p>「这听起来一点都不像是开玩笑，好恐怖喔。」</p><p>我怎么可能认真想这么做啊……其实是有一点。</p><p>目前我的总资产为负，要是再不想点办法……</p><p>「啊，要是你没钱的话，就先用这个吧。」</p><p>泰勒咚的一声将装满东西的袋子放到桌上。</p><p>难道说这个袋子里装满了钱？</p><p>「你有什么企图？」</p><p>「亏你平常满口喊着要借钱，结果别人直接拿钱出来又开始警戒。这是公会发的赔偿金。说是没能看穿对方是罪犯就介绍给我们的赔礼。」</p><p>泰勒用大拇指朝公会柜台的方向指了指，跟我们视线交错的露娜也深深低头道歉。</p><p>「里面装了我们所有人的份，全部都给达斯特吧。你姑且算是我们的救命恩人。」</p><p>「别看我们这样，我们其实很感激你啦。」</p><p>「总之就是这样。」</p><p>这群伙伴真是不够坦率。这时候说「太见外了」并拒绝收下肯定会很帅，不过我的信条就是来者不拒。</p><p>「谢啦，等我把欠债还清如果还有剩，就拿来喝个痛快吧！」</p><p>「刚刚不是说要去接委托吗？受不了，真拿你没办法。我今天就陪你吧。」</p><p>「真是好主意，我可不会客气喔！」</p><p>「对了，就当成是纪念我们重新结成队伍，来大喝一顿吧！」</p><p>伙伴果然就该是如此。</p><p>只有能够同甘共苦的人，才是真正的伙伴。</p><p>「好，就来个不醉不归吧！把酒都拿上来！」</p><p>「看来你赚了不少呢，就让吾也来参一脚吧。」</p><p>当我伸出手准备叫住附近的店员时，一只戴着白手套的手突然从旁抓住我。</p><p>到底是哪个没礼貌的家伙，敢在我心情正好的时候跑来打扰啊？</p><p>我才刚抬起头，就看到一张熟悉的脸庞。</p><p>「咦？巴尼尔老大？你又来打工吗？」</p><p>之前老大在公会的角落开设谘询服务时大受好评，所以应该是如此吧。</p><p>「吾的确是如此打算，但已经没必要这么做了。那么，快把购买魔道具的钱交出来吧。」</p><p>「咦？老大，你在说什么啊？你先前不是说那个魔道具要免费给我吗？」</p><p>「吾的确这么说过……『一个』的话可以免费。」</p><p>巴尼尔老大抓住装满钱的袋子说着「呼哈哈哈哈哈！汝的负面情感真是美味！」就走了。</p><p>我完全忘了这件事……这么说来，他一开始的确说一个的话免费……</p><p>「我的酒钱……钱……」</p><p>由于太过震惊，甚至忘了请老大留一些给我。</p><p>我茫然地望着伙伴，他们则是一脸同情地将手放上我的肩膀。</p><p>「「「去接委托吧。」」」</p><p>不要给我异口同声说话。</p><p>「啊啊！可恶啊啊啊！为什么钱总是要离我而去！」</p><p>「大概是因为钱很讨厌你吧。好啦，快点去选要接的委托吧。我们会陪你一起去啦……毕竟是伙伴啊。」</p><p>琳恩有些害羞但语气强硬地如此说道，而在她背后的奇斯和泰勒也用力地点头。</p><p>没办法了，今天也努力工作赚钱吧。</p><p>「啊！因为老大把所有的钱都抢走，今天到期的欠债我一毛都还不了！我们快点接下委托远离这座城镇吧！」</p><p>我急急忙忙挑了合适的委托并走出公会，就看到阳光从万里无云的天空洒落。</p><p>今天也努力拉开嗓门拉客的店员。</p><p>正准备出发去冒险的熟识冒险者。</p><p>还有看到我就做出警戒的警察。</p><p>「真是让人不爽的大晴天耶，喂！」</p><p>「不要迁怒天气啦！唉……那天晚上你明明就很帅气啊。」</p><p>我下意识转过头，望向在我耳边讲悄悄话的琳恩。</p><p>琳恩那如同露出恶作剧成功的孩子般咧嘴笑着的模样，让我不禁看傻了。</p><p>「难道说你那天晚上有醒来吗？」</p><p>「哎呀，谁知道呢？」</p><p>琳恩只给了个暧昧的回应，就踏着小跳步向前跑了出去。</p><p>我与奇斯、泰勒各对望了一眼后，就耸耸肩追了上去。</p><p>看来今天也会是吵吵闹闹又快乐的一天呢。</p><h2 id="后记" tabindex="-1"><a class="header-anchor" href="#后记"><span>后记</span></a></h2><p>大家好，我是这次负责为这本《让笨蛋登上舞台吧！》执笔的昼熊。</p><p>众多买下这本书的读者们应该都是《美好世界》的粉丝，同时也抱持着昼熊这个人是谁的疑问吧？我是承蒙Sneaker文库青睐，以《转生成自动贩卖机的我今天也在迷宫徘徊》一作出道一年多的新人作家。</p><p>这样的我是在今年年初，被责任编辑M氏问道：「要不要写写看《美好世界》的外传？」由于我打从网络连载时期就是《美好世界》的粉丝，所以二话不说就回答：「真的可以吗，拜托你了！」但是等我挂上电话过了一段时间冷静下来后……才终于发现这下事情闹大了，压力也跟着接踵而来。</p><p>要负责撰写超人气作品的官方外传——虽然对这个现实感到胆怯，但我仍选择以一名粉丝的身分来撰写本作。虽然这只是我个人的想法，不过要担任官方外传的作者，至少必须是真心喜欢原作。我认为这是最基本的条件。而我可以抬头挺胸表示自己完全符合，毕竟我是真心喜欢《美好世界》啊！</p><p>不只是要以作家的身分完成工作，也不忘记以粉丝角度撰写，如果真的能够做到这点，肯定能写出最有趣的作品吧。不是借助《美好世界》的世界观及角色来活跃自己的原创角色，而是想看见更多在本篇另一侧的故事，以及配角们的活跃场景。这也是一介粉丝的我的想望。</p><p>能够顺利写出这本书，我得好好感谢的人就跟山一样多。</p><p>首先是暁なつめ老师。真的非常感谢您愿意将角色都充满魅力的《美好世界》交给我写外传！如果要在这里用言语来表达我对作品的迷恋及感谢的心情，那后记可能要再增加十页以上，所以请让我另外找机会好好向您打声招呼。</p><p>光是参考三嶋くろね老师的角色图，就让我的想像无边无尽，也得以让达斯特他们能开心地大闹一番。</p><p>负责为本作绘制美丽插图的忧姬はぐれ老师。谢谢您这么棒的图，达克妮丝超赞的……</p><p>还有《美好世界》动画的相关人士们。执笔时角色们能够活生生在我脑中动作，负责帮角色配音的各位声优，你们的声音也一直在我的脑中不断重播。</p><p>以及编辑部的各位。总是与我交换意见责编M氏，还有与本书相关的各位。</p><p>最后是拿起这本书阅读到最后的各位读者，真的非常感谢大家！</p><div style="text-align:right;"><p>昼熊</p></div>`,112),e(f,{src:`/images/E1/12.avif`,alt:`后记插图`,width:`850`,height:`1257`})])}var u=o(c,[[`render`,l]]);export{s as _pageData,u as default};